/** 会期の先頭の年から初日を読む。実在しない日付は繰り上げない。 */
function _AssignNag_parseFirstDate(text, defaultYear) {
  var value = String(text || '').replace(/[\s　]+/g, '');
  var year = /\d{4}/.exec(value);
  var m = year ? /^(\d{4})(?:年|\/|-)(\d{1,2})(?:月|\/|-)(\d{1,2})(?!\d)/.exec(value.slice(year.index)) : null;
  if (!m) {
    // 年の無い表記（4/17〜4/19）は defaultYear が渡されたときだけそれを当てる
    if (defaultYear == null) return null;
    m = /^(\d{1,2})(?:月|\/|-)(\d{1,2})(?!\d)/.exec(value);
    if (!m) return null;
    m = [m[0], String(defaultYear), m[1], m[2]];
  }
  var date = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  return date.getUTCFullYear() === Number(m[1]) && date.getUTCMonth() === Number(m[2]) - 1 &&
    date.getUTCDate() === Number(m[3]) ? date : null;
}

/** row8 のゆらぎ（制作P：百瀬かなう / P百瀬かなう / 制作P百瀬かなう）から氏名を取り出す。 */
function _AssignNag_producerName(value) {
  var base = _AssignSheet_producerName(value);
  var stripped = String(base).replace(/^[\s　]*(?:制作)?[PD][\s　]*(?=[぀-ヿ一-鿿])/, '')
    .replace(/^[\s　]+|[\s　]+$/g, '');
  return stripped || base;
}

function _AssignNag_isAssignRow(cells) {
  return String(cells.subCategory || '').indexOf('アサイン') !== -1 && String(cells.exclude || '').trim() !== '不要';
}

function _AssignNag_evaluateCase(params) {
  var incomplete = params.assignRows.filter(function (row) {
    var progress = String(row.progress || '').trim();
    return progress !== '済' && progress !== '不要';
  }).map(function (row) { return row.item; });
  var days = params.eventFirstDate ? Math.floor((params.eventFirstDate - params.today) / 86400000) : null;
  if (days !== null && !isFinite(days)) days = null;
  return { status: days === null ? 'skipped' : days >= 0 && days <= 21 ? 'window' : 'outside',
    daysLeft: days, incomplete: incomplete };
}

function _AssignNag_buildText(params) {
  var lines = [];
  if (params.fallback) {
    var names = params.items.map(function (item) { return item.producer || '担当者未設定'; })
      .filter(function (name, index, all) { return all.indexOf(name) === index; });
    lines.push('※この案件の制作P（' + names.join(' / ') + '）のDiscordが未同定です。取り次ぎをお願いします。');
  }
  lines.push('⏰ アサイン未完了リマインダー（イベント3週間前の毎日通知・自動）');
  params.items.forEach(function (item) {
    lines.push('・' + item.clientName + ' / ' + item.caseName + '（会期初日 ' + item.eventFirstDateText + '・あと' + item.daysLeft + '日）');
    lines.push('  未完了: ' + item.incomplete.join(' / '));
  });
  lines.push('対応が済んだら進捗表の該当行を「済」にしてください。');
  lines.push('https://docs.google.com/a/orgiast.jp/spreadsheets/d/1t6eMvbPIu17m7hbv6foJcvd-fXrJkZqrePb8P6njxGI/edit');
  return lines.join('\n').slice(0, 1900);
}

/** count は通知対象案件数。シートの読み取りは一括で1回、書き込みは行わない。 */
function AssignNag_nagPending(opts) {
  opts = opts || {};
  var values = SpreadsheetApp.openById('1t6eMvbPIu17m7hbv6foJcvd-fXrJkZqrePb8P6njxGI')
    .getSheetByName('task').getDataRange().getDisplayValues();
  var todayText = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy/MM/dd');
  var today = _AssignNag_parseFirstDate(todayText);
  var defaultYear = Number(todayText.slice(0, 4));
  var assignIndices = [];
  for (var r = 11; r < values.length; r++) {
    if (_AssignNag_isAssignRow({ subCategory: values[r][2], exclude: values[r][4] })) assignIndices.push(r);
  }
  var items = [], skipped = [], groups = Object.create(null);
  var headers = values[1] || [], last = -1;
  for (var c = 12; c < headers.length; c += 3) {
    if (String(headers[c] || '').trim()) last = c;
  }
  for (var col = 12; col <= last; col += 3) {
    if (!String(headers[col] || '').trim()) continue;
    var eventDate = _AssignNag_parseFirstDate((values[4] || [])[col], defaultYear);
    var evaluation = _AssignNag_evaluateCase({ today: today, eventFirstDate: eventDate,
      assignRows: assignIndices.map(function (row) { return { item: values[row][3], progress: values[row][col + 2] }; }) });
    if (evaluation.status === 'skipped') {
      skipped.push({ caseName: headers[col], masterCol: col + 1, reason: '会期初日を解析できません' });
      continue;
    }
    if (evaluation.status !== 'window' || !evaluation.incomplete.length) continue;
    var owners = values[7] || [];
    var producer = _AssignNag_producerName(owners[col]) || _AssignNag_producerName(owners[col + 1]) || '担当者未設定';
    var item = { producer: producer, clientName: (values[0] || [])[col] || '', caseName: headers[col],
      daysLeft: evaluation.daysLeft, eventFirstDateText: Utilities.formatDate(eventDate, 'UTC', 'yyyy/MM/dd'),
      incomplete: evaluation.incomplete };
    items.push(item);
    if (!groups[producer]) groups[producer] = [];
    groups[producer].push(item);
  }
  if (!items.length) return { ok: true, sent: false, count: 0, items: [], texts: [], results: [], skipped: skipped };
  var props = PropertiesService.getScriptProperties();
  var userMap;
  try { userMap = JSON.parse(props.getProperty('ASSIGN_NAG_USER_MAP') || '{}'); } catch (e) { userMap = {}; }
  if (!userMap || typeof userMap !== 'object' || Array.isArray(userMap)) userMap = {};
  var token = props.getProperty('DISCORD_BOT_TOKEN');
  var fallbackId = props.getProperty('DISCORD_DM_USER_ID');
  var texts = [], results = [];
  Object.keys(groups).forEach(function (producer) {
    var mappedId = Object.prototype.hasOwnProperty.call(userMap, producer) ? userMap[producer] : null;
    var fallback = typeof mappedId !== 'string' || !mappedId.trim();
    var userId = fallback ? fallbackId : mappedId.trim();
    var text = _AssignNag_buildText({ todayText: todayText, items: groups[producer], fallback: !!fallback });
    texts.push(text);
    if (opts.dryRun === true) return;
    var result = { producer: producer, userId: userId || '', via: fallback ? 'fallback' : 'map', ok: false };
    if (!token || !userId) result.reason = 'DISCORD_BOT_TOKEN または送信先ユーザーIDが未設定';
    else {
      try {
        result.ok = _FeedbackRelay_postDm(token, userId, text) === true;
        if (!result.ok) result.reason = 'Discord DM送信失敗';
      } catch (e) { result.reason = 'Discord DM送信時に例外が発生'; }
    }
    results.push(result);
  });
  if (opts.dryRun === true) return { ok: true, count: items.length, items: items, texts: texts, sent: false, skipped: skipped };
  return { ok: results.every(function (r) { return r.ok; }), count: items.length,
    sent: results.some(function (r) { return r.ok; }), results: results, skipped: skipped };
}

function AssignNag_installTrigger() {
  var removed = 0;
  ScriptApp.getProjectTriggers().forEach(function (trigger) {
    if (trigger.getHandlerFunction() === 'AssignNag_nagPending') {
      ScriptApp.deleteTrigger(trigger);
      removed++;
    }
  });
  ScriptApp.newTrigger('AssignNag_nagPending').timeBased().atHour(9).everyDays(1).create();
  return { ok: true, removed: removed, created: 1 };
}

function AssignNag_testDm() {
  var props = PropertiesService.getScriptProperties();
  var token = props.getProperty('DISCORD_BOT_TOKEN'), userId = props.getProperty('DISCORD_DM_USER_ID');
  if (!token || !userId) return { ok: false, sent: false, reason: 'DISCORD_BOT_TOKEN または DISCORD_DM_USER_ID が未設定' };
  try {
    var ok = _FeedbackRelay_postDm(token, userId, '疎通テスト（無視してください）') === true;
    return ok ? { ok: true, sent: true } : { ok: false, sent: false, reason: 'Discord DM送信失敗' };
  } catch (e) { return { ok: false, sent: false, reason: 'Discord DM送信時に例外が発生' }; }
}

/**
 * 既存タスク管理表「正式：reブースタスク進捗管理表」(SS 1t6eMvbPIu17m7hbv6foJcvd-fXrJkZqrePb8P6njxGI / sheet "task")
 * からアクティブ案件 21 件を 案件一覧 へ一括取り込み。
 *
 * 元シート構造（wide format）:
 *   - 1 案件 = 3 列ブロック（名前 / 日付 / 進捗）
 *   - ブロック先頭列 = M(13), P(16), S(19), V(22), ... 3 列刻みで横並び
 *   - 行 6: ｸﾗｲｱﾝﾄ
 *   - 行 7: 展示会名
 *   - 行 8: 地域/会場
 *   - 行 9: 設営日
 *   - 行 10: 開催日程
 *   - 行 11: 実計/見積（HYPERLINK の display: "実施計画書（...）" / formula: =HYPERLINK(url, label)）
 *   - 行 13: 担当（"制作P：xxx" 等）
 *
 * 仕様:
 *   - HYPERLINK formula から実施計画書 URL を抽出
 *   - URL が空（"実施計画書URL" 等の placeholder）の案件は skip して結果に skipped 配列で報告
 *   - 重複（既に zissiId が案件一覧 K列にあるもの）は skip
 */

const _BULK_IMPORT_SS_ID = '1t6eMvbPIu17m7hbv6foJcvd-fXrJkZqrePb8P6njxGI';
const _BULK_IMPORT_SHEET = 'task';
const _BULK_IMPORT_FIRST_COL = 13; // M
const _BULK_IMPORT_LAST_COL = 75;  // 21 case blocks (13 + 3*20 = 73 for last name col, +2 for date+progress = 75)
const _BULK_IMPORT_ROW_CLIENT = 5;
const _BULK_IMPORT_ROW_EVENT = 6;
const _BULK_IMPORT_ROW_VENUE = 7;
const _BULK_IMPORT_ROW_SETUP = 8;
const _BULK_IMPORT_ROW_PERIOD = 9;
const _BULK_IMPORT_ROW_ZISSI = 10;  // 実計/見積 行（A1 ベースで 11 行目 = row 10 0-indexed... wait）

// 注意: スプレッドシート読みは 1-indexed 行 = ヘッダー1行目 を 1 とカウント
//       上のサブエージェント分析では「行5=クライアント, 行11=実計/見積, 行13=担当」
//       これは 1-indexed 表記。GAS API も 1-indexed なのでそのまま使う。

// 実際のレイアウト (1-indexed):
// row 1: クライアント, row 2: 展示会名, row 3: 地域/会場, row 4: 設営日,
// row 5: 開催日程, row 6: 実計/見積 (cell hyperlink), row 7: 展示会HP,
// row 8: 担当, row 9: 次MTG, row 10: 前回済タスク数, row 11: 残タスク/済/不要
const _BULK_IMPORT_R_CLIENT = 1;
const _BULK_IMPORT_R_EVENT = 2;
const _BULK_IMPORT_R_VENUE = 3;
const _BULK_IMPORT_R_SETUP = 4;
const _BULK_IMPORT_R_PERIOD = 5;
const _BULK_IMPORT_R_ZISSI = 6;
const _BULK_IMPORT_R_OWNER = 8;

/**
 * 一括取り込み実行。
 * @return {object} { totalBlocks, imported, duplicates, skipped, errors, summary }
 */
function BulkImportFromTaskMgmt_run(opts) {
  opts = opts || {};
  const ss = SpreadsheetApp.openById(_BULK_IMPORT_SS_ID);
  const sheet = ss.getSheetByName(_BULK_IMPORT_SHEET);
  if (!sheet) throw new Error('sheet not found: ' + _BULK_IMPORT_SHEET);

  // 各案件の名前列 = 13, 16, 19, ... シートの最終列まで動的に検出
  // (2026-08-01: 22案件目以降がシート右側に追加されるようになったため 21 固定を廃止)
  const sheetLastCol = sheet.getLastColumn();
  const blocks = [];
  for (let col = 13; col + 2 <= sheetLastCol; col += 3) {
    blocks.push(col);
  }
  const lastCol = blocks[blocks.length - 1];

  // 一括 read（値）+ 行 6（実計/見積）は richTextValue / formula 両方確認
  const valuesRange = sheet.getRange(_BULK_IMPORT_R_CLIENT, 1, _BULK_IMPORT_R_OWNER - _BULK_IMPORT_R_CLIENT + 1, lastCol);
  const values = valuesRange.getValues();
  const zissiRange = sheet.getRange(_BULK_IMPORT_R_ZISSI, 1, 1, lastCol);
  const zissiFormulasRow = zissiRange.getFormulas()[0];
  const zissiRichTextRow = zissiRange.getRichTextValues()[0];

  const imported = [];
  const duplicates = [];
  const skipped = [];
  const errors = [];

  // values は 9 行（行5〜13）。idx で参照する: 0=行5, 1=行6, ...
  function row(r) { return values[r - _BULK_IMPORT_R_CLIENT]; }

  blocks.forEach(function (col1) {
    // col1 は 1-indexed の名前列番号。Sheets配列は 0-indexed なので col1-1
    const c = col1 - 1;
    const clientName = String((row(_BULK_IMPORT_R_CLIENT)[c] || '')).trim();
    const eventName = String((row(_BULK_IMPORT_R_EVENT)[c] || '')).trim();
    const venue = String((row(_BULK_IMPORT_R_VENUE)[c] || '')).trim();
    const setupDate = row(_BULK_IMPORT_R_SETUP)[c];
    const periodCell = String((row(_BULK_IMPORT_R_PERIOD)[c] || '')).trim();
    const ownerCell = String((row(_BULK_IMPORT_R_OWNER)[c] || '')).trim();
    const zissiFormula = String(zissiFormulasRow[c] || '');
    const zissiRich = zissiRichTextRow[c];

    // クライアント名 or 展示会名 が空のブロックは skip
    if (!clientName && !eventName) {
      skipped.push({ col: col1, reason: 'empty block' });
      return;
    }

    // URL 抽出: (1) HYPERLINK formula, (2) cell hyperlink (richTextValue.getLinkUrl),
    //          (2b) セル文字列内の plain URL (https://docs.google.com/spreadsheets/d/...)
    //          (3) フォールバック: タイトル文字列から案件コード抽出 → Drive 検索
    let zissiUrl = '';
    const fm = zissiFormula.match(/HYPERLINK\(\s*["']([^"']+)["']/i);
    if (fm) {
      zissiUrl = fm[1];
    } else if (zissiRich) {
      const linkUrl = zissiRich.getLinkUrl();
      if (linkUrl) {
        zissiUrl = linkUrl;
      } else {
        const runs = zissiRich.getRuns();
        for (let k = 0; k < runs.length; k++) {
          const u = runs[k].getLinkUrl();
          if (u) { zissiUrl = u; break; }
        }
      }
    }
    // (2b) セル文字列内の plain URL を拾う（HYPERLINK 化されてないが URL が含まれている場合）
    const cellTextForUrl = String(zissiRich ? zissiRich.getText() : '') ||
      String(sheet.getRange(_BULK_IMPORT_R_ZISSI, col1).getValue() || '');
    if (!zissiUrl) {
      const urlMatch = cellTextForUrl.match(/https?:\/\/docs\.google\.com\/(?:a\/[^/]+\/)?spreadsheets\/d\/[A-Za-z0-9_-]+[^\s)]*/);
      if (urlMatch) zissiUrl = urlMatch[0];
    }

    // (2c) 案件一覧マスター (14RC6...) の D列を参照
    //      master text 内のコード (例: 251103PDR) を 案件一覧マスター I列 で完全一致検索
    //      → 一致したら同じ行の D列 (実施計画URL) を採用
    //      コード一致が無く clientName で 1 件に絞れたら採用
    if (!zissiUrl) {
      const codeMatch = cellTextForUrl.match(/[（(](\d{6}[A-Z]{2,5})[_\s]/);
      const codeFromText = codeMatch ? codeMatch[1] : '';
      const url = _Bulk_lookupKessanMaster(codeFromText, clientName);
      if (url) zissiUrl = url;
    }
    // (3) タイトル文字列から案件コード (例: 260408TRS) を抽出 → Drive で検索
    if (!zissiUrl) {
      const cellText = String(zissiRich ? zissiRich.getText() : '') ||
        String(sheet.getRange(_BULK_IMPORT_R_ZISSI, col1).getValue() || '');
      const codeMatch = cellText.match(/[（(](\d{6}[A-Z]{2,5})[_\s]/);
      if (codeMatch) {
        const code = codeMatch[1];
        try {
          const it = DriveApp.searchFiles(
            "title contains '" + code + "' and title contains '実施計画書' and " +
            "mimeType = 'application/vnd.google-apps.spreadsheet' and trashed = false"
          );
          while (it.hasNext()) {
            const f = it.next();
            if (f.getName().indexOf('提出') >= 0) continue;
            zissiUrl = f.getUrl();
            break;
          }
        } catch (e) { /* skip */ }
      }
    }

    // (4) クライアント名 + イベント名キーワード で Drive 検索（eventKey 必須）
    //     master の zissi コードが古い/不一致でも、ファイル名でマッチさせる
    //     ※ clientName だけ一致のファイルは別案件の可能性が高いので採用しない
    if (!zissiUrl && clientName) {
      const clientKey = clientName.replace(/^株式会社|株式会社$|^（株）|（株）$/g, '').trim();
      // eventName から最初の意味のあるキーワードを抽出（記号/年号/共通語を除外）
      const eventKeys = _Bulk_extractEventKeywords(eventName);
      if (clientKey && eventKeys.length > 0) {
        try {
          const escClient = clientKey.replace(/'/g, '\\\'');
          const q = "title contains '実施計画書' and title contains '" + escClient +
            "' and mimeType = 'application/vnd.google-apps.spreadsheet' and trashed = false";
          const it = DriveApp.searchFiles(q);
          const matches = [];
          while (it.hasNext()) {
            const f = it.next();
            const name = f.getName();
            if (name.indexOf('コピー') >= 0) continue;
            if (name.indexOf('提出') >= 0) continue;
            if (/(テスト|サンプル|テンプレート|template)/i.test(name)) continue;
            // eventKeys のいずれかが含まれるファイルだけ採用
            const hit = eventKeys.some(function (k) { return name.indexOf(k) >= 0; });
            if (!hit) continue;
            matches.push({ file: f, modifiedTime: f.getLastUpdated().getTime() });
          }
          if (matches.length > 0) {
            matches.sort(function (a, b) { return b.modifiedTime - a.modifiedTime; });
            zissiUrl = matches[0].file.getUrl();
          }
        } catch (e) { /* skip */ }
      }
    }

    if (!zissiUrl) {
      skipped.push({
        col: col1,
        clientName: clientName,
        eventName: eventName,
        reason: '実施計画書 URL なし（行11 が HYPERLINK でない）'
      });
      return;
    }

    // 開催期間パース: "2025年10月20日〜22日" → start=2025/10/20, end=2025/10/22
    const period = _Bulk_parsePeriod(periodCell);
    const startDate = period.start || (setupDate instanceof Date ? Utilities.formatDate(setupDate, 'Asia/Tokyo', 'yyyy/MM/dd') : '');
    const endDate = period.end || '';

    const caseName = eventName + (venue ? ' / ' + venue : '');

    // masterCol-based 重複チェック: 同じ (masterSsId, masterCol) で既存ケースがあれば skip
    //   - kessan lookup などで zissi URL が以前の取込時と変わっても、case を二重作成しないため
    const existingByMasterCol = _Bulk_findCaseByMasterCol(_BULK_IMPORT_SS_ID, col1);
    if (existingByMasterCol) {
      duplicates.push({ col: col1, clientName, eventName, existingCaseId: existingByMasterCol.caseId, reason: 'same masterCol' });
      return;
    }

    try {
      const result = CaseList_importFromZissiUrl(zissiUrl, {
        clientName: clientName,
        caseName: caseName,
        startDate: startDate,
        endDate: endDate,
        phase: 2,
        masterSsId: _BULK_IMPORT_SS_ID,
        masterCol: col1
      });
      if (result.duplicate) {
        duplicates.push({ col: col1, clientName, eventName, existingCaseId: result.caseId });
      } else {
        imported.push({ col: col1, caseId: result.caseId, clientName, eventName, startDate, endDate, zissiUrl });
      }
    } catch (e) {
      errors.push({ col: col1, clientName, eventName, error: e.message });
    }
  });

  return {
    totalBlocks: blocks.length,
    imported: imported,
    duplicates: duplicates,
    skipped: skipped,
    errors: errors,
    summary: {
      importedCount: imported.length,
      duplicateCount: duplicates.length,
      skippedCount: skipped.length,
      errorCount: errors.length
    }
  };
}

/**
 * 毎日 深夜 3:00 (JST) に bulk import を自動実行する time-based trigger を登録。
 * 既存トリガーがあれば削除してから再作成（時刻変更にも対応）。
 */
function BulkImportFromTaskMgmt_setupDailyTrigger() {
  const triggers = ScriptApp.getProjectTriggers();
  let removed = 0;
  for (let i = 0; i < triggers.length; i++) {
    if (triggers[i].getHandlerFunction() === 'BulkImportFromTaskMgmt_run') {
      ScriptApp.deleteTrigger(triggers[i]);
      removed++;
    }
  }
  ScriptApp.newTrigger('BulkImportFromTaskMgmt_run')
    .timeBased()
    .everyDays(1)
    .atHour(3)
    .create();
  return { removedOld: removed, created: true, hourJst: 3 };
}

/**
 * 案件一覧シートから (masterSsId, masterCol) で既存ケースを検索
 */
function _Bulk_findCaseByMasterCol(masterSsId, masterCol) {
  const sheet = SpreadsheetApp.getActive().getSheetByName(CASE_LIST_SHEET_NAME);
  if (!sheet) return null;
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return null;
  // M列(13) = masterSsId, N列(14) = masterCol
  const data = sheet.getRange(2, 1, lastRow - 1, 14).getValues();
  for (let i = 0; i < data.length; i++) {
    if (String(data[i][12]) === String(masterSsId) && Number(data[i][13]) === Number(masterCol)) {
      return { caseId: String(data[i][0]), rowIndex: i + 2 };
    }
  }
  return null;
}

// 案件一覧マスター (kessan master) の参照定数とキャッシュ
const _KESSAN_MASTER_SS_ID = '14RC6og1ma_I3LGHwCVwswKArgHwCOPxWlPB3g8adaYY';
const _KESSAN_MASTER_GID = 849096576;
const _KESSAN_COL_CLIENT = 3;   // C列: 顧客名
const _KESSAN_COL_ZISSI_URL = 4; // D列: 実施計画URL
const _KESSAN_COL_CODE = 9;     // I列: ｺｰﾄﾞ
let _kessanIndexCache = null;

function _Bulk_buildKessanIndex() {
  if (_kessanIndexCache) return _kessanIndexCache;
  const ss = SpreadsheetApp.openById(_KESSAN_MASTER_SS_ID);
  const sheets = ss.getSheets();
  let sheet = null;
  for (let i = 0; i < sheets.length; i++) {
    if (sheets[i].getSheetId() === _KESSAN_MASTER_GID) { sheet = sheets[i]; break; }
  }
  if (!sheet) sheet = sheets[0];
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) { _kessanIndexCache = { byCode: {}, byClient: {} }; return _kessanIndexCache; }
  const values = sheet.getRange(2, 1, lastRow - 1, Math.max(_KESSAN_COL_CODE, _KESSAN_COL_ZISSI_URL)).getValues();
  const byCode = {};
  const byClient = {};
  for (let i = 0; i < values.length; i++) {
    const row = values[i];
    const client = String(row[_KESSAN_COL_CLIENT - 1] || '').trim().replace(/[\r\n]+/g, '');
    const url = String(row[_KESSAN_COL_ZISSI_URL - 1] || '').trim();
    const code = String(row[_KESSAN_COL_CODE - 1] || '').trim().replace(/_\d+$/, ''); // 末尾 _2 等を剥がす
    if (!url || url.indexOf('docs.google.com/spreadsheets/') < 0) continue;
    if (code && !byCode[code]) byCode[code] = url;
    if (client) {
      if (!byClient[client]) byClient[client] = [];
      byClient[client].push({ url: url, code: code });
    }
  }
  _kessanIndexCache = { byCode: byCode, byClient: byClient };
  return _kessanIndexCache;
}

/**
 * 案件一覧シート上で「既に登録済みの zissiId」セットを返す
 * （同一クライアントで複数候補があるとき、別ケースに紐付き済みの URL を除外するため）
 */
function _Bulk_getExistingZissiIdSet() {
  const sheet = SpreadsheetApp.getActive().getSheetByName(CASE_LIST_SHEET_NAME);
  const set = {};
  if (!sheet) return set;
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return set;
  const data = sheet.getRange(2, 11, lastRow - 1, 1).getValues(); // K列 = zissiId
  for (let i = 0; i < data.length; i++) {
    const id = String(data[i][0] || '').trim();
    if (id) set[id] = true;
  }
  return set;
}

function _Bulk_extractSheetIdFromUrl(url) {
  const m = String(url || '').match(/\/spreadsheets\/d\/([A-Za-z0-9_-]+)/);
  return m ? m[1] : '';
}

/**
 * 案件一覧マスター から zissiUrl を引く。
 * 1) コード完全一致を最優先
 * 2) コード一致が無い場合、clientName で集約した URL を取得し、
 *    すでに別ケースに紐付き済みのものを除外 → 残り 1 件なら採用
 * 3) それでも絞れない場合は元の動作（uniq.length === 1）を維持
 */
function _Bulk_lookupKessanMaster(code, clientName) {
  try {
    const idx = _Bulk_buildKessanIndex();
    if (code && idx.byCode[code]) return idx.byCode[code];
    if (!clientName) return '';
    const clientKey = clientName.replace(/^株式会社|株式会社$|^（株）|（株）$|[\r\n\s]/g, '').trim();
    if (!clientKey) return '';
    const collected = [];
    Object.keys(idx.byClient).forEach(function (k) {
      const nk = k.replace(/^株式会社|株式会社$|^（株）|（株）$|[\r\n\s]/g, '');
      if (nk.indexOf(clientKey) >= 0 || clientKey.indexOf(nk) >= 0) {
        idx.byClient[k].forEach(function (e) { collected.push(e); });
      }
    });
    const seen = {};
    const uniq = [];
    collected.forEach(function (e) {
      if (!seen[e.url]) { seen[e.url] = true; uniq.push(e); }
    });
    if (uniq.length === 0) return '';
    if (uniq.length === 1) return uniq[0].url;
    // 複数候補 → 既に別ケースに紐付き済みの URL を除外
    const usedIds = _Bulk_getExistingZissiIdSet();
    const available = uniq.filter(function (e) {
      const id = _Bulk_extractSheetIdFromUrl(e.url);
      return id && !usedIds[id];
    });
    if (available.length === 1) return available[0].url;
    return '';
  } catch (e) {
    return '';
  }
}

/**
 * eventName からファイル名マッチ用のキーワード配列を返す。
 * - 改行/全角空白/句読点で分割
 * - 共通語 (展示会/ブース/出展/2024/2025/2026 など) と短すぎる(2字未満)を除外
 * - 配列が空ならマッチング不能と判定して呼び出し側で fallback skip
 */
function _Bulk_extractEventKeywords(eventName) {
  if (!eventName) return [];
  const STOPWORDS = /^(展示会|ブース|出展|出展ブース|reブース|REブース|キット|フェア|ビジネス|ジャパン|JAPAN|展|セミナー|国際|総合|大会|学術|学術大会|総会|株式会社|2024|2025|2026|2027|春|秋|夏|冬|東京|大阪|名古屋|九州|福岡|沖縄|中部|関東|関西|第[\d０-９]+回|Vol\.\d+|VOL\d+|Week|WEEK|EXPO|expo)$/i;
  const parts = String(eventName)
    .replace(/[【】（）()「」『』［］\[\]［］、,，\.　\n\r\t]/g, ' ')
    .split(/\s+/)
    .map(function (s) { return s.trim(); })
    .filter(function (s) {
      if (!s || s.length < 2) return false;
      if (STOPWORDS.test(s)) return false;
      return true;
    });
  // 重複排除
  const seen = {};
  const out = [];
  for (let i = 0; i < parts.length; i++) {
    const w = parts[i];
    if (!seen[w]) { seen[w] = true; out.push(w); }
    if (out.length >= 5) break; // top 5 keywords
  }
  return out;
}

function _Bulk_parsePeriod(s) {
  if (!s) return { start: '', end: '' };
  const str = String(s).trim();
  // パターン: "2025年10月20日〜22日"
  let m = str.match(/(\d{4})年\s*(\d{1,2})月\s*(\d{1,2})日\s*[〜~～\-ー－]\s*(?:(\d{1,2})月)?\s*(\d{1,2})日/);
  if (m) {
    const y = m[1], m1 = m[2], d1 = m[3], m2 = m[4] || m[2], d2 = m[5];
    return {
      start: y + '/' + ('0' + m1).slice(-2) + '/' + ('0' + d1).slice(-2),
      end: y + '/' + ('0' + m2).slice(-2) + '/' + ('0' + d2).slice(-2)
    };
  }
  // パターン: "2026/04/15〜17" / "2026/4/8~10"
  m = str.match(/(\d{4})\/(\d{1,2})\/(\d{1,2})\s*[〜~～\-ー－]\s*(?:(\d{1,2})\/)?(\d{1,2})/);
  if (m) {
    const y = m[1], m1 = m[2], d1 = m[3], m2 = m[4] || m[2], d2 = m[5];
    return {
      start: y + '/' + ('0' + m1).slice(-2) + '/' + ('0' + d1).slice(-2),
      end: y + '/' + ('0' + m2).slice(-2) + '/' + ('0' + d2).slice(-2)
    };
  }
  // パターン: "10/8-10日" — 年なしは諦め
  return { start: '', end: '' };
}

/** 案件情報を施工手順書ジェネレーターへ渡す WebApp API。 */
var CASE_API_TOKEN_DEFAULT = '691b5f21fc97f252672c90c44db69733e3bb221bbcd1273e';

var CASE_API_MASTER_SS_ID = '1t6eMvbPIu17m7hbv6foJcvd-fXrJkZqrePb8P6njxGI';

function _CaseApi_json(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}

function _CaseApi_expectedToken() {
  var configured = String(PropertiesService.getScriptProperties().getProperty('CASE_API_TOKEN') || '');
  return configured && configured.indexOf('__') !== 0 ? configured : CASE_API_TOKEN_DEFAULT;
}

function _CaseApi_norm(value) {
  return String(value || '').normalize('NFKC').toLowerCase()
    .replace(/様$/, '').replace(/[\s　]+/g, '').replace(/＆/g, '&');
}

function _CaseApi_caseCandidates(value) {
  var original = String(value || '');
  var withoutRegion = original.replace(/\s*\/\s*[^/]*[（(][^）)]*[）)]\s*$/, '');
  var normalized = [_CaseApi_norm(original), _CaseApi_norm(withoutRegion)];
  return normalized.filter(function (candidate, index) {
    return candidate && normalized.indexOf(candidate) === index;
  });
}

function _CaseApi_dateParts(value) {
  if (value instanceof Date && !isNaN(value.getTime())) {
    return [{ year: value.getFullYear(), month: value.getMonth() + 1, day: value.getDate() }];
  }
  var text = String(value || '').trim();
  var parts = [];
  var year = 0, month = 0;
  var re = /(\d{4})\s*(?:年|[\/.\-])\s*(\d{1,2})\s*(?:月|[\/.\-])\s*(\d{1,2})\s*日?|(?:^|[^\d])(\d{1,2})\s*(?:月|[\/])\s*(\d{1,2})\s*日?|(?:[~〜～ー–—至-]\s*)(\d{1,2})\s*日?/g;
  var match;
  while ((match = re.exec(text)) !== null) {
    var day = 0;
    if (match[1]) {
      year = Number(match[1]); month = Number(match[2]); day = Number(match[3]);
    } else if (match[4]) {
      month = Number(match[4]); day = Number(match[5]);
    } else if (match[6] && month) {
      day = Number(match[6]);
    }
    if (month >= 1 && month <= 12 && day >= 1 && day <= 31) {
      parts.push({ year: year || 0, month: month, day: day });
    }
  }
  return parts;
}

function _CaseApi_targetDates(opts) {
  var options = opts || {};
  return _CaseApi_dateParts(options.startDate).concat(_CaseApi_dateParts(options.endDate));
}

function _CaseApi_chooseMasterMatch(matches, cases, opts) {
  if (!matches.length) return null;
  var longest = -1;
  var winners = [];
  for (var i = 0; i < matches.length; i++) {
    var length = _CaseApi_norm(cases[matches[i]]).length;
    if (length > longest) {
      longest = length;
      winners = [matches[i]];
    } else if (length === longest) {
      winners.push(matches[i]);
    }
  }
  if (winners.length === 1) return { col: winners[0] + 1, source: 'matched' };

  var dateRows = opts && Array.isArray(opts.dateRows) ? opts.dateRows : [];
  var targets = _CaseApi_targetDates(opts);
  if (targets.length && dateRows.length) {
    var dateWinners = winners.filter(function (candidate) {
      var candidateDates = [];
      for (var row = 0; row < dateRows.length; row++) {
        candidateDates = candidateDates.concat(_CaseApi_dateParts(
          Array.isArray(dateRows[row]) ? dateRows[row][candidate] : ''
        ));
      }
      return candidateDates.some(function (candidateDate) {
        return targets.some(function (target) {
          return candidateDate.month === target.month && candidateDate.day === target.day &&
            (!candidateDate.year || !target.year || candidateDate.year === target.year);
        });
      });
    });
    if (dateWinners.length === 1) return { col: dateWinners[0] + 1, source: 'matched' };
  }
  return null;
}

function _CaseApi_validateStoredCol(clients, cases, clientName, caseName, storedCol) {
  var fallback = Number(storedCol) || 0;
  if (fallback <= 0 || fallback % 1 !== 0) return { col: 0, source: 'none' };

  for (var offset = 0; offset <= 2; offset++) {
    var index = fallback - 1 - offset;
    if (index < 0) break;
    var storedClient = String(clients[index] || '');
    if (!storedClient.trim()) continue;
    if (_CaseApi_norm(storedClient) !== _CaseApi_norm(clientName)) return { col: 0, source: 'none' };
    var storedCase = _CaseApi_norm(cases[fallback - 1]);
    var requestedCases = _CaseApi_caseCandidates(caseName);
    var caseMatches = !storedCase || requestedCases.some(function (requestedCase) {
      return storedCase === requestedCase || storedCase.indexOf(requestedCase) === 0 ||
        requestedCase.indexOf(storedCase) === 0;
    });
    return caseMatches ? { col: fallback, source: 'stored' } : { col: 0, source: 'none' };
  }
  return { col: 0, source: 'none' };
}

/**
 * master の案件先頭列を特定する純関数。
 * headerRows は [row1, row2] のゼロ始まり配列で、配列 index 0 がシート列1に対応する。
 * row1=クライアント名、row2=案件名。保存列は一致しない場合だけ後方互換用に使う。
 */
function CaseApi_resolveMasterCol(headerRows, clientName, caseName, storedCol, opts) {
  var rows = Array.isArray(headerRows) ? headerRows : [];
  var clients = Array.isArray(rows[0]) ? rows[0] : [];
  var cases = Array.isArray(rows[1]) ? rows[1] : [];
  var clientN = _CaseApi_norm(clientName);
  var caseNames = _CaseApi_caseCandidates(caseName);
  var width = Math.max(clients.length, cases.length);
  var candidates = [];
  var i;

  if (clientN && caseNames.length) {
    for (i = 0; i < width; i++) {
      if (_CaseApi_norm(clients[i]) === clientN) candidates.push(i);
    }

    var exactMatches = candidates.filter(function (candidate) {
      var masterCaseN = _CaseApi_norm(cases[candidate]);
      return caseNames.indexOf(masterCaseN) >= 0;
    });
    var resolution = _CaseApi_chooseMasterMatch(exactMatches, cases, opts);
    if (resolution) return resolution;

    var prefixMatches = candidates.filter(function (candidate) {
      var masterCaseN = _CaseApi_norm(cases[candidate]);
      return masterCaseN && caseNames.some(function (caseN) {
        return masterCaseN.indexOf(caseN) === 0 || caseN.indexOf(masterCaseN) === 0;
      });
    });
    resolution = _CaseApi_chooseMasterMatch(prefixMatches, cases, opts);
    if (resolution) return resolution;

    var prefixes = caseNames.map(function (caseN) { return caseN.slice(0, 12); });
    var prefix12Matches = candidates.filter(function (candidate) {
      var masterPrefix = _CaseApi_norm(cases[candidate]).slice(0, 12);
      return masterPrefix && prefixes.indexOf(masterPrefix) >= 0;
    });
    resolution = _CaseApi_chooseMasterMatch(prefix12Matches, cases, opts);
    if (resolution) return resolution;
  }

  return _CaseApi_validateStoredCol(clients, cases, clientName, caseName, storedCol);
}

/** GAS の task シートからヘッダを読み、純関数へ渡す薄いラッパ。 */
function CaseApi_resolveMasterColFromSheet(task, clientName, caseName, storedCol, opts) {
  if (!task) return CaseApi_resolveMasterCol([], clientName, caseName, storedCol, opts);
  var lastCol = task.getLastColumn();
  var headers = lastCol > 0 ? task.getRange(1, 1, 5, lastCol).getValues() : [];
  var options = opts || {};
  options.dateRows = [headers[3] || [], headers[4] || []];
  return CaseApi_resolveMasterCol(headers, clientName, caseName, storedCol, options);
}

/**
 * 解決列から右2列までの行3を受け、地域表記ではない最初の非空値を返す。
 * 会場名が無い場合は、最初の地域表記（または最初の非空値）へフォールバックする。
 */
function CaseApi_pickVenue(row3Slice) {
  var values = Array.isArray(row3Slice) ? row3Slice : [];
  var fallback = '';
  for (var i = 0; i < values.length; i++) {
    var value = String(values[i] || '').trim();
    if (!value) continue;
    if (!fallback) fallback = value;
    if (!/^[^（）()]+[（(][^）)]+[）)]$/.test(value)) return value;
  }
  return fallback;
}

function _CaseApi_formatDate(value) {
  return value instanceof Date && !isNaN(value.getTime())
    ? Utilities.formatDate(value, 'Asia/Tokyo', 'yyyy年M月d日')
    : String(value || '').trim();
}

/**
 * 開催日程の末尾にある日付を拾う。年が省略された場合は設営日の年だけを補う。
 * 例: "2026年9月1日〜3日" -> "2026年9月3日"
 */
function _CaseApi_lastDate(value, setupValue) {
  if (value instanceof Date && !isNaN(value.getTime())) return _CaseApi_formatDate(value);
  var text = String(value || '').trim();
  if (!text) return '';

  var setupYear = setupValue instanceof Date ? setupValue.getFullYear() : 0;
  var year = 0, month = 0, day = 0, found = false;
  var re = /(\d{4})\s*(?:年|[\/.\-])\s*(\d{1,2})\s*(?:月|[\/.\-])\s*(\d{1,2})\s*日?|(?:^|[^\d])(\d{1,2})\s*(?:月|[\/])\s*(\d{1,2})\s*日?|(?:[~〜～ー–—至-]\s*)(\d{1,2})\s*日?/g;
  var match;
  while ((match = re.exec(text)) !== null) {
    if (match[1]) {
      year = Number(match[1]); month = Number(match[2]); day = Number(match[3]);
    } else if (match[4]) {
      month = Number(match[4]); day = Number(match[5]);
      if (!year) year = setupYear;
    } else if (match[6] && month) {
      day = Number(match[6]);
    }
    found = true;
  }
  if (!found || !year || !month || !day) return '';
  var date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) return '';
  return _CaseApi_formatDate(date);
}

function _CaseApi_dispatch(e) {
  try {
    var params = e && e.parameter ? e.parameter : {};
    if (String(params.form || '') === 'feedback') return FeedbackRelay_serveForm(params);
    if (String(params.app || '') === 'checklist' && params.admin) return Checklist_serveAdmin(params);
    if (String(params.app || '') === 'checklist') return Checklist_serveStaff(params);
    if (String(params.token || '') !== _CaseApi_expectedToken()) {
      return _CaseApi_json({ ok: false, error: 'unauthorized' });
    }

    var action = String(params.action || 'case');
    if (action === 'feedback') return _CaseApi_json(FeedbackApi_list(params));
    if (action === 'checklistUrls') return _CaseApi_json(Checklist_getUrls());
    if (action === 'checklistBootstrap') return _CaseApi_json(Checklist_bootstrap());
    if (action === 'checklistSeedMerge') return _CaseApi_json(Checklist_seedMerge());
    if (action === 'checklistItems') return _CaseApi_json(Checklist_getItemList(String(params.caseId || ''), String(params.refresh || '') === 'true'));
    if (action === 'checklistLinks') return _CaseApi_json(Checklist_getCaseLinks(String(params.caseId || ''), String(params.role || ''), String(params.refresh || '') === 'true'));
    if (action === 'rushList') {
      var rush = Checklist_listRush(String(params.caseId || ''));
      if (rush.ok && params.since) {
        var since = new Date(String(params.since));
        if (isNaN(since.getTime())) return _CaseApi_json({ ok: false, error: 'since が不正です' });
        rush.rows = rush.rows.filter(function (row) { return new Date(row.updatedAt).getTime() >= since.getTime(); });
      }
      return _CaseApi_json(rush.ok ? rush.rows : rush);
    }
    if (action === 'rushUpdate') return _CaseApi_json(Checklist_updateRushStatus(String(params.id || ''), String(params.status || ''), String(params.updatedBy || '')));

    var label = String(params.event || '');
    var separator = label.indexOf(' / ');
    var clientPart = separator >= 0 ? label.slice(0, separator) : label;
    var eventPart = separator >= 0 ? label.slice(separator + 3) : '';
    var clientN = _CaseApi_norm(clientPart);
    var eventN = _CaseApi_norm(eventPart).slice(0, 25);
    if (!clientN) return _CaseApi_json({ ok: false, error: 'case not found' });

    var sheet = SpreadsheetApp.getActive().getSheetByName(CASE_LIST_SHEET_NAME);
    var data = sheet ? sheet.getDataRange().getValues() : [];
    var caseId = '';
    for (var i = 1; i < data.length; i++) {
      if (_CaseApi_norm(data[i][1]) === clientN &&
          (eventN === '' || _CaseApi_norm(data[i][2]).indexOf(eventN) === 0)) {
        caseId = String(data[i][0] || '').trim();
        if (caseId) break;
      }
    }
    var c = caseId ? CaseList_getById(caseId) : null;
    if (!c) return _CaseApi_json({ ok: false, error: 'case not found' });

    var venue = '', region = '', setupRaw = '', eventDates = '';
    var masterColResolution = { col: Number(c.masterCol) || 0, source: c.masterCol ? 'stored' : 'none' };
    var master = SpreadsheetApp.openById(CASE_API_MASTER_SS_ID);
    var task = master.getSheetByName('task');
    if (task) {
      masterColResolution = CaseApi_resolveMasterColFromSheet(
        task, c.clientName, c.caseName, c.masterCol,
        { startDate: c.startDate, endDate: c.endDate }
      );
      if (masterColResolution.col > 0) {
        var masterWidth = Math.max(1, Math.min(3, task.getLastColumn() - masterColResolution.col + 1));
        var masterValues = task.getRange(3, masterColResolution.col, 3, masterWidth).getValues();
        var row3Slice = masterValues[0] || [];
        region = String(row3Slice[0] || '').trim();
        venue = CaseApi_pickVenue(row3Slice);
        setupRaw = masterValues[1][0];
        eventDates = masterValues[2][0];
        if (typeof setupRaw === 'string') setupRaw = setupRaw.trim();
        if (typeof eventDates === 'string') eventDates = eventDates.trim();
      }
    }

    var itemList = '';
    if (c.zissiId) {
      var items = Zissi_readExistingItemList(SpreadsheetApp.openById(c.zissiId)).items;
      itemList = items.slice(0, 200).map(function (item) {
        return item.name + ' ×' + item.qty;
      }).join('\n');
    }

    return _CaseApi_json({
      ok: true,
      caseId: c.caseId,
      clientName: c.clientName,
      eventName: c.caseName,
      venue: venue,
      masterColUsed: masterColResolution.col,
      masterColSource: masterColResolution.source,
      region: region,
      setupDate: _CaseApi_formatDate(setupRaw),
      eventDates: eventDates,
      teardownDate: _CaseApi_lastDate(eventDates, setupRaw),
      boothSize: c.boothSize,
      itemList: itemList,
      extraNotes: ''
    });
  } catch (err) {
    return _CaseApi_json({ ok: false, error: String(err && err.message ? err.message : err) });
  }
}

function doGet(e) {
  return _CaseApi_dispatch(e);
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    CaseApi_resolveMasterCol: CaseApi_resolveMasterCol,
    CaseApi_pickVenue: CaseApi_pickVenue
    ,_CaseApi_dispatch: _CaseApi_dispatch
  };
}

/** 案件フォルダ全資料を Gemini で事前要約し、実施計画書へ保存する。 */
const CASE_DIGEST_SHEET_NAME = 'Claude_案件資料ダイジェスト';
const CASE_DIGEST_MODEL = 'google/gemini-3.7-flash';
const CASE_DIGEST_ENDPOINT = 'https://openrouter.ai/api/v1/chat/completions';
const CASE_DIGEST_MAX_FILE_BYTES = 20 * 1024 * 1024;
const CASE_DIGEST_MAX_CHUNK_BYTES = 15 * 1024 * 1024; // base64 で約20MB。UrlFetchApp 50MB 上限に余裕を持たせる
const CASE_DIGEST_RUNTIME_MS = 4.5 * 60 * 1000;
// 1案件(=1チャンク)の処理に最大約2分かかる実測。4.5分経過後に新しい案件を開始すると
// GAS の6分制限を超えて打ち切られるため、新規着手の締切は別に短く取る。
const CASE_DIGEST_CASE_START_CUTOFF_MS = 2.5 * 60 * 1000;
const CASE_DIGEST_RUN_BUDGET_MS = 3.5 * 60 * 1000;
const CASE_DIGEST_MAX_CHUNKS_PER_RUN = 1;
const CASE_DIGEST_CELL_CHARS = 40000; // Sheets の 1セル 50,000 文字上限に対する安全域
const CASE_DIGEST_LEDGER_KEY = 'CASE_DIGEST_LEDGER';
const CASE_DIGEST_RECHECK_MS = 20 * 60 * 60 * 1000;
const CASE_DIGEST_PARTIAL_FINALIZE_MS = 5 * 24 * 60 * 60 * 1000;
const CASE_DIGEST_LEDGER_MAX_CHARS = 8000;
const CASE_DIGEST_FAILURE_COOLDOWN_MS = 3 * 24 * 60 * 60 * 1000;

function CaseDigest_fingerprint(materials) {
  const source = (materials || []).map(function (m) {
    return String(m.driveFileId || m.fileId || '') + ':' + String(m.lastUpdated || '');
  }).sort().join('\n');
  let bytes;
  if (typeof Utilities !== 'undefined') {
    bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, source, Utilities.Charset.UTF_8);
    return bytes.map(function (b) { return ('0' + ((b < 0 ? b + 256 : b).toString(16))).slice(-2); }).join('');
  }
  // Node の純ロジックテスト用。GAS ではこの分岐を通らない。
  return require('node:crypto').createHash('sha256').update(source, 'utf8').digest('hex');
}

function CaseDigest_chunkFingerprint(chunkMaterials) {
  return CaseDigest_fingerprint(chunkMaterials);
}

/** サイズ情報だけで安定してチャンク化する純関数。 */
function CaseDigest_chunkMaterials(materials, maxChunkBytes) {
  const limit = Number(maxChunkBytes) || CASE_DIGEST_MAX_CHUNK_BYTES;
  const chunks = [], excluded = [];
  let current = [], currentBytes = 0;
  (materials || []).forEach(function (m) {
    const bytes = Number(m.bytes) || 0;
    if (bytes > limit) {
      excluded.push(Object.assign({}, m, { reason: 'over_max_chunk_bytes' }));
      return;
    }
    if (current.length && currentBytes + bytes > limit) {
      chunks.push(current); current = []; currentBytes = 0;
    }
    current.push(m); currentBytes += bytes;
  });
  if (current.length) chunks.push(current);
  return { chunks: chunks, excluded: excluded };
}

function CaseDigest_getKey_() {
  return String(PropertiesService.getScriptProperties().getProperty('OPENROUTER_API_KEY') || '');
}

function CaseDigest_blobForMaterial_(m) {
  const file = DriveApp.getFileById(m.driveFileId);
  if (m.kind === 'pptx') return CaseMaterials_pptxToPdf(m.driveFileId);
  if (m.kind === 'slides' || m.kind === 'docs') return file.getAs('application/pdf');
  return file.getBlob();
}

function CaseDigest_prepareMaterials_(materials) {
  const prepared = [], excluded = [];
  (materials || []).forEach(function (m) {
    try {
      const blob = CaseDigest_blobForMaterial_(m);
      if (!blob) { excluded.push(Object.assign({}, m, { reason: 'conversion_failed' })); return; }
      const bytes = blob.getBytes();
      if (bytes.length > CASE_DIGEST_MAX_FILE_BYTES) {
        excluded.push(Object.assign({}, m, { reason: 'over_max_file_bytes', actualBytes: bytes.length })); return;
      }
      prepared.push(Object.assign({}, m, {
        bytes: bytes.length,
        digestMimeType: m.kind === 'image' ? blob.getContentType() : 'application/pdf',
        digestBase64: Utilities.base64Encode(bytes)
      }));
    } catch (e) {
      excluded.push(Object.assign({}, m, { reason: 'read_failed', detail: String(e.message || e) }));
    }
  });
  return { prepared: prepared, excluded: excluded };
}

function CaseDigest_prompt_() {
  return [
    '添付された案件資料だけを根拠に、展示会ブース制作の案件資料ダイジェストを日本語で作成してください。',
    '見出し付きプレーンテキスト（Markdown見出し可）で、次を必ず含めてください。',
    '1. ブース/装飾の仕様（寸法・素材・色・数量）',
    '2. 現況写真から読み取れる建物・設置環境の条件',
    '3. デザイン/パースで確定していること',
    '4. 測定・実測値',
    '5. 未確定・要確認事項',
    '6. 各項目の出典ファイル名',
    '資料に無い情報は絶対に補わず、「資料に記載なし」と明記してください。'
  ].join('\n');
}

function CaseDigest_callOpenRouter_(key, text, files) {
  const content = [{ type: 'text', text: text }];
  (files || []).forEach(function (f) {
    const dataUrl = 'data:' + f.digestMimeType + ';base64,' + f.digestBase64;
    if (f.kind === 'image') content.push({ type: 'image_url', image_url: { url: dataUrl } });
    else content.push({ type: 'file', file: { filename: f.label, file_data: dataUrl } });
  });
  const response = UrlFetchApp.fetch(CASE_DIGEST_ENDPOINT, {
    method: 'post', contentType: 'application/json',
    headers: { Authorization: 'Bearer ' + key },
    payload: JSON.stringify({ model: CASE_DIGEST_MODEL, messages: [{ role: 'user', content: content }] }),
    muteHttpExceptions: true
  });
  const status = response.getResponseCode();
  const body = response.getContentText();
  if (status < 200 || status >= 300) throw new Error('OpenRouter HTTP ' + status + ': ' + body.slice(0, 500));
  const parsed = JSON.parse(body);
  const textOut = parsed.choices && parsed.choices[0] && parsed.choices[0].message && parsed.choices[0].message.content;
  if (!textOut) throw new Error('OpenRouter response has no content');
  return { text: String(textOut), usage: parsed.usage || {} };
}

function CaseDigest_addUsage_(total, usage) {
  Object.keys(usage || {}).forEach(function (k) {
    if (typeof usage[k] === 'number') total[k] = (Number(total[k]) || 0) + usage[k];
  });
}

/** Sheets の 1セル文字数上限を超えないよう、改行境界で本文を分割する。 */
function CaseDigest_splitForCells(text, maxChars) {
  const limit = Number(maxChars) || CASE_DIGEST_CELL_CHARS;
  const out = [];
  let buf = '';
  String(text || '').split('\n').forEach(function (line) {
    while (line.length > limit) {            // 1行が上限超なら強制的に切る
      if (buf) { out.push(buf); buf = ''; }
      out.push(line.slice(0, limit));
      line = line.slice(limit);
    }
    if (buf.length + line.length + 1 > limit) { out.push(buf); buf = line; }
    else buf = buf ? buf + '\n' + line : line;
  });
  if (buf) out.push(buf);
  return out.length ? out : [''];
}

/** シート行から再開に必要な状態を取り出す純関数。 */
function CaseDigest_parseProgress(rows, fingerprint, chunkTotal, chunkFingerprints) {
  const values = rows || [];
  const storedFingerprint = values[1] ? String(values[1][1] || '') : '';
  const storedState = values[3] ? String(values[3][1] || '') : '';
  const summaries = [], saved = [], byFingerprint = {};
  for (let i = 0; i < values.length; i++) {
    const match = String(values[i][0] || '').match(/^チャンク(\d+)要約$/);
    if (!match) continue;
    const index = Number(match[1]) - 1;
    const parts = [];
    for (let j = i + 1; j < values.length; j++) {
      if (/^チャンク\d+要約$/.test(String(values[j][0] || ''))) break;
      parts.push(String(values[j][0] || ''));
    }
    const summary = parts.join('\n').trim();
    const chunkFingerprint = String(values[i][1] || '');
    saved[index] = summary;
    if (chunkFingerprint && summary) byFingerprint[chunkFingerprint] = summary;
  }
  if (Array.isArray(chunkFingerprints) && Object.keys(byFingerprint).length) {
    chunkFingerprints.forEach(function (chunkFingerprint, index) {
      if (byFingerprint[String(chunkFingerprint || '')]) summaries[index] = byFingerprint[String(chunkFingerprint || '')];
    });
  } else if (storedFingerprint === String(fingerprint || '') && storedState === '部分') {
    saved.forEach(function (summary, index) { if (summary) summaries[index] = summary; });
  }
  let nextIndex = 0;
  while (nextIndex < chunkTotal && typeof summaries[nextIndex] === 'string' && summaries[nextIndex]) nextIndex++;
  return { state: storedState, fingerprintMatches: storedFingerprint === String(fingerprint || ''),
    summaries: summaries, nextIndex: nextIndex, chunkTotal: chunkTotal };
}

/** チャンク処理の状態遷移。processChunk/savePartial/merge は本番・テストで注入する。 */
function CaseDigest_runChunks(state, opts) {
  const options = opts || {};
  const summaries = (state.summaries || []).slice();
  const total = Number(state.chunkTotal) || 0;
  const maxChunks = options.maxChunksPerRun == null ? CASE_DIGEST_MAX_CHUNKS_PER_RUN : Number(options.maxChunksPerRun);
  const budget = options.runtimeBudgetMs == null ? CASE_DIGEST_RUN_BUDGET_MS : Number(options.runtimeBudgetMs);
  const now = options.now || Date.now;
  const started = now();
  let processed = 0;
  for (let i = 0; i < total; i++) {
    if (summaries[i]) continue;
    if (processed >= maxChunks || now() - started >= budget) break;
    summaries[i] = String(options.processChunk(i) || '');
    if (!summaries[i]) throw new Error('チャンク' + (i + 1) + 'の要約が空です');
    processed++;
    if (options.savePartial) options.savePartial(summaries, summaries.filter(function (s) { return Boolean(s); }).length, total);
  }
  const done = summaries.filter(function (s) { return Boolean(s); }).length;
  if (done < total) return { state: '部分', chunksDone: done, chunkTotal: total, summaries: summaries };
  const digest = total === 1 ? summaries[0] : options.merge(summaries);
  return { state: '完了', chunksDone: done, chunkTotal: total, summaries: summaries, digest: digest };
}

function CaseDigest_readRows_(c) {
  const sh = CaseDigest_sheet_(c);
  if (!sh) return [];
  return sh.getRange(1, 1, sh.getLastRow() || 1, 3).getDisplayValues();
}

function CaseDigest_write_(c, materials, fingerprint, state, chunksDone, chunkTotal, digest, summaries, chunkFingerprints, note) {
  if (!c.zissiId) throw new Error('実施計画書がありません: ' + c.caseId);
  const ss = SpreadsheetApp.openById(c.zissiId);
  const sh = ss.getSheetByName(CASE_DIGEST_SHEET_NAME) || ss.insertSheet(CASE_DIGEST_SHEET_NAME);
  sh.clearContents();
  const rows = [
    ['生成日時', new Date().toISOString(), ''],
    ['フィンガープリント', fingerprint, ''],
    ['対象ファイル', materials.length, ''],
    ['状態', state, ''],
    ['進捗', chunksDone + '/' + chunkTotal, ''],
    ['', '', ''],
    ['ファイル名', 'kind', '更新日時']
  ];
  materials.forEach(function (m) {
    rows.push([m.label || '', m.kind || '', m.lastUpdated ? new Date(m.lastUpdated).toISOString() : '']);
  });
  rows.push(['', '', ''], ['本文', '', '']);
  if (state === '完了') CaseDigest_splitForCells(digest).forEach(function (part) { rows.push([part, '', '']); });
  if (note) rows.push(['注記', note, '']);
  (summaries || []).forEach(function (summary, i) {
    if (!summary) return;
    rows.push(['チャンク' + (i + 1) + '要約', String(chunkFingerprints && chunkFingerprints[i] || ''), '']);
    CaseDigest_splitForCells(summary).forEach(function (part) { rows.push([part, '', '']); });
  });
  sh.getRange(1, 1, rows.length, 3).setValues(rows);
  return PanelLinks_sheetUrl(ss, sh);
}

function CaseDigest_buildForCase(caseId, opts) {
  const options = opts || {};
  const key = CaseDigest_getKey_();
  if (!key) return { skipped: 'OPENROUTER_API_KEY 未設定' };
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);
  const materials = options.materials || Case_collectCaseMaterials(c, { unlimited: true });
  const fingerprint = options.fingerprint || CaseDigest_fingerprint(materials);
  // 元サイズでチャンク分割し、変換+base64 は「送る直前にそのチャンクだけ」行う。
  // 先に全件 base64 化すると 30MB 級の案件で GAS のメモリを溢れさせる。
  const split = CaseDigest_chunkMaterials(materials, CASE_DIGEST_MAX_CHUNK_BYTES);
  const chunkFingerprints = split.chunks.map(function (chunk) { return CaseDigest_chunkFingerprint(chunk); });
  const excluded = [].concat(split.excluded);
  if (!split.chunks.length) throw new Error('ダイジェスト対象として送信可能な資料がありません');
  const progress = CaseDigest_parseProgress(CaseDigest_readRows_(c), fingerprint, split.chunks.length, chunkFingerprints);
  const finalizeBeforeProcessing = CaseDigest_shouldFinalizePartial({ partialSinceMs: options.partialSinceMs,
    chunksDone: progress.summaries.filter(function (s) { return Boolean(s); }).length,
    chunkTotal: split.chunks.length, nowMs: Date.now() });
  const usage = {};
  let sheetUrl = '';
  const run = CaseDigest_runChunks(progress, {
    maxChunksPerRun: finalizeBeforeProcessing ? 0 : options.maxChunksPerRun,
    runtimeBudgetMs: options.runtimeBudgetMs,
    processChunk: function (i) {
      const prepared = CaseDigest_prepareMaterials_(split.chunks[i]);
      prepared.excluded.forEach(function (x) { excluded.push(x); });
      if (!prepared.prepared.length) throw new Error('チャンク' + (i + 1) + 'に送信可能な資料がありません');
      const result = CaseDigest_callOpenRouter_(key,
        CaseDigest_prompt_() + '\n\nこれは全' + split.chunks.length + 'チャンク中の' + (i + 1) + '番目です。',
        prepared.prepared);
      CaseDigest_addUsage_(usage, result.usage);
      return result.text;
    },
    savePartial: function (summaries, done, total) {
      sheetUrl = CaseDigest_write_(c, materials, fingerprint, '部分', done, total, '', summaries, chunkFingerprints);
    },
    merge: function (summaries) {
      const merged = CaseDigest_callOpenRouter_(key,
        CaseDigest_prompt_() + '\n\n以下は資料群ごとの要約です。重複を統合して1本のダイジェストにしてください。\n\n' +
        summaries.map(function (s, i) { return '## チャンク' + (i + 1) + '\n' + s; }).join('\n\n'), []);
      CaseDigest_addUsage_(usage, merged.usage);
      return merged.text;
    }
  });
  let finalizedPartial = false;
  if (run.state === '部分' && CaseDigest_shouldFinalizePartial({ partialSinceMs: options.partialSinceMs,
    chunksDone: run.chunksDone, chunkTotal: run.chunkTotal, nowMs: Date.now() })) {
    const available = run.summaries.filter(function (s) { return Boolean(s); });
    if (available.length === 1) run.digest = available[0];
    else {
      const partialMerged = CaseDigest_callOpenRouter_(key,
        CaseDigest_prompt_() + '\n\n以下は取得済み資料群の要約です。重複を統合して1本のダイジェストにしてください。\n\n' +
        available.join('\n\n'), []);
      CaseDigest_addUsage_(usage, partialMerged.usage);
      run.digest = partialMerged.text;
    }
    run.state = '完了';
    finalizedPartial = true;
  }
  if (run.state === '完了') sheetUrl = CaseDigest_write_(c, materials, fingerprint, '完了',
    run.chunksDone, run.chunkTotal, run.digest, run.summaries, chunkFingerprints,
    finalizedPartial ? '資料の一部のみ反映(' + run.chunksDone + '/' + run.chunkTotal + 'チャンク)' : '');
  return { caseId: caseId, files: materials.length, chunks: split.chunks.length,
    state: run.state, chunksDone: run.chunksDone, chunkTotal: run.chunkTotal,
    chunksSent: run.chunksDone - progress.summaries.filter(function (s) { return Boolean(s); }).length,
    chunksDeferred: run.chunkTotal - run.chunksDone, finalizedPartial: finalizedPartial,
    chars: run.digest ? run.digest.length : 0,
    fingerprint: fingerprint, sheetUrl: sheetUrl, usage: usage, excluded: excluded.map(function (x) {
      return { label: x.label || '', reason: x.reason || '' };
    }) };
}

function CaseDigest_sheet_(c) {
  if (!c || !c.zissiId) return null;
  try { return SpreadsheetApp.openById(c.zissiId).getSheetByName(CASE_DIGEST_SHEET_NAME); } catch (e) { return null; }
}

function CaseDigest_load(c) {
  try {
    const values = CaseDigest_readRows_(c);
    if (!values.length) return '';
    const state = values[3] ? String(values[3][1] || '') : '';
    if (state === '部分') {
      const progress = CaseDigest_parseProgress(values, values[1] ? values[1][1] : '', Number(String(values[4] && values[4][1] || '').split('/')[1]) || 0);
      const partial = progress.summaries.filter(function (s) { return Boolean(s); }).join('\n\n');
      return partial ? '（注: このダイジェストは資料の一部のみを反映した途中版です）\n' + partial : '';
    }
    const hasPartialNote = values.some(function (row) { return String(row[0] || '') === '注記'; });
    for (let i = 0; i < values.length; i++) {
      if (values[i][0] === '本文') {
        const body = [];
        for (let j = i + 1; j < values.length && !/^チャンク\d+要約$/.test(String(values[j][0] || '')) && String(values[j][0] || '') !== '注記'; j++) body.push(values[j][0]);
        const text = body.join('\n').trim();
        return hasPartialNote && text ? '（注: このダイジェストは資料の一部のみを反映しています）\n' + text : text;
      }
    }
  } catch (e) {}
  return '';
}

function CaseDigest_shouldFinalizePartial(input) {
  const value = input || {};
  const done = Number(value.chunksDone) || 0;
  const total = Number(value.chunkTotal) || 0;
  const since = Number(value.partialSinceMs) || 0;
  const nowMs = Number(value.nowMs) || 0;
  return done >= 1 && total > done && since > 0 && nowMs - since >= CASE_DIGEST_PARTIAL_FINALIZE_MS;
}

/** Unix ms を JST の日付キーへ変換する純関数。 */
const CaseDigest_failureDayKey = function (ms) {
  const value = Number(ms) || 0;
  if (value <= 0) return '';
  return new Date(value + 9 * 60 * 60 * 1000).toISOString().slice(0, 10);
};

/** 同日の再試行を数えず、異なる失敗日だけを記録する純関数。 */
const CaseDigest_recordFailure = function (input) {
  const value = input || {};
  const prev = value.prev || {};
  const nowMs = Number(value.nowMs) || 0;
  const days = Array.isArray(prev.days) ? prev.days.map(function (day) { return String(day); })
    .filter(function (day, index, all) { return day && all.indexOf(day) === index; }) : [];
  const previousDay = CaseDigest_failureDayKey(prev.lastMs);
  if (!Array.isArray(prev.days) && previousDay) days.push(previousDay);
  const today = CaseDigest_failureDayKey(nowMs);
  let n = Number(prev.n) || 0;
  if (today && days.indexOf(today) === -1) {
    days.push(today);
    n += 1;
  }
  return { n: n, lastMs: nowMs, days: days.slice(-10) };
};

/** 異なる5日で失敗してから3日未満の間だけ夜間処理を停止する純関数。 */
const CaseDigest_shouldSkipByFailure = function (input) {
  const value = input || {};
  const n = Array.isArray(value.days) ? value.days.filter(function (day, index, all) {
    return day && all.indexOf(day) === index;
  }).length : (Number(value.n) || 0);
  const lastMs = Number(value.lastMs) || 0;
  const nowMs = Number(value.nowMs) || 0;
  return n >= 5 && lastMs > 0 && nowMs - lastMs < CASE_DIGEST_FAILURE_COOLDOWN_MS;
};

function CaseDigest_orderCases(cases, ledger, nowMs) {
  const entries = ledger || {};
  const now = Number(nowMs) || 0;
  return (cases || []).map(function (c, index) { return { c: c, i: index, e: entries[String(c.caseId || '')] }; })
    .filter(function (x) { return !x.e || x.e.s !== '完了' || now - (Number(x.e.c) || 0) >= CASE_DIGEST_RECHECK_MS; })
    .sort(function (a, b) {
      const ap = !a.e ? 0 : a.e.s === '部分' ? 1 : 2;
      const bp = !b.e ? 0 : b.e.s === '部分' ? 1 : 2;
      if (ap !== bp) return ap - bp;
      if (ap === 1) return (Number(a.e.p) || 0) - (Number(b.e.p) || 0) || a.i - b.i;
      if (ap === 2) return (Number(a.e.c) || 0) - (Number(b.e.c) || 0) || a.i - b.i;
      return a.i - b.i;
    }).map(function (x) { return x.c; });
}

function CaseDigest_saveLedger_(props, ledger) {
  let json = JSON.stringify(ledger || {});
  if (json.length > CASE_DIGEST_LEDGER_MAX_CHARS) {
    Object.keys(ledger).filter(function (caseId) { return ledger[caseId] && ledger[caseId].s === '完了'; })
      .sort(function (a, b) { return (Number(ledger[a].c) || 0) - (Number(ledger[b].c) || 0); })
      .some(function (caseId) {
        delete ledger[caseId];
        json = JSON.stringify(ledger);
        return json.length <= CASE_DIGEST_LEDGER_MAX_CHARS;
      });
  }
  props.setProperty(CASE_DIGEST_LEDGER_KEY, json);
}

function CaseDigest_nightlyRun() {
  const key = CaseDigest_getKey_();
  if (!key) {
    const unset = { skipped: 'OPENROUTER_API_KEY 未設定' };
    console.log('CaseDigest nightly: skipped=OPENROUTER_API_KEY 未設定');
    return unset;
  }
  const started = Date.now(), cases = CaseList_listAll() || [];
  const props = PropertiesService.getScriptProperties();
  let ledger = {};
  try { ledger = JSON.parse(props.getProperty(CASE_DIGEST_LEDGER_KEY) || '{}'); } catch (e) {}
  const ordered = CaseDigest_orderCases(cases, ledger, started);
  const result = { done: true, processed: [], partial: [], skipped: [], errors: [], remaining: [],
    order: ordered.slice(0, 5).map(function (c) { return c.caseId; }) };
  for (let i = 0; i < ordered.length; i++) {
    if (Date.now() - started > CASE_DIGEST_CASE_START_CUTOFF_MS) {
      result.done = false; result.remaining = ordered.slice(i).map(function (c) { return c.caseId; }); break;
    }
    const c = ordered[i];
    const failKey = 'DIGEST_FAIL_' + c.caseId;
    let fail = { n: 0, lastMs: 0 };
    try { fail = JSON.parse(props.getProperty(failKey) || '{}'); } catch (e) {}
    fail.n = Number(fail.n) || 0;
    if (CaseDigest_shouldSkipByFailure({ n: fail.n, days: fail.days, lastMs: fail.lastMs, nowMs: Date.now() })) {
      console.error('caseId=' + c.caseId + ' は ' + fail.n + ' 回失敗したため夜間ダイジェストを停止。手動確認が必要');
      result.skipped.push(c.caseId);
      continue;
    }
    const failureDays = Array.isArray(fail.days) ? fail.days.length : fail.n;
    if (failureDays >= 5) {
      props.deleteProperty(failKey);
      console.log('caseId=' + c.caseId + ' カウンタ期限切れのため再開');
      fail = { n: 0, lastMs: 0 };
    }
    fail = CaseDigest_recordFailure({ prev: fail, nowMs: Date.now() });
    props.setProperty(failKey, JSON.stringify(fail));
    try {
      const materials = Case_collectCaseMaterials(c, { unlimited: true });
      const fingerprint = CaseDigest_fingerprint(materials);
      const sh = CaseDigest_sheet_(c);
      const stored = sh ? sh.getRange('B2:B4').getDisplayValues() : [];
      if (stored.length && String(stored[0][0] || '') === fingerprint && String(stored[2][0] || '') === '完了') {
        props.deleteProperty(failKey);
        const old = ledger[c.caseId] || {};
        ledger[c.caseId] = { s: '完了', d: Number(old.d) || 0, t: Number(old.t) || 0, c: Date.now(), p: 0 };
        CaseDigest_saveLedger_(props, ledger);
        result.skipped.push(c.caseId); continue;
      }
      const built = CaseDigest_buildForCase(c.caseId, { materials: materials, fingerprint: fingerprint,
        partialSinceMs: ledger[c.caseId] && ledger[c.caseId].p });
      props.deleteProperty(failKey);
      result.processed.push(built);
      if (built.state === '部分') result.partial.push(c.caseId);
      const previous = ledger[c.caseId] || {};
      ledger[c.caseId] = { s: built.state, d: built.chunksDone, t: built.chunkTotal, c: Date.now(),
        p: built.state === '部分' ? (Number(previous.p) || Date.now()) : 0 };
      CaseDigest_saveLedger_(props, ledger);
    } catch (e) { result.errors.push({ caseId: c.caseId, error: String(e.message || e) }); }
  }
  console.log('CaseDigest nightly: processed=' + result.processed.length + ', skipped=' + result.skipped.length +
    ', failed=' + result.errors.length + ', remaining=' + result.remaining.length);
  return result;
}

function CaseDigest_setupNightlyTrigger() {
  if (!CaseDigest_getKey_()) return { skipped: 'OPENROUTER_API_KEY 未設定' };
  const alreadyInstalled = ScriptApp.getProjectTriggers().some(function (trigger) {
    return trigger.getEventType() === ScriptApp.EventType.CLOCK &&
      trigger.getHandlerFunction() === 'CaseDigest_nightlyRun';
  });
  if (alreadyInstalled) return { skipped: 'CaseDigest_nightlyRun trigger already installed' };
  ScriptApp.newTrigger('CaseDigest_nightlyRun').timeBased().everyDays(1)
    .atHour(1).nearMinute(0).create();
  return { removedOld: 0, created: 1, timesJst: ['1:00'] };
}

