function _debug_mailAttachmentsPlanAll() {
  const started = Date.now();
  const hardDeadlineAt = started + MAIL_ATTACH_RUN_HARD_DEADLINE_MS;
  const filtered = _MailAttach_filterCases(CaseList_listAll(), started);
  const ss = SpreadsheetApp.getActive();
  const logSheet = ss.getSheetByName(MAIL_ATTACH_LOG_SHEET);
  // 取込側 (_MailAttach_isSettled) と同じ判定にする。error 行は決着扱いにしない。
  // ここだけ判定が違うとプレビューと実際の取込がずれる。
  // ensureLogState はシートを新規作成しうるので debug からは呼ばず、読み取りだけで組む。
  const settledState = { keys: new Set(), errorCounts: {} };
  if (logSheet && logSheet.getLastRow() > 1) {
    logSheet.getRange(2, 11, logSheet.getLastRow() - 1, 3).getDisplayValues().forEach(function (row) {
      if (!row[0] || !row[1]) return;
      const key = String(row[0]) + ':' + String(row[1]);
      if (String(row[2] || '').indexOf('error') === 0) {
        settledState.errorCounts[key] = (settledState.errorCounts[key] || 0) + 1;
      } else {
        settledState.keys.add(key);
      }
    });
  }
  const result = { cases: [], totalWillUpload: 0, truncated: false };
  for (let i = 0; i < filtered.included.length; i++) {
    if (Date.now() > hardDeadlineAt) { result.truncated = true; break; }
    const c = filtered.included[i];
    const listed = _MailAttach_fetchJson({
      caseId: c.caseId,
      clientName: c.clientName || '',
      days: MAIL_ATTACH_LOOKBACK_DAYS
    }, 'plan:' + c.caseId);
    if (!listed.ok) {
      result.cases.push({ caseId: c.caseId, clientName: c.clientName, azukariFolderFound: false,
        willUpload: [], excludedCount: 0, error: listed.error });
      continue;
    }
    // 添付が無い案件でフォルダ解決をしない。解決は実施計画書を開くので1件あたり数秒かかり、
    // 全18案件でやると6分制限を超えて結果を書けずに死ぬ(実際に死んだ)。
    // 大半の案件は添付0件なので、ここを飛ばすだけで実行時間が桁で落ちる。
    const rawAttachments = listed.body.attachments || [];
    if (rawAttachments.length === 0) {
      result.cases.push({ caseId: c.caseId, clientName: c.clientName, azukariFolderFound: null,
        willUpload: [], excludedCount: (listed.body.excluded || []).length });
      continue;
    }
    // CaseList_listAll() の行は軽量で zissiId/projectFolderId を持たないため、
    // そのまま渡すとフォルダ解決が必ず失敗し azukariFolderFound:false になる
    // (実際に全案件 false になった)。解決には getById の完全な案件オブジェクトが必要。
    const full = CaseList_getById(c.caseId) || c;
    const folderId = _CaseManualPdf_findAzukariFolder(full) || '';
    const existingByName = {};
    if (folderId) {
      try {
        const files = DriveApp.getFolderById(folderId).getFiles();
        while (files.hasNext()) {
          const file = files.next();
          if (!existingByName[file.getName()]) existingByName[file.getName()] = {};
          existingByName[file.getName()][String(file.getSize())] = true;
        }
      } catch (e) {}
    }
    let excludedCount = (listed.body.excluded || []).length;
    const willUpload = [];
    rawAttachments.forEach(function (attachment) {
      const size = Number(attachment.size) || 0;
      const finalName = _MailAttach_finalName(attachment.name);
      if (_MailAttach_isSettled(settledState, _MailAttach_dupKey(attachment)) || attachment.oversize || size > MAIL_ATTACH_MAX_BYTES ||
          (existingByName[finalName] && existingByName[finalName][String(size)])) {
        excludedCount++;
        return;
      }
      // 同一添付が原メールと転送の2通に入ると messageId が別なので上の重複キーでは弾けない。
      // 実際の取込では保存直後に existingByName へ登録されて2通目が skipped_duplicate になるため、
      // プレビューでも同じ扱いにしないと件数を過大報告する (C0039 で 3件を6件と表示した)。
      if (!existingByName[finalName]) existingByName[finalName] = {};
      existingByName[finalName][String(size)] = true;
      willUpload.push({ name: attachment.name || '', finalName: finalName, size: size,
        prefix: _MailAttach_classifyPrefix(attachment.name), matchedVia: attachment.matchedVia || '' });
    });
    result.cases.push({ caseId: c.caseId, clientName: c.clientName,
      azukariFolderFound: Boolean(folderId), willUpload: willUpload, excludedCount: excludedCount });
    result.totalWillUpload += willUpload.length;
  }
  return result;
}

/**
 * 実行パネル用の1行サマリを付ける。saved/skipped/errors は配列なので
 * パネル側 (JobQueue/CommandQueue) からは件数が読めない。
 * skipped(配列) を真偽値の「スキップ」規約と混同しないよう、ここでは触らない。
 */
function _MailAttach_withPanelResult(r) {
  if (!r || typeof r !== 'object') return r;
  if (r.ok === false) {
    r.panelResult = '❌ 取込に失敗しました: ' + String(r.error || '不明なエラー').slice(0, 120);
    r.panelStatus = '❌ エラー';
    return r;
  }
  if (r.found === false) {
    r.panelResult = 'お客様メールが見つかりませんでした (顧客の紐付けを確認してください)';
    return r;
  }
  const saved = (r.saved || []).length;
  const dup = (r.skipped || []).filter(function (s) { return s && s.reason === 'duplicate'; }).length;
  const big = (r.skipped || []).filter(function (s) { return s && s.reason === 'too_large'; }).length;
  const err = (r.errors || []).length;
  if (saved === 0 && dup === 0 && big === 0 && err === 0) {
    r.panelResult = '新しい添付はありませんでした (取込済みのみ)';
    return r;
  }
  const parts = ['保存 ' + saved + '件'];
  if (dup) parts.push('既に取込済み ' + dup + '件');
  if (big) parts.push('サイズ超過 ' + big + '件');
  if (err) parts.push('エラー ' + err + '件');
  if (r.truncated) parts.push('時間切れのため続きは次回');
  r.panelResult = parts.join(' / ') + ' → 預かり素材フォルダ';
  return r;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    _MailAttach_withPanelResult: _MailAttach_withPanelResult,
    _MailAttach_classifyPrefix: _MailAttach_classifyPrefix
  };
}

function Mail_subjectLabel(caseName) {
  if (caseName === null || typeof caseName === 'undefined') return '';
  let label = String(caseName).split(/[\r\n]/)[0];
  label = label.split(' / ')[0];
  label = label.replace(/^[\s　]+|[\s　]+$/g, '').replace(/[\s　]+/g, ' ');
  if (label.length > 30) label = label.slice(0, 29) + '…';
  return label;
}

function Mail_externalSubject(caseId, caseName, purpose, tag) {
  const label = Mail_subjectLabel(caseName);
  return '[' + caseId + ']' + (tag ? '[' + tag + ']' : '') + ' ' + (label ? label + ' ' : '') + purpose;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { Mail_subjectLabel: Mail_subjectLabel, Mail_externalSubject: Mail_externalSubject };
}

/**
 * Growi マニュアル取り込み。Drive 一次ソース「社内マニュアル_NotebookLM連携」
 * フォルダ (1LMRI2jFpVG3WnDYlepgbOuyJ6ZBYzI8B) の Part01-13 Google Docs から
 * ページタイトル/パスを指定して本文を抽出する。
 *
 * 各 Part Doc は ~450KB のプレーンテキストで以下の構造を繰り返す:
 *   ### ページタイトル: <title>
 *   --- 内部パス: <path> ---
 *   ---------- マニュアル本文 ----------
 *   <body>
 *
 * WebFetch は使わず Drive 経由で取得（認証必須サイト対策、global rule）。
 */

const MANUAL_PARTS_FOLDER_ID = '1LMRI2jFpVG3WnDYlepgbOuyJ6ZBYzI8B';
const MANUAL_CACHE_PREFIX = 'manual_part_';
const MANUAL_INDEX_CACHE_KEY = 'manual_page_index_v1';
const MANUAL_CACHE_TTL_SEC = 21600; // 6h

function ManualLoader_freshnessCheck() {
  const parts = _Manual_listParts();
  if (parts.length === 0) {
    SpreadsheetApp.getUi().alert('Part01-13 が見つかりません。Drive フォルダ ID を確認してください。');
    return;
  }
  const now = new Date();
  const lines = parts.map(p => {
    const ageDays = Math.floor((now - p.modifiedTime) / (1000 * 60 * 60 * 24));
    const flag = ageDays > 90 ? ' ⚠️3ヶ月超' : '';
    return p.title + ' / 最終更新: ' + p.description + ' / Driveでの更新: ' + ageDays + '日前' + flag;
  });
  const oldest = Math.max(...parts.map(p => Math.floor((now - p.modifiedTime) / (1000 * 60 * 60 * 24))));
  const warning = oldest > 90
    ? '\n\n⚠️ 最古ファイルが3ヶ月超古いです。GAS の取り込みフローが止まっている可能性があります。'
    : '';
  SpreadsheetApp.getUi().alert('マニュアル鮮度', lines.join('\n') + warning, SpreadsheetApp.getUi().ButtonSet.OK);
}

/**
 * ページタイトル（部分一致）または内部パス（部分一致）でページを検索し本文を返す。
 * @return {Array<{title, path, body, partTitle}>} マッチしたページのリスト
 */
function ManualLoader_findPages(queries) {
  // queries: ['ページタイトル文字列', '/path/to/page', ...] — 単一文字列でも可
  if (typeof queries === 'string') queries = [queries];
  const index = _Manual_buildIndex();
  const results = [];
  const seen = {};
  queries.forEach(q => {
    if (!q) return;
    const qNorm = String(q).trim();
    index.forEach(entry => {
      const matchByPath = qNorm.indexOf('/') >= 0 && entry.path.indexOf(qNorm) >= 0;
      const matchByTitle = entry.title.indexOf(qNorm) >= 0 || entry.path.indexOf(qNorm) >= 0;
      if ((matchByPath || matchByTitle) && !seen[entry.partId + '#' + entry.startOffset]) {
        seen[entry.partId + '#' + entry.startOffset] = true;
        let body = '';
        try { body = _Manual_extractBody(entry); }
        catch (e) { body = '(本文取得失敗: ' + e.message + ')'; }
        results.push({
          title: entry.title,
          path: entry.path,
          partTitle: entry.partTitle,
          body: body
        });
      }
    });
  });
  return results;
}

function ManualLoader_findFirst(query) {
  const r = ManualLoader_findPages(query);
  return r.length > 0 ? r[0] : null;
}

// -------- internals --------

function _Manual_listParts() {
  const cache = CacheService.getScriptCache();
  const cached = cache.get('manual_part_list');
  if (cached) {
    return JSON.parse(cached).map(p => ({ ...p, modifiedTime: new Date(p.modifiedTime) }));
  }
  const folder = DriveApp.getFolderById(MANUAL_PARTS_FOLDER_ID);
  const it = folder.getFilesByType(MimeType.GOOGLE_DOCS);
  const parts = [];
  while (it.hasNext()) {
    const f = it.next();
    const title = f.getName();
    if (title.indexOf('_Part') < 0) continue;
    parts.push({
      id: f.getId(),
      title: title,
      description: f.getDescription() || '',
      modifiedTime: f.getLastUpdated()
    });
  }
  parts.sort((a, b) => a.title.localeCompare(b.title));
  cache.put('manual_part_list', JSON.stringify(parts.map(p => ({
    ...p, modifiedTime: p.modifiedTime.toISOString()
  }))), MANUAL_CACHE_TTL_SEC);
  return parts;
}

function _Manual_getPartText(partId) {
  const cache = CacheService.getScriptCache();
  const key = MANUAL_CACHE_PREFIX + partId;
  const cached = cache.get(key);
  if (cached) return cached;
  const url = 'https://docs.google.com/feeds/download/documents/export/Export?id=' +
    partId + '&exportFormat=txt';
  // 429 rate limit に対して exponential backoff で 3 回まで再試行
  let lastCode = 0;
  for (let attempt = 0; attempt < 3; attempt++) {
    if (attempt > 0) Utilities.sleep(1500 * attempt);
    const response = UrlFetchApp.fetch(url, {
      headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() },
      muteHttpExceptions: true
    });
    lastCode = response.getResponseCode();
    if (lastCode === 200) {
      const text = response.getContentText();
      if (text.length < 90000) {
        cache.put(key, text, MANUAL_CACHE_TTL_SEC);
      }
      return text;
    }
    if (lastCode !== 429 && lastCode !== 500 && lastCode !== 503) break;
  }
  throw new Error('Part 取得失敗: ' + partId + ' / ' + lastCode);
}

function _Manual_buildIndex() {
  const cache = CacheService.getScriptCache();
  const cached = cache.get(MANUAL_INDEX_CACHE_KEY);
  if (cached) return JSON.parse(cached);
  const parts = _Manual_listParts();
  const index = [];
  const titleRe = /### ページタイトル:\s*(.+?)[\r\n]+--- 内部パス:\s*(.+?)\s*---/g;
  const failedParts = [];
  parts.forEach(p => {
    let text;
    try {
      text = _Manual_getPartText(p.id);
    } catch (e) {
      failedParts.push(p.title + ' (' + e.message + ')');
      return;
    }
    let m;
    while ((m = titleRe.exec(text)) !== null) {
      index.push({
        title: m[1].trim(),
        path: m[2].trim(),
        partId: p.id,
        partTitle: p.title,
        startOffset: m.index
      });
    }
  });
  if (failedParts.length > 0) {
    console.warn('manual buildIndex: skipped failing parts: ' + failedParts.join(', '));
  }
  // インデックスは大きすぎる可能性があるので圧縮しない形で保存試行、ダメなら諦める
  try {
    cache.put(MANUAL_INDEX_CACHE_KEY, JSON.stringify(index), MANUAL_CACHE_TTL_SEC);
  } catch (e) {
    // 100KB 超なら諦めて毎回再構築（保守的）
  }
  return index;
}

function _Manual_extractBody(entry) {
  const text = _Manual_getPartText(entry.partId);
  // entry.startOffset から次の「### ページタイトル:」まで抜き出し、本文以降を切り出す
  const headerEnd = text.indexOf('---------- マニュアル本文 ----------', entry.startOffset);
  if (headerEnd < 0) return '';
  const bodyStart = headerEnd + '---------- マニュアル本文 ----------'.length;
  const next = text.indexOf('### ページタイトル:', bodyStart);
  const bodyEnd = next < 0 ? text.length : next;
  return text.substring(bodyStart, bodyEnd).trim();
}

