      parts.push((rowLabels[item.type] || String(item.type || '')) + ': ' + item.row + '行目 ' +
        'https://docs.google.com/a/orgiast.jp/spreadsheets/d/' + _ASSIGN_SS_ID + '/edit?gid=' + _ASSIGN_SHEET_GID + '&range=A' + item.row);
    });
