const COST_PROFIT_SHEET_NAME = 'Claude_原価粗利';
const COST_PROFIT_FILE_SHEET_NAME = 'Claude_原価粗利_ファイル';
const COST_PROFIT_HEADERS = ['更新日時', '区分', '仕入先', '項目', '仕様', '数量', '単位', '単価', '金額', '出典', '信頼度', 'メモ', 'ファイルを開く'];
