];
const _PROCURE_PURCHASE_SS_ID = '1Uu0bdtI9AnHVJ9325SsbGIEWxl1uk3z8e9jzp0aF2RU';
const _PROCURE_PURCHASE_SHEET = '購買依頼フォーム';
