    '}',
    '',
    '## 重要ルール',
    '- 単価は「価格表抜粋」の該当項目から該当する価格を選んで設定すること。価格表にない場合は 0 にして confirmations に「○○の単価要確認」を入れる。',
    '- mgmt の項目は案件情報や価格表から確実に決められるもののみ記入。担当者氏名・電話・メールなどお客様情報は記入せず confirmations に「○○未取得」と入れること（捏造禁止）。',
    '- mgmt の弊社担当は不明なら空欄。コードはアルファベットのみ（例: CTKTSS）。',
    '- 利用回数は新規/2回目以降 を案件状況から判断。',
    '- qtyUnit は「式」「日」「人」など。',
    '- category は見積テンプレで使われる大分類「イベント」「運営・制作」など。',
    '- 議事録に記載がある場合は その内容を優先し、 一般論より具体的に。',
  ]).join('\n');

  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    maxTokens: 6000
  });

  const parsed = _Phase1_parseJson(res.text);
  const items = parsed.items || [];
  const mgmt = parsed.mgmt || {};

  // 5) 管理画面に案件/客様情報を書き込み
  const mgmtSheet = _Estimate_findMgmtSheet(ss);
  if (mgmtSheet) {
    _Estimate_fillMgmtFields(mgmtSheet, mgmt);
  }

  // 6) 明細セクションに書き込み
  //   - 開始行: ヘッダ + 4（ヘッダ／ガード／イベント placeholder／運営制作 placeholder の次）
  //   - 各行で 項目小計 (col L) と 消費税 (col M) に数式を明示的に設定
  const target = _Estimate_findDetailHeaderRow(ss);
  if (target) {
    const startRow = target.row + 4;
    items.forEach((it, idx) => {
      const row = startRow + idx;
      target.sheet.getRange(row, 1).setValue(it.category || '');
      target.sheet.getRange(row, 2).setValue(it.itemName || '');
      target.sheet.getRange(row, 3).setValue(it.content || '');
      if (it.note) target.sheet.getRange(row, 4).setValue(it.note);
      target.sheet.getRange(row, 5).setValue(it.unitPrice || 0);
      target.sheet.getRange(row, 6).setValue(it.qty || 1);
      target.sheet.getRange(row, 7).setValue(it.qtyUnit || '式');
      target.sheet.getRange(row, 12).setFormula('=E' + row + '*F' + row);   // 項目小計
      target.sheet.getRange(row, 13).setFormula('=L' + row + '*0.1');       // 消費税
    });
    // 7-pre) オプション欄のテンプレ既存項目（木槌レンタル等）をクリア
    _Estimate_clearOptionSection(target.sheet, startRow + items.length);
  }

  // 7) legacy 統合: アプローチリストFOLDER 下にプロジェクトフォルダ作成 + 見積を移動
  let projectFolderUrl = null;
  let projectFolderId = null;
  let zissiUrl = null;
  let teisyutuUrl = null;
  try {
    const approachList = DriveApp.getFolderById(LEGACY_APPROACH_LIST_FOLDER_ID);
    const category = (mgmt['商品カテゴリ'] || 'イベント');
    const projectFolderName = (mgmt['コード'] || c.caseId) + '_' + c.clientName + '_' + c.caseName;
    const existingProjectFolders = approachList.getFoldersByName(projectFolderName);
    const hasExistingProjectFolder = existingProjectFolders.hasNext();
    const projectFolder = hasExistingProjectFolder ? existingProjectFolders.next() : approachList.createFolder(projectFolderName);
    if (hasExistingProjectFolder) console.log('既存を再利用: ' + projectFolderName);
    projectFolderId = projectFolder.getId();
    projectFolderUrl = projectFolder.getUrl();

    // 見積を案件フォルダ (My Drive 配下) から legacy プロジェクトフォルダへ移動
    DriveApp.getFileById(copy.getId()).moveTo(projectFolder);

    // 見積の解説!B75 にプロジェクトフォルダID（legacy 慣習）
    const kaisetuSheet = ss.getSheetByName('解説');
    if (kaisetuSheet) {
      kaisetuSheet.getRange('B75').setValue(projectFolderId);
    }

    // 8) 実施計画書テンプレを複製 → legacy プロジェクトフォルダへ
    const zissiTemplate = DriveApp.getFileById(LEGACY_ZISSI_TEMPLATE_ID);
    const zissiName = (mgmt['コード'] || c.caseId) + '_' + c.caseName + '_実施計画書';
    const existingZissi = projectFolder.getFilesByName(zissiName);
    const hasExistingZissi = existingZissi.hasNext();
    const zissiCopy = hasExistingZissi ? existingZissi.next() : zissiTemplate.makeCopy(zissiName, projectFolder);
    if (hasExistingZissi) console.log('既存を再利用: ' + zissiName);
    const zissiSs = SpreadsheetApp.openById(zissiCopy.getId());
    zissiUrl = zissiSs.getUrl();

    // 9) 提出フォーマットテンプレを複製 → legacy プロジェクトフォルダへ
    const teisyutuTemplate = DriveApp.getFileById(LEGACY_TEISYUTU_TEMPLATE_ID);
    const teisyutuName = (mgmt['コード'] || c.caseId) + '_' + c.caseName + '_ご提出フォーマット';
    const existingTeisyutu = projectFolder.getFilesByName(teisyutuName);
    const hasExistingTeisyutu = existingTeisyutu.hasNext();
    const teisyutuCopy = hasExistingTeisyutu ? existingTeisyutu.next() : teisyutuTemplate.makeCopy(teisyutuName, projectFolder);
    if (hasExistingTeisyutu) console.log('既存を再利用: ' + teisyutuName);
    const teisyutuSs = SpreadsheetApp.openById(teisyutuCopy.getId());
    teisyutuUrl = teisyutuSs.getUrl();

    // 10) 実施計画書 settei シートに URL 群を埋め込み (legacy MakeZissiSS と同様)
    const settei = zissiSs.getSheetByName('settei');
    if (settei) {
      settei.getRange('B1').setValue(zissiUrl);      // 実施計画書URL
      settei.getRange('B3').setValue(ss.getUrl());   // 見積URL
      settei.getRange('B4').setValue(teisyutuUrl);   // 提出フォーマットURL
      settei.getRange('B6').setValue(projectFolderUrl); // 製作フォルダURL
    }

    // 11) 実施計画の task シートに 納品日 を埋め込み (legacy MakeZissiSS line 514-)
    const taskSheet = zissiSs.getSheetByName('task');
    if (taskSheet) {
      const today = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy/MM/dd');
      taskSheet.getRange('E6').setValue(today);
      taskSheet.getRange('E10').setValue(today);
      if (c.endDate) {
        const nouki = (c.endDate instanceof Date)
          ? Utilities.formatDate(c.endDate, 'Asia/Tokyo', 'yyyy/MM/dd')
          : String(c.endDate);
        taskSheet.getRange('S2').setValue(nouki);
      }
    }

    // 12) 管理画面の「実施計画URL」フィールドにも書き込み
    if (mgmtSheet) _Estimate_fillMgmtFields(mgmtSheet, { '実施計画URL': zissiUrl });

    // 12.5) 案件一覧の K列(実施計画書ID)・L列(プロジェクトフォルダID) に保存
    //       → ③ スケジュール生成がこの実施計画書を直接開けるようにする
    CaseList_setZissiInfo(caseId, zissiCopy.getId(), projectFolderId);

    // 案件一覧 master 登録 (legacy AddtoYosanUrl 相当の最小実装)
    const ankenRegistered = _Estimate_registerInAnkenMaster({
      clientName: c.clientName,
      caseName: c.caseName,
      mitumoriUrl: ss.getUrl(),
      zissiUrl: zissiUrl
    });
    if (ankenRegistered === true) {
      parsed.confirmations = (parsed.confirmations || []).concat([{
        category: '見積/案件マスタ',
        content: '案件マスタ ' + LEGACY_ANKEN_MASTER_URL + ' に新規行を追加しました。予算項目セルは隣接行から自動継承。確認・修正してください。'
      }]);
    } else {
      parsed.confirmations = (parsed.confirmations || []).concat([{
        category: '見積/案件マスタエラー',
        content: '案件マスタ登録失敗: ' + ankenRegistered
      }]);
    }
  } catch (e) {
    // legacy 統合に失敗しても見積生成は続行
    parsed.confirmations = (parsed.confirmations || []).concat([{
      category: '見積/legacy統合エラー',
      content: 'プロジェクトフォルダ作成/実施計画複製で失敗: ' + e.toString()
    }]);
  }

  // 8) 確認事項
  if (parsed.confirmations && parsed.confirmations.length > 0) {
    ConfirmationSheet_appendItems(caseId, parsed.confirmations.map(x => ({
      ...x, category: '見積/' + (x.category || '')
    })), 1);
  }
  CaseList_touchUpdatedAt(caseId);

  MasterWriteBack_recordArtifact(caseId, '見積', '見積初版', ss.getUrl());
  if (zissiUrl) MasterWriteBack_recordArtifact(caseId, '実施計画書', '実施計画書', zissiUrl);

  let costProfitQueued = false;
  try { costProfitQueued = _CostProfit_enqueue(caseId); } catch (e) {}

  return {
    estimateSheetUrl: ss.getUrl(),
    projectFolderUrl: projectFolderUrl,
    zissiSheetUrl: zissiUrl,
    teisyutuSheetUrl: teisyutuUrl,
    itemCount: items.length,
    mgmtFilledCount: Object.keys(mgmt).length,
    confirmationCount: (parsed.confirmations || []).length,
    headerRow: target ? target.row : null,
    detailSheetName: target ? target.sheet.getName() : null,
    mgmtSheetName: mgmtSheet ? mgmtSheet.getName() : null,
    usage: res.usage,
    costProfit: { queued: costProfitQueued }
  };
}

// -------- internals --------

function _Estimate_loadPriceList() {
  const ss = SpreadsheetApp.openById(ESTIMATE_PRICE_LIST_ID);
  const sheets = ss.getSheets();
  const out = [];
  ESTIMATE_PRICE_RELEVANT_SHEETS.forEach(name => {
    const sheet = sheets.find(function (s) { return s.getName() === name; });
    if (!sheet) return;
    const lastRow = sheet.getLastRow();
    const lastCol = sheet.getLastColumn();
    if (lastRow === 0 || lastCol === 0) return;
    const values = sheet.getRange(1, 1, Math.min(lastRow, 200), Math.min(lastCol, 12)).getValues();
    const text = values.map(function (row) {
      return row.map(function (v) { return String(v); }).join('\t');
    }).filter(function (line) { return line.replace(/[\t\s]/g, '').length > 0; }).join('\n');
    out.push('### ' + name + '\n' + text);
  });
  return out.join('\n\n');
}

function _Estimate_findDetailHeaderRow(ss) {
  const sheets = ss.getSheets();
  for (let s = 0; s < sheets.length; s++) {
    const sheet = sheets[s];
    const lastRow = sheet.getLastRow();
    if (lastRow < 2) continue;
    const lastCol = Math.min(sheet.getLastColumn(), 14);
    if (lastCol < 5) continue;
    const data = sheet.getRange(1, 1, lastRow, lastCol).getValues();
    for (let r = 0; r < data.length; r++) {
      if (data[r][0] === 'カテゴリ' && data[r][1] === '項目' && data[r][4] === '単価') {
        return { sheet: sheet, row: r + 1 };
      }
    }
  }
  return null;
}

function _Estimate_registerInAnkenMaster(payload) {
  // legacy AddtoYosanUrl の setList 構造を踏襲し、案件マスタの案件一覧シート2行目に新規行を挿入。
  // setList 9列: [予算項目, "アプローチリスト", 顧客名, 実施計画URL, 見積URL, 範囲指定, vlookup式, countif式, importrange式]
  try {
    const target = SpreadsheetApp.openByUrl(LEGACY_ANKEN_MASTER_URL);
    const sheet = target.getSheetByName('案件一覧');
    if (!sheet) return '案件一覧 シートが見つかりません: ' + LEGACY_ANKEN_MASTER_URL;

    // 予算項目: 既存3行目の A列を継承（同じ期を使う）
    let yosanName = '';
    try { yosanName = String(sheet.getRange(3, 1).getValue() || ''); } catch (e) { /* keep empty */ }

    sheet.insertRowsBefore(2, 1);
    sheet.getRange(2, 1, 1, 9).setValues([[
      yosanName,
      'アプローチリスト',
      payload.clientName || '',
      payload.zissiUrl || '',
      payload.mitumoriUrl || '',
      '管理画面（正式）※シート名変更禁止!A2:AE2',
      "=vlookup(E2, '請求コードチェック'!A:P, 16, false)",
      '=countif(E:E, E2)',
      '=importrange(indirect("E"&row()),indirect("F"&row()))'
    ]]);
    try {
      sheet.getRange('BG2:CF2').setBorder(true, true, true, true, true, true);
    } catch (e) { /* 罫線失敗は無視 */ }
    SpreadsheetApp.flush();
    return true;
  } catch (e) {
    return e.toString();
  }
}

function _Estimate_clearOptionSection(sheet, fromRow) {
  // 「オプション」見出し行を fromRow 以降で探し、その下から次の「項目計」行の手前まで
  // 明細列（A〜G）をクリア。テンプレデフォルトの木槌レンタル等を削除する目的。
  // セル結合があっても拾えるよう全列をスキャンして文字列結合で判定する。
  const lastRow = sheet.getLastRow();
  if (lastRow <= fromRow) return;
  const lastCol = Math.min(sheet.getLastColumn(), 14);
  if (lastCol < 1) return;
  const range = sheet.getRange(fromRow, 1, lastRow - fromRow + 1, lastCol).getValues();
  let optRow = -1;
  let nextKei = -1;
  for (let i = 0; i < range.length; i++) {
    const rowText = range[i].map(function (v) { return String(v || ''); }).join(' ');
    if (optRow < 0 && rowText.indexOf('オプション') >= 0) {
      optRow = fromRow + i;
      continue;
    }
    if (optRow > 0 && rowText.indexOf('項目計') >= 0) {
      nextKei = fromRow + i;
      break;
    }
  }
  if (optRow > 0 && nextKei > optRow + 1) {
    sheet.getRange(optRow + 1, 1, nextKei - optRow - 1, 7).clearContent();
  }
}

function _Estimate_findMgmtSheet(ss) {
  // 「サービス希望者」「商品カテゴリ」が縦並びで A 列に並んでいるシート（管理画面（正式））を検出
  const sheets = ss.getSheets();
  for (let s = 0; s < sheets.length; s++) {
    const sheet = sheets[s];
    const lastRow = sheet.getLastRow();
    if (lastRow < 5) continue;
    const data = sheet.getRange(1, 1, lastRow, 1).getValues();
    let svcRow = -1, catRow = -1;
    for (let r = 0; r < data.length; r++) {
      if (data[r][0] === 'サービス希望者') svcRow = r;
      if (data[r][0] === '商品カテゴリ') catRow = r;
    }
    if (svcRow >= 0 && catRow >= 0) return sheet;
  }
  return null;
}

function _Estimate_fillMgmtFields(sheet, mgmt) {
  // ラベルを A 列で検索し、その同じ行の B 列に値を書き込む
  const lastRow = sheet.getLastRow();
  if (lastRow < 1) return 0;
  const labels = sheet.getRange(1, 1, lastRow, 1).getValues();
  let written = 0;
  Object.keys(mgmt).forEach(function (key) {
    const value = mgmt[key];
    if (value === undefined || value === null || value === '') return;
    for (let r = 0; r < labels.length; r++) {
      if (labels[r][0] === key) {
        sheet.getRange(r + 1, 2).setValue(value);
        written++;
        break;
      }
    }
  });
  return written;
}

/**
 * 見積のみ生成（既存案件用）。 実施計画書 / プロジェクトフォルダは作らない。
 * 実行パネル・メニューから 既に立ち上がっている案件の見積を作りたい時に使う。
 * 出力先: 案件のプロジェクトフォルダ (無ければ案件フォルダ)。 ファイル名に日時を付けて重複回避。
 */
function Phase1_EstimateOnly_generate(caseId, pastedText) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);

  // 1) テンプレ複製 → 既存プロジェクトフォルダへ
  const destFolderId = Case_resolveProjectRoot(c);
  if (!destFolderId) throw new Error('案件フォルダが未設定です (案件一覧 L列)。先に「master → アプリ 同期」を実行してください。');
  const stamp = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'MMdd_HHmm');
  const newName = c.caseId + '_' + c.caseName + '_見積_' + stamp;
  const copy = DriveApp.getFileById(ESTIMATE_TEMPLATE_ID).makeCopy(newName, DriveApp.getFolderById(destFolderId));
  const ss = SpreadsheetApp.openById(copy.getId());
  const innerStockSheet = ss.getSheetByName(ESTIMATE_INTERNAL_STOCK_SHEET_NAME);
  if (innerStockSheet) { try { ss.deleteSheet(innerStockSheet); } catch (e) {} }

  // 2) 価格表 + マニュアル
  const priceListText = _Estimate_loadPriceList();
  const manualPages = ManualLoader_findPages(['見積書に売値をいれる', '原価の反映', '見積書をPDFにしてお客様へ送る']);
  const cachedContext = [
    Case_loadClientContext(c),
    '【関連マニュアル抜粋】',
    ...manualPages.map(p => '# ' + p.title + '\nパス: ' + p.path + '\n\n' + p.body),
    '【価格表抜粋】\n' + priceListText
  ].filter(Boolean);

  // 3) Claude 生成 (新規版と同じ出力形式)
  const userPrompt = [
    '以下の展示会ブース案件について、見積の明細項目と管理画面の埋められる項目を提案してください。',
    '',
    '## 案件情報',
    '- クライアント: ' + c.clientName,
    '- 案件名: ' + c.caseName,
    '- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate),
    '- ブースサイズ: ' + (c.boothSize || '未確定'),
    '- 案件ID: ' + c.caseId,
    '',
    String(pastedText || '').trim() ? '## 📝貼付欄の直接指示（他の情報より優先）\n' + String(pastedText).trim().slice(0, 12000) + '\n' : '',
    '## 出力形式（厳守・前後の説明文不要）',
    '{',
    '  "items": [',
    '    {"category": "イベント|運営・制作", "itemName": "...", "content": "...", "unitPrice": 60000, "qty": 1, "qtyUnit": "式", "note": "..."}',
    '  ],',
    '  "mgmt": { "商品カテゴリ": "イベント", "サービス希望者": "<クライアント名>", "案件名": "<案件名>", "弊社担当": "金功勇", "コード": "<アルファベットのみ>", "利用回数": "2回目以降", "案件ルート": "...", "場所": "...", "希望納期": "..." },',
    '  "confirmations": [ {"category": "...", "content": "..."} ]',
    '}',
    '',
    '## 重要ルール',
    '- 単価は「価格表抜粋」から選ぶ。無い場合は 0 + confirmations に「○○の単価要確認」。',
    '- お客様の担当者情報は捏造せず confirmations に「○○未取得」。',
    '- qtyUnit は「式」「日」「人」など。 category は「イベント」「運営・制作」など。'
  ].join('\n');

  const res = ClaudeClient_call({ cachedContext: cachedContext, userMessage: userPrompt, maxTokens: 6000 });
  const parsed = _Phase1_parseJson(res.text);
  const items = parsed.items || [];
  const mgmt = parsed.mgmt || {};

  // 4) 管理画面 + 明細書き込み (新規版と同一手順)
  const mgmtSheet = _Estimate_findMgmtSheet(ss);
  let mgmtFilled = 0;
  if (mgmtSheet) mgmtFilled = _Estimate_fillMgmtFields(mgmtSheet, mgmt);
  const target = _Estimate_findDetailHeaderRow(ss);
  if (target) {
    const startRow = target.row + 4;
    items.forEach((it, idx) => {
      const row = startRow + idx;
      target.sheet.getRange(row, 1).setValue(it.category || '');
      target.sheet.getRange(row, 2).setValue(it.itemName || '');
      target.sheet.getRange(row, 3).setValue(it.content || '');
      if (it.note) target.sheet.getRange(row, 4).setValue(it.note);
      target.sheet.getRange(row, 5).setValue(it.unitPrice || 0);
      target.sheet.getRange(row, 6).setValue(it.qty || 1);
      target.sheet.getRange(row, 7).setValue(it.qtyUnit || '式');
      target.sheet.getRange(row, 12).setFormula('=E' + row + '*F' + row);
      target.sheet.getRange(row, 13).setFormula('=L' + row + '*0.1');
    });
    _Estimate_clearOptionSection(target.sheet, startRow + items.length);
  }

  // 5) 確認事項 + 生成物記録
  const confirmations = parsed.confirmations || [];
  if (confirmations.length > 0) {
    try { ConfirmationSheet_appendItems(caseId, confirmations, '[見積]'); } catch (e) {}
  }
  const url = ss.getUrl();
  try { MasterWriteBack_recordArtifact(caseId, '見積', newName, url); } catch (e) {}
  CaseList_touchUpdatedAt(caseId);

  let costProfitQueued = false;
  try { costProfitQueued = _CostProfit_enqueue(caseId); } catch (e) {}

  return {
    url: url,
    estimateSheetUrl: url,
    itemCount: items.length,
    mgmtFilledCount: mgmtFilled,
    confirmationCount: confirmations.length,
    usage: res.usage,
    costProfit: { queued: costProfitQueued }
  };
}

/**
 * Phase1: 全体スケジュール 初版 を生成（schedule(4ヵ月) シート貼り付け方式）。
 *
 * 流れ:
 *  1) Phase1_Estimate が作成した実施計画書を探す
 *  2) パーツマスタの「schedule（4ヵ月）」シート (gid=1089324704) を実施計画書にコピー
 *     既に「スケジュール」シートがある場合はスキップ
 *  3) Claude にマニュアル + 案件情報を渡してマイルストーン JSON 生成
 *  4) **コピーしたスケジュールシートには直接書かない**（数式・体裁を壊さないため）
 *     代わりに別シート「Claude_マイルストーン提案」を作って書き込み、user 側で参照
 *  5) 確認事項を確認シートに積む
 *
 * NOTE:
 *  - 4ヵ月横長テンプレの正確なセル位置（タスク列・日付列）が判別困難なため、
 *    今は提案シート方式。テンプレ構造が判明したら直接書き込みに切替予定。
 */

const SCHEDULE_SOURCE_SS_ID = '1_zbmz8LReBsLRynQ7oIxdyXEwzw7mMnnbULsQcAFfio';
const SCHEDULE_SOURCE_GID = 1089324704; // schedule（4ヵ月）
const SCHEDULE_TARGET_NAME = 'スケジュール';
const SCHEDULE_PROPOSAL_NAME = 'Claude_マイルストーン提案';

function Phase1_Schedule_generate(caseId) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);

  // 1) 実施計画書を探す
  const zissiSs = _Schedule_findExistingZissi(c);
  if (!zissiSs) {
    throw new Error('実施計画書が見つかりません。先に ② 見積 初版 を生成 を実行してください。');
  }

  // 2) schedule（4ヵ月）シートを実施計画書にコピー（未存在時のみ）
  let scheduleSheet = zissiSs.getSheetByName(SCHEDULE_TARGET_NAME);
  let copiedThisRun = false;
  if (!scheduleSheet) {
    const sourceSs = SpreadsheetApp.openById(SCHEDULE_SOURCE_SS_ID);
    const sourceSheet = sourceSs.getSheets().find(function (s) {
      return s.getSheetId() === SCHEDULE_SOURCE_GID;
    });
    if (!sourceSheet) {
      throw new Error('パーツマスタに schedule(4ヵ月) シート (gid=' + SCHEDULE_SOURCE_GID + ') が見つかりません');
    }
    scheduleSheet = sourceSheet.copyTo(zissiSs);
    scheduleSheet.setName(SCHEDULE_TARGET_NAME);
    copiedThisRun = true;
  }

  // 2.5) summary シート provisioning (スケジュール!#REF! の解消)
  //      スケジュール sheet の数式は =summary!D5(社名) / =summary!D13(案件名) / =summary!D19(開催日) を参照
  const fillResult = _Schedule_provisionSummarySheet(zissiSs, c);

  // 2.52) row 1 / row 6 ヘッダーを復元（コピー構造とテンプレ構造の両方に対応）
  //       過去の壊れた forceRecalc 実装で label が消えたシートにも対応するため、
  //       label/formula を毎回 set。merge 構造が異なる 2 系統に同時対応:
  //       - 現行コピー row 1: N1=開催日, R1=date, X1=内容, AB1=case, BF1=作成日, BJ1=今日, BT1=case
  //       - テンプレ系 row 1: S1=開催日, W1=date, AC1=内容, AG1=case, BK1=作成日, BO1=今日
  //       - 現行コピー row 6: A6/W6/AS6/BO6=日付, F6/AB6/AX6/BT6=内容
  //       - テンプレ系 row 6: A6/S6/AK6/BC6=日付, F6/X6/AP6/BH6=内容
  //       merge top-left でないセルへの書き込みは無視されるので両系統に投げて害なし
  try {
    // row 1
    scheduleSheet.getRange('A1').setValue('　■制作スケジュール');
    scheduleSheet.getRange('N1').setValue('開催日');
    scheduleSheet.getRange('S1').setValue('開催日');
    scheduleSheet.getRange('X1').setValue('内容');
    scheduleSheet.getRange('AC1').setValue('内容');
    scheduleSheet.getRange('BF1').setValue('作成日');
    scheduleSheet.getRange('BK1').setValue('作成日');
    scheduleSheet.getRange('BJ1').setFormula('=TODAY()');
    scheduleSheet.getRange('BO1').setFormula('=TODAY()');
    scheduleSheet.getRange('BT1').setFormula('=summary!D5&"様 "&summary!D13');
    // row 1 の日付セルを yyyy/MM/dd 表示に
    ['R1', 'W1', 'BJ1', 'BO1'].forEach(function (a) {
      try { scheduleSheet.getRange(a).setNumberFormat('yyyy/MM/dd'); } catch (e) {}
    });
    // row 6 (日付/内容ヘッダー — コピー版 + テンプレ版の両系統)
    ['A6', 'W6', 'AS6', 'BO6', 'S6', 'AK6', 'BC6'].forEach(function (a) {
      try { scheduleSheet.getRange(a).setValue('日付'); } catch (e) {}
    });
    ['F6', 'AB6', 'AX6', 'BT6', 'X6', 'AP6', 'BH6'].forEach(function (a) {
      try { scheduleSheet.getRange(a).setValue('内容'); } catch (e) {}
    });
  } catch (e) { /* skip */ }

  // 2.55) スケジュールシートの数式を強制再評価（#REF! キャッシュ解消）
  //       数式セルだけ setFormula で書き戻す（非数式セルのテキストラベルは保持）
  _Schedule_forceRecalcFormulas(scheduleSheet);

  // 2.6) 診断: スケジュールシートの row 1-10 構造を Claude_診断 Doc に dump
  _Schedule_dumpDiagnostic(zissiSs, scheduleSheet, fillResult);

  // 3) Claude でマイルストーン生成
  const manualPages = ManualLoader_findPages([
    'スケジュールシートの作成（全体スケジュール）'
  ]);
  const cachedContext = [
    Case_loadClientContext(c),
    '【関連マニュアル抜粋】',
    ...manualPages.map(function (p) { return '# ' + p.title + '\nパス: ' + p.path + '\n\n' + p.body; })
  ].filter(Boolean);

  const userPrompt = [
    '以下の案件の全体スケジュール（初版）を、出展開始日から逆算して作成してください。',
    '',
    '## 案件情報',
    '- クライアント: ' + c.clientName,
    '- 案件名: ' + c.caseName,
    '- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate),
    '- ブースサイズ: ' + (c.boothSize || '未確定'),
    '',
    '## 出力形式（厳守・前後の説明文不要）',
    '{',
    '  "milestones": [',
    '    {"task": "...", "owner": "...", "dueDate": "yyyy/MM/dd", "note": "..."}',
    '  ],',
    '  "confirmations": [',
    '    {"category": "...", "content": "..."}',
    '  ]',
    '}',
    '',
    '注意:',
    '- 出展期間が未確定の場合は milestones を空にして confirmations に「出展期間の確定」を入れる。',
    '- owner は社内の確定情報がなければ空文字にすること（人名を捏造しない）。',
    '- マニュアルが定める標準工程を網羅すること。',
    '- マイルストーンは出展日から逆算した期日 (dueDate) を必ず入れる。'
  ].join('\n');

  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    maxTokens: 4000
  });

  const parsed = _Phase1_parseJson(res.text);
  const milestones = parsed.milestones || [];

  // 3.5) マイルストーンをスケジュール（4ヵ月）カレンダーの該当日 内容セルに書き込み
  const calendarWriteLog = _Schedule_writeMilestonesToCalendar(scheduleSheet, milestones);

  // 4) Claude_マイルストーン提案 シートに書き込み（毎回上書き）
  let proposalSheet = zissiSs.getSheetByName(SCHEDULE_PROPOSAL_NAME);
  if (!proposalSheet) {
    proposalSheet = zissiSs.insertSheet(SCHEDULE_PROPOSAL_NAME);
  } else {
    proposalSheet.clear();
  }
  proposalSheet.getRange(1, 1, 1, 4).setValues([['タスク', '担当', '期日', '備考']]);
  proposalSheet.getRange(1, 1, 1, 4).setFontWeight('bold').setBackground('#cfe2f3');
  proposalSheet.setFrozenRows(1);
  if (milestones.length > 0) {
    const rows = milestones.map(function (m) {
      return [m.task || '', m.owner || '', m.dueDate || '', m.note || ''];
    });
    proposalSheet.getRange(2, 1, rows.length, 4).setValues(rows);
  }
  proposalSheet.setColumnWidth(1, 320);
  proposalSheet.setColumnWidth(2, 80);
  proposalSheet.setColumnWidth(3, 110);
  proposalSheet.setColumnWidth(4, 400);

  // 5) 確認事項
  if (parsed.confirmations && parsed.confirmations.length > 0) {
    ConfirmationSheet_appendItems(caseId, parsed.confirmations.map(function (x) {
      return Object.assign({}, x, { category: 'スケジュール/' + (x.category || '') });
    }), 1);
  }

  // 案件マスタへの転記は今ファースト版では行わない（user が schedule シートへ手動で反映）
  parsed.confirmations = (parsed.confirmations || []).concat([{
    category: 'スケジュール/反映',
    content: 'Claude_マイルストーン提案シートに ' + milestones.length + ' 件のマイルストーンを生成しました。' +
      'スケジュール（4ヵ月）シートには直接書いていません。提案を見ながら手動で配置してください。'
  }]);

  CaseList_touchUpdatedAt(caseId);

  // gid 付きURL でそれぞれの該当タブに直接開ける形にする
  const scheduleSheetUrl = PanelLinks_sheetUrl(zissiSs, scheduleSheet);
  const proposalSheetUrl = PanelLinks_sheetUrl(zissiSs, proposalSheet);

  MasterWriteBack_recordArtifact(caseId, 'スケジュール', '全体スケジュール 初版 (' + milestones.length + ' マイルストーン)', scheduleSheetUrl);

  return {
    zissiSheetUrl: zissiSs.getUrl(),
    scheduleSheetUrl: scheduleSheetUrl,
    proposalSheetUrl: proposalSheetUrl,
    scheduleSheetName: SCHEDULE_TARGET_NAME,
    proposalSheetName: SCHEDULE_PROPOSAL_NAME,
    scheduleCopiedThisRun: copiedThisRun,
    milestoneCount: milestones.length,
    confirmationCount: (parsed.confirmations || []).length,
    fillWrites: fillResult ? fillResult.writes : [],
    fillReason: fillResult ? fillResult.reason : null,
    calendarWrites: calendarWriteLog ? calendarWriteLog.writes : [],
    usage: res.usage
  };
}

// -------- internals --------

function _Schedule_dumpDiagnostic(zissiSs, scheduleSheet, fillResult) {
  // 診断結果を Google Doc に書く (Drive MCP natural-language export が Doc 本文を完全に出力するため)
  const caseFolder = DriveApp.getFolderById(zissiSs.getId()).getParents().next();
  const docName = 'Claude_診断_schedule';
  let doc;
  const it = caseFolder.getFilesByName(docName);
  if (it.hasNext()) {
    const file = it.next();
    doc = DocumentApp.openById(file.getId());
    doc.getBody().clear();
  } else {
    doc = DocumentApp.create(docName);
    DriveApp.getFileById(doc.getId()).moveTo(caseFolder);
  }

  const body = doc.getBody();
  const lines = [];
  lines.push('=== Schedule Diagnostic ===');
  lines.push('timestamp: ' + Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy/MM/dd HH:mm:ss'));
  lines.push('scheduleSheet.name: ' + scheduleSheet.getName());
  lines.push('scheduleSheet.gid: ' + String(scheduleSheet.getSheetId()));

  const lastRow = Math.min(scheduleSheet.getLastRow(), 10);
  const lastCol = Math.min(scheduleSheet.getLastColumn(), 50);
  lines.push('scanned.range: 1,1 to ' + lastRow + ',' + lastCol);

  lines.push('');
  lines.push('=== fillWrites (what was written) ===');
  if (fillResult && fillResult.writes && fillResult.writes.length > 0) {
    fillResult.writes.forEach(function (w) {
      lines.push('write: ' + JSON.stringify(w));
    });
  } else {
    lines.push('write: NONE - no label or yellow bg found');
    if (fillResult && fillResult.reason) lines.push('reason: ' + fillResult.reason);
  }

  lines.push('');
  lines.push('=== Unique non-white backgrounds in rows 1-10 ===');
  if (lastRow > 0 && lastCol > 0) {
    const bgs = scheduleSheet.getRange(1, 1, lastRow, lastCol).getBackgrounds();
    const seen = {};
    for (let r = 0; r < bgs.length; r++) {
      for (let cc = 0; cc < bgs[r].length; cc++) {
        const bg = String(bgs[r][cc] || '').toLowerCase();
        if (bg && bg !== '#ffffff' && bg !== '#fff' && bg !== '') {
          if (!seen[bg]) seen[bg] = [];
          seen[bg].push('r' + (r + 1) + 'c' + (cc + 1));
        }
      }
    }
    Object.keys(seen).forEach(function (bg) {
      lines.push('bg ' + bg + ': ' + seen[bg].slice(0, 12).join(',') + (seen[bg].length > 12 ? '...(' + seen[bg].length + ' total)' : ''));
    });
    if (Object.keys(seen).length === 0) {
      lines.push('bg: NONE — all cells in range are white');
    }
  }

  lines.push('');
  lines.push('=== Row 1-5 cells (non-empty only) ===');
  if (lastRow > 0 && lastCol > 0) {
    const vals = scheduleSheet.getRange(1, 1, Math.min(lastRow, 5), lastCol).getValues();
    const fmls = scheduleSheet.getRange(1, 1, Math.min(lastRow, 5), lastCol).getFormulas();
    for (let r = 0; r < vals.length; r++) {
      for (let cc = 0; cc < vals[r].length; cc++) {
        const v = String(vals[r][cc] || '');
        const f = String(fmls[r][cc] || '');
        if (v !== '' || f !== '') {
          lines.push('r' + (r + 1) + 'c' + (cc + 1) + ' val=[' + v.substring(0, 60) + '] formula=[' + f.substring(0, 60) + ']');
        }
      }
    }
  }

  body.setText(lines.join('\n'));
  doc.saveAndClose();
}

function _Schedule_writeMilestonesToCalendar(scheduleSheet, milestones) {
  // 4ヵ月カレンダーの各セクションに、該当日のマイルストーンを書き込む。
  // セクション構造（diagnostic で確認済み）:
  //   Section 1 (Feb): A=日付, B-C=内容, D=曜日
  //   Section 2 (Mar): W=日付, X-Y=内容, Z=曜日
  //   Section 3 (Apr): AS=日付, AT-AU=内容, AV=曜日
  //   Section 4 (May): BO=日付, BP-BQ=内容, BR=曜日
  const writeLog = [];
  if (!milestones || milestones.length === 0) return { writes: writeLog };

  // セクション構造（2026-06-15 read-back 検証で修正）:
  //   日付セルは 5 列 merge (top-left のみが値を持つ) → dateCol は **必ず merge top-left** にする
  //   内容セル開始位置: date+6 (日付セルの merge 終端の次の列)
  //   Section 1: A(date)=1, G(content)=7
  //   Section 2: S(date)=19, Y(content)=25
  //   Section 3: AK(date)=37, AQ(content)=43
  //   Section 4: BC(date)=55, BI(content)=61
  const sections = [
    { dateCol: 1, contentCol: 7 },
    { dateCol: 19, contentCol: 25 },
    { dateCol: 37, contentCol: 43 },
    { dateCol: 55, contentCol: 61 }
  ];

  // 各セクションの日付列を読み取り、日付 → {row, contentCol} の map を作る
  const dateMap = {};
  for (let i = 0; i < sections.length; i++) {
    const sec = sections[i];
    let colValues;
    try {
      colValues = scheduleSheet.getRange(7, sec.dateCol, 31, 1).getValues();
    } catch (e) { continue; }
    for (let r = 0; r < colValues.length; r++) {
      const v = colValues[r][0];
      if (v instanceof Date && !isNaN(v.getTime())) {
        const key = Utilities.formatDate(v, 'Asia/Tokyo', 'yyyy/MM/dd');
        if (!dateMap[key]) {
          dateMap[key] = { row: 7 + r, contentCol: sec.contentCol };
        }
      }
    }
  }

  // 既存セルをクリア（再生成時の重複防止）
  // 新 content col (7/25/43/61) + 旧 content col (29/51/73, 28/50/72) の両方をクリア
  const allClearCols = [7, 25, 43, 61, 28, 29, 50, 51, 72, 73];
  allClearCols.forEach(function (col) {
    try {
      scheduleSheet.getRange(7, col, 31, 1).clearContent();
    } catch (e) { /* skip */ }
  });

  // 同じ日付に複数マイルストーンが来たら改行で結合
  const cellBuffer = {}; // key: row+col → text

  milestones.forEach(function (m) {
    if (!m.dueDate) return;
    const raw = String(m.dueDate).replace(/-/g, '/').trim();
    const parts = raw.split('/');
    let normalized;
    if (parts.length === 3) {
      normalized = parts[0] + '/' + ('0' + parts[1]).slice(-2) + '/' + ('0' + parts[2]).slice(-2);
    } else {
      normalized = raw;
    }
    const target = dateMap[normalized];
    if (!target) {
      writeLog.push({ date: m.dueDate, task: m.task, action: 'skipped (date out of calendar range)' });
      return;
    }
    const bufKey = target.row + ',' + target.contentCol;
    cellBuffer[bufKey] = cellBuffer[bufKey] ? cellBuffer[bufKey] + '\n' + m.task : m.task;
    writeLog.push({ date: normalized, row: target.row, col: target.contentCol, task: m.task });
  });

  // バッファをセルに書き込み
  // setValue / setWrap を分離（チェーン中の例外で setValue が巻き戻る可能性回避）
  Object.keys(cellBuffer).forEach(function (k) {
    const parts = k.split(',');
    const row = parseInt(parts[0], 10);
    const col = parseInt(parts[1], 10);
    const range = scheduleSheet.getRange(row, col);
    try {
      range.setValue(cellBuffer[k]);
    } catch (e) {
      writeLog.push({ action: 'setValue ERROR', row: row, col: col, error: e.toString() });
      return;
    }
    try {
      range.setWrap(false);
    } catch (e) {
      writeLog.push({ action: 'setWrap ERROR (value still set)', row: row, col: col, error: e.toString() });
    }
  });

  return { writes: writeLog };
}

function _Schedule_forceRecalcFormulas(sheet) {
  // 数式エラーがキャッシュされている時、参照先が後から正しくなっても再評価されない。
  // 対策: 数式があるセルだけ個別に setFormula で書き戻す → 再評価される。
  // ★setFormulas 一括は NG: 非数式セル（"開催日"等のテキストラベル）に空文字が書かれて消える。
  const lastRow = sheet.getLastRow();
  const lastCol = sheet.getLastColumn();
  if (lastRow === 0 || lastCol === 0) return;
  const range = sheet.getRange(1, 1, lastRow, lastCol);
  const formulas = range.getFormulas();
  for (let r = 0; r < formulas.length; r++) {
    for (let c = 0; c < formulas[r].length; c++) {
      const f = formulas[r][c];
      if (f) {
        try {
          sheet.getRange(r + 1, c + 1).setFormula(f);
        } catch (e) { /* skip */ }
      }
    }
  }
  SpreadsheetApp.flush();
}

function _Schedule_provisionSummarySheet(zissiSs, caseInfo) {
  // スケジュール (4ヵ月) の数式は同じ workbook 内の `summary` シートを参照する。
  // コピー元にあれば copyTo してから対象セルを上書き。無ければ insertSheet して必要セルだけ埋める。
  const writeLog = [];
  let dt = null;
  if (caseInfo.startDate) {
    if (caseInfo.startDate instanceof Date) {
      dt = caseInfo.startDate;
    } else {
      const str = String(caseInfo.startDate).trim();
      if (str) {
        const parsed = new Date(str.replace(/-/g, '/'));
        if (!isNaN(parsed.getTime())) dt = parsed;
      }
    }
  }

  let summarySheet = zissiSs.getSheetByName('summary');
  if (!summarySheet) {
    try {
      const sourceSs = SpreadsheetApp.openById(SCHEDULE_SOURCE_SS_ID);
      const sourceSummary = sourceSs.getSheetByName('summary');
      if (sourceSummary) {
        summarySheet = sourceSummary.copyTo(zissiSs);
        summarySheet.setName('summary');
        writeLog.push({ action: 'copied summary from source' });
      } else {
        summarySheet = zissiSs.insertSheet('summary');
        writeLog.push({ action: 'created empty summary (source has no summary sheet)' });
      }
    } catch (e) {
      writeLog.push({ action: 'failed to provision summary', error: e.toString() });
      return { writes: writeLog };
    }
  } else {
    writeLog.push({ action: 'summary sheet already exists, reusing' });
  }

  // summary シート: D/I/AV 列に同じ値を書く（テンプレ版 + コピー版 + 右側ヘッダーの三系統が参照）
  //                  D5/I5/AV5 = 社名, D13/I13/AV13 = 案件名, D19/I19/AV19 = 開催日
  try {
    ['D5', 'I5', 'AV5'].forEach(function (a) { summarySheet.getRange(a).setValue(caseInfo.clientName || ''); });
    writeLog.push({ sheet: 'summary', cell: 'D5/I5/AV5', value: caseInfo.clientName || '' });
    ['D13', 'I13', 'AV13'].forEach(function (a) { summarySheet.getRange(a).setValue(caseInfo.caseName || ''); });
    writeLog.push({ sheet: 'summary', cell: 'D13/I13/AV13', value: caseInfo.caseName || '' });
    if (dt) {
      ['D19', 'I19', 'AV19'].forEach(function (a) { summarySheet.getRange(a).setValue(dt); });
      writeLog.push({ sheet: 'summary', cell: 'D19/I19/AV19', value: Utilities.formatDate(dt, 'Asia/Tokyo', 'yyyy/MM/dd') });
    } else {
      writeLog.push({ sheet: 'summary', cell: 'D19/I19/AV19', value: '(skipped: no valid startDate)' });
    }
  } catch (e) {
    writeLog.push({ action: 'failed to write summary cells', error: e.toString() });
  }

  // 企画 シート: B30 = 出展日（スケジュールの A7 が =EOMONTH('企画'!B30, -4)+1 で参照する）
  try {
    const kikakuSheet = zissiSs.getSheetByName('企画');
    if (kikakuSheet && dt) {
      kikakuSheet.getRange('B30').setValue(dt);
      writeLog.push({ sheet: '企画', cell: 'B30', value: Utilities.formatDate(dt, 'Asia/Tokyo', 'yyyy/MM/dd') });
    } else if (!kikakuSheet) {
      writeLog.push({ sheet: '企画', cell: 'B30', value: '(skipped: 企画 sheet not found)' });
    }
  } catch (e) {
    writeLog.push({ action: 'failed to write 企画 B30', error: e.toString() });
  }

  return { writes: writeLog };
}

function _Schedule_findExistingZissi(caseInfo) {
  // 最優先: 案件一覧 K列 に保存された実施計画書ID（Phase1_Estimate が書き込む）
  if (caseInfo.zissiId) {
    try {
      return SpreadsheetApp.openById(caseInfo.zissiId);
    } catch (e) { /* ID が無効なら次の方法へ */ }
  }

  // フォールバック: 候補フォルダ（legacy プロジェクトフォルダ + My Drive 案件フォルダ）から名前検索
  const candidates = [];
  if (caseInfo.projectFolderId) candidates.push(caseInfo.projectFolderId);
  if (caseInfo.folderId) candidates.push(caseInfo.folderId);

  for (let i = 0; i < candidates.length; i++) {
    try {
      const folder = DriveApp.getFolderById(candidates[i]);
      const files = folder.getFilesByType(MimeType.GOOGLE_SHEETS);
      while (files.hasNext()) {
        const f = files.next();
        if (f.getName().indexOf('実施計画書') >= 0 && f.getName().indexOf('提出') < 0) {
          return SpreadsheetApp.openById(f.getId());
        }
      }
    } catch (e) { /* 次の候補へ */ }
  }

  // 最終フォールバック: Drive 全体から「<案件名> + 実施計画書」で検索
  try {
    const safeName = String(caseInfo.caseName || '').replace(/"/g, '');
    if (safeName) {
      const query = "title contains '" + safeName + "' and title contains '実施計画書' " +
        "and mimeType = 'application/vnd.google-apps.spreadsheet' and trashed = false";
      const it = DriveApp.searchFiles(query);
      while (it.hasNext()) {
        const f = it.next();
        if (f.getName().indexOf('提出') < 0) {
          return SpreadsheetApp.openById(f.getId());
        }
      }
    }
  } catch (e) { /* 検索失敗は null へ */ }

  return null;
}

/**
 * Phase2: アサインセット打診文 初版 を生成。
 *
 * 対象パーティ:
 *  - 'construction' : 施工会社（ブース造作・設営撤去の外注先）
 *  - 'ops'          : 運営スタッフ（当日進行サポートスタッフ）
 *  - 'driver'       : ドライバー（搬入出車両手配）
 *
 * 流れ:
 *  1) 案件情報を取得
 *  2) パーティ別の関連マニュアル抜粋を取得
 *  3) Claude で打診文 + 確認事項 JSON を生成
 *  4) Gmail Draft（受信者空欄）+ Doc を案件 Drive フォルダに保存
 *  5) 確認事項を確認シートに積む
 */

const _PARTY_CONFIG = {
  construction: {
    displayName: '施工会社',
    docSuffix: '施工会社打診文',
    subjectFallback: '施工ご協力のお願い（' + '初版' + '）',
    manualQueries: ['施工会社', '設営撤去', '搬入出計画', '展示会ブース 施工'],
    contextHint: '施工会社（造作・設営・撤去の外注先）への打診メール。設営日・搬出日・ブースサイズ・必要工程を伝えて見積依頼まで。'
  },
  ops: {
    displayName: '運営スタッフ',
    docSuffix: '運営スタッフ打診文',
    subjectFallback: '当日運営スタッフのご協力依頼（初版）',
    manualQueries: ['運営スタッフ', '当日進行', 'スタッフ手配', 'シフト'],
    contextHint: '展示会本番当日の運営スタッフ（受付・案内・対応サポート）への打診メール。当日時間帯・場所・必要人数・想定業務内容を伝えて稼働可否確認まで。'
  },
  driver: {
    displayName: 'ドライバー',
    docSuffix: 'ドライバー打診文',
    subjectFallback: '搬入出車両手配のご相談（初版）',
    manualQueries: ['ドライバー', '搬入出', '車両手配', '配送', 'トラック'],
    contextHint: 'ブース備品・造作物の搬入出ドライバーへの打診メール。搬入日時・搬出日時・会場住所・想定積載量・車両サイズを伝えて手配可否確認まで。'
  }
};

function Phase2_AssignBrief_generate(caseId, partyType) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);
  const cfg = _PARTY_CONFIG[partyType];
  if (!cfg) {
    throw new Error('不明な partyType: ' + partyType + ' (有効値: construction / ops / driver)');
  }

  // 関連ページが多すぎるとプロンプトコストが膨れるので上位 15 件に絞る
  const manualPages = ManualLoader_findPages(cfg.manualQueries).slice(0, 15);

  const cachedContext = [
    Case_loadClientContext(c),
    '【関連マニュアル抜粋】',
    ...manualPages.map(function (p) { return '# ' + p.title + '\nパス: ' + p.path + '\n\n' + p.body; })
  ].filter(Boolean);

  const userPrompt = [
    '以下の案件について、' + cfg.displayName + 'への初版打診メール本文を作成してください。',
    '',
    '## メールの目的',
    cfg.contextHint,
    '',
    '## 案件情報',
    '- クライアント名: ' + c.clientName,
    '- 案件名: ' + c.caseName,
    '- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate),
    '- ブースサイズ: ' + (c.boothSize || '未確定'),
    '',
    '## 出力形式（厳守）',
    '次の JSON だけを返してください。前後の説明文や ```json``` ブロックは不要。',
    '{',
    '  "subject": "<メール件名>",',
    '  "body": "<メール本文・改行は \\n>",',
    '  "confirmations": [',
    '    {"category": "<確認カテゴリ>", "content": "<確認したい内容>"}',
    '  ]',
    '}',
    '',
    '注意:',
    '- 受信者の固有名（会社名・担当者名）は案件情報に無いので本文に書かず confirmations へ。',
    '- 価格・人数・台数等の数値は案件情報に確定値が無いなら本文では「ご相談」「未確定」と書き、確定すべき項目は confirmations へ。',
    '- 関連マニュアルが示す依頼文書式・必要記載事項は本文に反映すること。'
  ].join('\n');

  const manualPdfs = CaseManualPdf_find(c);
  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    documents: manualPdfs,
    maxTokens: 3000
  });

  const parsed = _Phase1_parseJson(res.text);

  // Gmail Draft 作成（受信者は空 — 実際の発注先 user 側で埋める）
  const draft = GmailApp.createDraft(
    '',
    Mail_externalSubject(c.caseId, c.caseName, parsed.subject || cfg.subjectFallback, cfg.displayName),
    parsed.body || ''
  );

  // Drive フォルダにも Doc 保存
  const folderId = Case_resolveProjectRoot(c);
  const docName = c.caseId + '_' + c.caseName + '_' + cfg.docSuffix + '_初版';
  const doc = DocumentApp.create(docName);
  doc.getBody().setText('件名: ' + (parsed.subject || '') + '\n\n' + (parsed.body || ''));
  doc.saveAndClose();
  if (folderId) {
    try { DriveApp.getFileById(doc.getId()).moveTo(DriveApp.getFolderById(folderId)); } catch (e) {}
  }

  // 確認事項を積む（Phase=2 で積む）
  if (parsed.confirmations && parsed.confirmations.length > 0) {
    const tagged = parsed.confirmations.map(function (x) {
      return { category: '[' + cfg.displayName + '] ' + (x.category || ''), content: x.content || '' };
    });
    ConfirmationSheet_appendItems(caseId, tagged, 2);
  }
  CaseList_touchUpdatedAt(caseId);

  const docUrl = DocumentApp.openById(doc.getId()).getUrl();
  MasterWriteBack_recordArtifact(caseId, cfg.displayName + '打診文', parsed.subject || '', docUrl);

  return {
    partyType: partyType,
    partyName: cfg.displayName,
    subject: parsed.subject,
    draftId: draft.getId(),
    docUrl: docUrl,
    confirmationCount: (parsed.confirmations || []).length,
    manualPagesUsed: manualPages.length,
    usage: res.usage
  };
}

/** Fable5 model id 疎通確認用 */
function Phase2_Fable5_ping() {
  const res = ClaudeClient_call({
    model: CLAUDE_MODEL_HQ,
    userMessage: 'JSON 一行で {"ok":true} とだけ返してください。',
    maxTokens: 50
  });
  return { text: res.text || '(empty)', usage: res.usage };
}

