/**
 * 文字列の表示幅（全角=2、半角=1）を計算し、目標の幅に達するまで右パディング（スペース）を付与する。
 */
function _padRight(str, targetWidth) {
  var w = 0;
  for (var i = 0; i < str.length; i++) {
    w += (str.charCodeAt(i) <= 0x7f) ? 1 : 2;
  }
  var pad = '';
  var needed = Math.max(2, targetWidth - w);
  for (var j = 0; j < needed; j++) {
    pad += ' ';
  }
  return str + pad;
}

