  ];

/** LogisticsFormula.js と同じ優先順位。最大クラス超過時は同クラス複数台。 */
function Phase2_selectTrucks(withMarginM3) {
  if (typeof withMarginM3 !== 'number' || !isFinite(withMarginM3) || withMarginM3 < 0) throw new Error('容積は有限の非負数で指定してください');
  var selected = [{ name: 'デュトロ', kind: '自社便', capacity: PHASE2_DUTRO_CAPACITY }];
  var mode = 'dutro_only', rental = 0;
  if (withMarginM3 > PHASE2_DUTRO_CAPACITY) {
    if (withMarginM3 <= PHASE2_DUTRO_CAPACITY + PHASE2_CARAVAN_CAPACITY) {
      selected.push({ name: '日産キャラバン', kind: '自社便', capacity: PHASE2_CARAVAN_CAPACITY });
      mode = 'jisha_both';
    } else {
      mode = 'dutro_plus_rental';
      rental = Math.round((withMarginM3 - PHASE2_DUTRO_CAPACITY) * 1000000) / 1000000;
      var chosen = PHASE2_EXTRA_TRUCKS[0];
      PHASE2_EXTRA_TRUCKS.forEach(function (t) { if (t.capacity >= rental) chosen = t; });
      var count = Math.min(29, Math.ceil(rental / chosen.capacity));
      for (var i = 0; i < count; i++) selected.push({ name: chosen.name, kind: chosen.kind, capacity: chosen.capacity });
    }
  }
  return { selectedTrucks: selected, isCoveredByJisha: rental === 0, rentalNeededM3: rental, mode: mode };
}

const BIHIN_MASTER_SS_ID = '1QCW86DIri6nryqheFKw8Cr6e9Ce0YRV6FvFFW0zqBnc';
const BIHIN_MASTER_GID = 935442052;
const BIHIN_DATA_START_ROW = 4; // ヘッダーは row 3、 データは row 4 から
const BIHIN_COL_NAME = 4;       // D
const BIHIN_COL_CATEGORY = 7;   // G
const BIHIN_COL_SIZE_VERT = 18; // R
const BIHIN_COL_SIZE_HORZ = 19; // S
const BIHIN_COL_SIZE_HEIGHT = 20; // T
const BIHIN_COL_VOLUME = 42;    // AP

const LOGISTICS_SS_ID = '1_zbmz8LReBsLRynQ7oIxdyXEwzw7mMnnbULsQcAFfio';
const LOGISTICS_GID = 375728639;

/**
 * 備品在庫管理表 AP 列 (容積) を全行自動算出して書き込み。
 * - R/S/T (mm) が揃っている → R×S×T / 1e9 = m³
 * - 不揃いなら D 列 (品名) を 正規表現で W×D×H 抽出
 * - 抽出失敗時は カテゴリ別の推定値 (フォールバック)
 * 既存値 (空でない) は上書きしない (手入力を尊重)。
 *
 * @return {object} { totalRows, filledCount, skippedExisting, fallbackEstimateCount, sample }
 */
function Phase2_BihinVolume_fillAP(forceOverwrite) {
  const ss = SpreadsheetApp.openById(BIHIN_MASTER_SS_ID);
  let sheet = null;
  ss.getSheets().forEach(function (s) { if (s.getSheetId() === BIHIN_MASTER_GID) sheet = s; });
  if (!sheet) throw new Error('備品在庫管理表 sheet (gid=' + BIHIN_MASTER_GID + ') not found');

  const lastRow = sheet.getLastRow();
  const rowCount = lastRow - BIHIN_DATA_START_ROW + 1;
  if (rowCount <= 0) return { error: 'no data rows' };

  // 必要 6 列を一括取得 (D, G, R, S, T, AP)
  // D=4, G=7, R=18, S=19, T=20, AP=42
  // batch 範囲: D 〜 AP (39 列) で読み込み → 必要 index だけ参照
  const blockWidth = BIHIN_COL_VOLUME - BIHIN_COL_NAME + 1; // D..AP
  const block = sheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_NAME, rowCount, blockWidth).getValues();
  // 元 AP 列の値 (上書き判定用)
  const existingVolumes = block.map(function (r) { return r[blockWidth - 1]; });

  let filled = 0, skipped = 0, fallback = 0;
  const sample = [];
  const newAp = block.map(function (row, i) {
    const existing = existingVolumes[i];
    // 既存値 (数値 > 0 or "計算不要" 等の文字列) は上書きしない
    // forceOverwrite=true なら既存も再計算 (estimate ロジック更新時に使用)
    if (!forceOverwrite && existing !== '' && existing !== null && existing !== 0) {
      skipped++;
      return [existing];
    }
    const name = String(row[BIHIN_COL_NAME - BIHIN_COL_NAME] || '');
    const category = String(row[BIHIN_COL_CATEGORY - BIHIN_COL_NAME] || '');
    const v = Number(row[BIHIN_COL_SIZE_VERT - BIHIN_COL_NAME] || 0);
    const h = Number(row[BIHIN_COL_SIZE_HORZ - BIHIN_COL_NAME] || 0);
    const z = Number(row[BIHIN_COL_SIZE_HEIGHT - BIHIN_COL_NAME] || 0);

    let volume = 0;
    let source = '';
    if (!name && !v && !h && !z) {
      // 空行 → スキップ
      skipped++;
      return [existing || ''];
    }

    if (v > 0 && h > 0 && z > 0) {
      // mm * mm * mm / 10^9 = m^3
      volume = (v * h * z) / 1e9;
      source = 'RST';
    } else {
      // 品名から W×D×H パターン抽出
      const dims = _parseDimensionsFromName(name);
      if (dims) {
        volume = (dims.w * dims.d * dims.h) / 1e9;
        source = 'name';
      } else {
        // 推定値 (分類別)
        volume = _estimateVolumeByCategory(category, name);
        source = 'estimate';
        fallback++;
      }
    }
    // 1 m³ 超は外れ値疑い (構造物以外で発生したら確認用に半減)
    if (volume > 5 && source !== 'RST' && !/トラス|LED|パネル|フロアタイル|什器|テーブル|カウンター/.test(name)) {
      volume = volume / 2;
      source += '-capped';
    }
    // 4 桁有効数字に丸める
    volume = Math.round(volume * 10000) / 10000;
    filled++;
    if (sample.length < 8) {
      sample.push({ row: BIHIN_DATA_START_ROW + i, name: name.slice(0, 30), v: v, h: h, z: z, volume: volume, source: source });
    }
    return [volume];
  });

  // AP 列に一括書き込み
  sheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_VOLUME, rowCount, 1).setValues(newAp);
  SpreadsheetApp.flush();

  // read-back verify (先頭 10 行)
  const readBack = sheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_VOLUME, Math.min(10, rowCount), 1).getValues();
  return {
    totalRows: rowCount,
    filledCount: filled,
    skippedExisting: skipped,
    fallbackEstimateCount: fallback,
    sample: sample,
    readBackTop10: readBack.map(function (r) { return r[0]; })
  };
}

/**
 * AP 列が estimate fallback (一律 0.005) になっている品目を Claude API で個別容積推定し、
 * AP 列を上書きする。 R/S/T 実寸入力済みの 190 件は触らない。
 *
 * 進捗保存: Script Properties.BIHIN_AP_REFINE_OFFSET にバッチ index を保存し、
 *           次回呼び出しでレジューム可能。 全完了で 0 にリセット。
 *
 * @param {number} maxBatches このコマンド内で処理するバッチ上限 (default 30, Apps Script 6 分制限考慮)
 * @return {object} {totalTargets, batchCount, offsetBefore, offsetAfter, updates, isDone}
 */
function Phase2_BihinVolume_refineWithClaude(maxBatches) {
  const BATCH_SIZE = 50;
  const MAX_BATCHES_PER_RUN = maxBatches || 30;

  const ss = SpreadsheetApp.openById(BIHIN_MASTER_SS_ID);
  let sheet = null;
  ss.getSheets().forEach(function (s) { if (s.getSheetId() === BIHIN_MASTER_GID) sheet = s; });
  if (!sheet) throw new Error('master sheet not found');

  const lastRow = sheet.getLastRow();
  const rowCount = lastRow - BIHIN_DATA_START_ROW + 1;
  const blockWidth = BIHIN_COL_VOLUME - BIHIN_COL_NAME + 1;
  const block = sheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_NAME, rowCount, blockWidth).getValues();

  // estimate fallback ターゲット抽出: AP == 0.005 かつ R/S/T 全空
  const targets = [];
  for (let i = 0; i < block.length; i++) {
    const name = String(block[i][0] || '').trim();
    const v = Number(block[i][BIHIN_COL_SIZE_VERT - BIHIN_COL_NAME] || 0);
    const h = Number(block[i][BIHIN_COL_SIZE_HORZ - BIHIN_COL_NAME] || 0);
    const z = Number(block[i][BIHIN_COL_SIZE_HEIGHT - BIHIN_COL_NAME] || 0);
    const ap = Number(block[i][BIHIN_COL_VOLUME - BIHIN_COL_NAME] || 0);
    if (name && v === 0 && h === 0 && z === 0 && Math.abs(ap - 0.005) < 0.0001) {
      targets.push({ row: BIHIN_DATA_START_ROW + i, name: name });
    }
  }

  const batchCount = Math.ceil(targets.length / BATCH_SIZE);
  const props = PropertiesService.getScriptProperties();
  let offset = Number(props.getProperty('BIHIN_AP_REFINE_OFFSET') || 0);
  const startBatch = offset;
  const endBatch = Math.min(startBatch + MAX_BATCHES_PER_RUN, batchCount);

  // 一括取得した AP 列値 (書き戻し用)
  const fullAp = sheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_VOLUME, rowCount, 1).getValues();
  let updatesCount = 0;
  const failed = [];

  for (let b = startBatch; b < endBatch; b++) {
    const batch = targets.slice(b * BATCH_SIZE, (b + 1) * BATCH_SIZE);
    if (batch.length === 0) break;
    const prompt =
      '以下は展示会ブース制作の備品リストです。 各品目の 1個あたりの梱包輸送時容積を m³ で推定し、 JSON 配列で返してください。\n' +
      '基準値の目安:\n' +
      '  - ネジ・釘・ボルト・ナット・ワッシャー (1本/1個): 0.00005-0.0005\n' +
      '  - テープ・養生材・小物文具・薬品・電池 (1巻/1本): 0.0005-0.005\n' +
      '  - 名刺・チラシ・印刷物 (1枚): 0.00001-0.0001\n' +
      '  - 工具・電子小物・USB等 (1個): 0.001-0.02\n' +
      '  - ファイル・段ボール箱 1個: 0.01-0.05\n' +
      '  - 中型機器 (モニター・スタンド・椅子・スピーカー): 0.05-0.3\n' +
      '  - 大型構造物 (トラス本体・LEDUPパネル・什器・カウンター・展示台・ハイテーブル): 0.3-2.0\n' +
      '注意: 品名に「ボルト式シルバートラス用」「LEDUP固定用」等の親構造物名が混入していても、 単体の容積を推定すること。 例: 「ボルト式シルバートラス用 M10 ナット」は ナット1個 (0.0001 m³) であって トラスではない。\n\n' +
      '応答形式: JSON 配列のみ (前後の説明文・コードブロック禁止)\n' +
      '形式: [{"i":0,"v":0.001},{"i":1,"v":0.05}, ...]  i は下記リストの番号、 v は m³\n\n' +
      batch.map(function (t, idx) { return idx + ': ' + t.name.slice(0, 80); }).join('\n');

    try {
      const res = ClaudeClient_call({ userMessage: prompt, maxTokens: 4000 });
      let text = (res.text || '').trim();
      const m = text.match(/\[[\s\S]*\]/);
      if (m) text = m[0];
      const result = JSON.parse(text);
      result.forEach(function (r) {
        const idx = r.i;
        const vol = Number(r.v);
        if (typeof idx !== 'number' || isNaN(vol) || vol <= 0 || vol > 5) return;
        if (idx < 0 || idx >= batch.length) return;
        const masterOffset = batch[idx].row - BIHIN_DATA_START_ROW;
        fullAp[masterOffset][0] = Math.round(vol * 10000) / 10000;
        updatesCount++;
      });
    } catch (e) {
      failed.push({ batch: b, error: e.toString().slice(0, 100) });
    }
  }

  // AP 列を一括書き戻し
  sheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_VOLUME, rowCount, 1).setValues(fullAp);
  SpreadsheetApp.flush();

  // 進捗保存
  const isDone = endBatch >= batchCount;
  props.setProperty('BIHIN_AP_REFINE_OFFSET', isDone ? '0' : String(endBatch));

  // read-back verify (10 サンプル)
  const sampleRows = [];
  for (let s = 0; s < Math.min(10, updatesCount); s++) {
    const t = targets[Math.min(startBatch * BATCH_SIZE + s, targets.length - 1)];
    const apVal = sheet.getRange(t.row, BIHIN_COL_VOLUME).getValue();
    sampleRows.push({ row: t.row, name: t.name.slice(0, 40), apAfter: apVal });
  }

  return {
    totalTargets: targets.length,
    batchCount: batchCount,
    offsetBefore: startBatch,
    offsetAfter: endBatch,
    updates: updatesCount,
    failedBatches: failed.length,
    failedDetail: failed.slice(0, 3),
    isDone: isDone,
    nextRunWillResume: !isDone,
    sampleReadBack: sampleRows
  };
}

/**
 * 布製品 (布・カーテン・テーブルクロス・タペストリー・のれん・ファブリック等) の AP を
 * 「厚み 1mm 前提 (折り畳み収納)」 で再推定して上書き。
 *
 * 背景: _parseDimensionsFromName で 2 軸 W×H 抽出時に d=100mm デフォルトを使っており、
 *       布関連は実態 1mm 厚 ≒ 折り畳み収納なので過大評価されている (10cm → 1mm の 100倍)。
 *
 * @return {object} {targetCount, batchCount, updates, sampleReadBack}
 */
function Phase2_BihinVolume_refineCloth() {
  const BATCH_SIZE = 50;
  const ss = SpreadsheetApp.openById(BIHIN_MASTER_SS_ID);
  let sheet = null;
  ss.getSheets().forEach(function (s) { if (s.getSheetId() === BIHIN_MASTER_GID) sheet = s; });
  if (!sheet) throw new Error('master sheet not found');

  const lastRow = sheet.getLastRow();
  const rowCount = lastRow - BIHIN_DATA_START_ROW + 1;
  const blockWidth = BIHIN_COL_VOLUME - BIHIN_COL_NAME + 1;
  const block = sheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_NAME, rowCount, blockWidth).getValues();

  // 布関連キーワードでターゲット抽出
  const CLOTH_PATTERN = /布|カーテン|のれん|タペストリー|テーブルクロス|テーブルカバー|ナプキン|旗|バナー|ファブリック|fabric|cloth|クロス|ドレープ|スカート|シーツ|ベール|フェルト|タオル|手拭|風呂敷|シーティング|養生シート(?!.*段ボール)|モール|フリル/i;
  const targets = [];
  for (let i = 0; i < block.length; i++) {
    const name = String(block[i][0] || '').trim();
    if (!name) continue;
    const ap = Number(block[i][BIHIN_COL_VOLUME - BIHIN_COL_NAME] || 0);
    if (CLOTH_PATTERN.test(name) && ap > 0) {
      targets.push({ row: BIHIN_DATA_START_ROW + i, name: name, apBefore: ap });
    }
  }

  if (targets.length === 0) {
    return { targetCount: 0, batchCount: 0, updates: 0, sampleReadBack: [], note: '布関連品目が見つかりませんでした' };
  }

  const batchCount = Math.ceil(targets.length / BATCH_SIZE);
  const fullAp = sheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_VOLUME, rowCount, 1).getValues();
  let updatesCount = 0;
  const failed = [];

  for (let b = 0; b < batchCount; b++) {
    const batch = targets.slice(b * BATCH_SIZE, (b + 1) * BATCH_SIZE);
    const prompt =
      '以下は展示会・イベント制作の備品リスト中の「布製品 (布・カーテン・テーブルクロス等)」です。\n' +
      '輸送・保管時は折り畳んで収納するため、 1枚あたり梱包後の容積を以下の前提で推定してください:\n' +
      '  - 厚み (折り畳み後): 1mm を基本、 厚手の生地でも数 mm 程度\n' +
      '  - 縦・横: 折り畳み後 30〜50cm 角を基本\n' +
      '  - 例: テーブルクロス 1枚 → 約 0.001-0.003 m³ (300×300×30mm 程度)\n' +
      '  - 例: バナー (大型) 1枚 → 約 0.005-0.01 m³\n' +
      '  - 例: カーテン (大型遮光) 1枚 → 約 0.003-0.008 m³\n' +
      '  - 例: 養生シート (布製) 1枚 → 約 0.002-0.005 m³\n' +
      '  - モール・フリル等の装飾 → 1巻 0.001-0.005 m³\n\n' +
      '応答形式: JSON 配列のみ (前後の説明文・コードブロック禁止)\n' +
      '形式: [{"i":0,"v":0.001},{"i":1,"v":0.005}, ...]  i は下記リストの番号、 v は m³\n\n' +
      batch.map(function (t, idx) { return idx + ': ' + t.name.slice(0, 80); }).join('\n');

    try {
      const res = ClaudeClient_call({ userMessage: prompt, maxTokens: 4000 });
      let text = (res.text || '').trim();
      const m = text.match(/\[[\s\S]*\]/);
      if (m) text = m[0];
      const result = JSON.parse(text);
      result.forEach(function (r) {
        const idx = r.i;
        const vol = Number(r.v);
        if (typeof idx !== 'number' || isNaN(vol) || vol <= 0 || vol > 1) return;
        if (idx < 0 || idx >= batch.length) return;
        const masterOffset = batch[idx].row - BIHIN_DATA_START_ROW;
        fullAp[masterOffset][0] = Math.round(vol * 10000) / 10000;
        batch[idx].apAfter = fullAp[masterOffset][0];
        updatesCount++;
      });
    } catch (e) {
      failed.push({ batch: b, error: e.toString().slice(0, 100) });
    }
  }

  sheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_VOLUME, rowCount, 1).setValues(fullAp);
  SpreadsheetApp.flush();

  // read-back sample
  const sampleReadBack = targets.slice(0, 15).map(function (t) {
    return {
      row: t.row,
      name: t.name.slice(0, 50),
      before: t.apBefore,
      after: t.apAfter || sheet.getRange(t.row, BIHIN_COL_VOLUME).getValue()
    };
  });

  return {
    targetCount: targets.length,
    batchCount: batchCount,
    updates: updatesCount,
    failedBatches: failed.length,
    failedDetail: failed.slice(0, 3),
    sampleReadBack: sampleReadBack
  };
}

/**
 * 品名から W×D×H パターン抽出。
 * "W3000×H2980" / "3000×1500×500" / "φ900×H1200" / "直径900 H1200" などに対応。
 * 返り値: {w, d, h} (単位 mm) または null
 */
function _parseDimensionsFromName(name) {
  if (!name) return null;
  const s = String(name).replace(/[Ｗｗ]/g, 'W').replace(/[ＨｈＤｄ]/g, function (c) {
    return c === 'Ｄ' || c === 'ｄ' ? 'D' : 'H';
  });
  // パターン 1: 3 軸 数字×数字×数字 (mm 想定)
  let m = s.match(/(\d{2,5})\s*[×x✕＊\*]\s*(\d{2,5})\s*[×x✕＊\*]\s*(\d{2,5})/);
  if (m) return { w: Number(m[1]), d: Number(m[2]), h: Number(m[3]) };
  // パターン 2: W{n}×H{n} (奥行不明 → 100mm 仮定)
  m = s.match(/W\s*(\d{2,5}).*?H\s*(\d{2,5})/);
  if (m) return { w: Number(m[1]), d: 100, h: Number(m[2]) };
  // パターン 3: φ{n}×H{n} or 直径{n} (円柱)
  m = s.match(/[φΦ]\s*(\d{2,5}).*?H\s*(\d{2,5})/);
  if (m) {
    const r = Number(m[1]) / 2;
    return { w: Math.round(Math.PI * r * r / 1000), d: 1000, h: Number(m[2]) };
  }
  m = s.match(/直径\s*(\d{2,5}).*?H\s*(\d{2,5})/);
  if (m) {
    const r = Number(m[1]) / 2;
    return { w: Math.round(Math.PI * r * r / 1000), d: 1000, h: Number(m[2]) };
  }
  // パターン 4: 2 軸 W×H (奥行不明 → 100mm 仮定)
  m = s.match(/(\d{2,5})\s*[×x]\s*(\d{2,5})/);
  if (m && Number(m[1]) > 30 && Number(m[2]) > 30) {
    return { w: Number(m[1]), d: 100, h: Number(m[2]) };
  }
  return null;
}

/**
 * カテゴリ・名前から容積 (m³) を推定。 サイズ不明品目用フォールバック。
 *
 * 重要: マスタ品名にはしばしば 「ボルト式シルバートラス用 ボルト」 のように
 * 親構造物名が混入する → regex で 「トラス」 マッチ → ボルト1個が 0.3 m³ などの
 * 致命的誤判定を起こす。 そこで estimate は 一律 0.005 m³ で押し下げる方針。
 *
 * 大型構造物 (トラス・LEDUP・什器等) の正確な容積は R/S/T 列の手入力に依存する。
 * estimate fallback はあくまで「不明品」扱いの小さな保守値。
 */
function _estimateVolumeByCategory(category, name) {
  // 一律 0.005 m³ (5L) で押し下げ。 大型構造物は R/S/T 入力で個別精緻化前提。
  return 0.005;
}

/**
 * 案件のアイテムリスト全体容積を計算 + 自社便優先トラック選定。
 *
 * 流れ:
 *   1) zissi の Claude_アイテムリスト提案 シートを読む (品名 + 数量)
 *   2) 備品在庫管理表 D 列で品名マッチ → AP 列容積取得
 *   3) マッチしない品目は spec から容積推定 (上記 helper を再利用)
 *   4) 総容積 × 安全係数 1.3 (積載効率)
 *   5) 自社便 (キャラバン 7.59 + デュトロ 9.51 = 17.10 m³) 優先
 *      不足分を 4t > 2t > 軽 の順で 最小台数選定
 *
 * @param {string} caseId
 * @return {object} { items, totalVolume, withMargin, selectedTrucks, isCoveredByJisha, ... }
 */
/** zissi「アイテムリスト」シートの AF1（容積合計セル）を数値で読む。無効なら null。 */
function _Phase2_readItemListAF1(zissi) {
  try {
    var s = Zissi_findItemListSheet(zissi);
    if (!s) return null;
    var v = s.getRange('AF1').getValue();
    var n = Number(String(v).replace(/[,\s㎥㎥m³]/g, ''));
    return (isFinite(n) && n > 0) ? n : null;
  } catch (e) { return null; }
}

/** 実施計画から Claude 生成物ではない「アイテムリスト」シートを探す。 */
function Zissi_findItemListSheet(zissiSs) {
  var sheet = zissiSs.getSheetByName('アイテムリスト');
  if (!sheet) {
    sheet = zissiSs.getSheets().filter(function (s) {
      var n = s.getName();
      return n.indexOf('アイテムリスト') >= 0 && n.indexOf('Claude_') < 0;
    })[0];
  }
  return sheet || null;
}

/** 実施計画の既存「アイテムリスト」から品名と数量を読む。 */
function Zissi_readExistingItemList(zissiSs) {
  var sheet = Zissi_findItemListSheet(zissiSs);
  return Zissi_parseItemListValues(sheet && sheet.getLastRow() && sheet.getLastColumn()
    ? sheet.getRange(1, 1, sheet.getLastRow(), sheet.getLastColumn()).getValues() : []);
}

/** 列・行 index は 0 始まり。未検出は -1。数量候補は配列順に優先。 */
function Zissi_parseItemListValues(raw) {
  var NAME_HEADERS = ['品名', '品目', 'アイテム名', '品目名', 'item', 'name'];
  var QTY_HEADERS = ['現場必要数', '現場数', '数量', '個数', '必要数', 'qty', 'quantity'];
  var headers = (raw || []).slice(0, 5).map(function (row) {
    return row.map(function (v) { return String(v == null ? '' : v).trim().toLowerCase(); });
  });
  function detect(choices) {
    for (var h = 0; h < choices.length; h++) {
      for (var r = 0; r < headers.length; r++) {
        var col = headers[r].indexOf(choices[h]);
        if (col >= 0) return { row: r, col: col };
      }
    }
    return { row: -1, col: -1 };
  }
  var name = detect(NAME_HEADERS), qty = detect(QTY_HEADERS);
  var result = { items: [], qtyHeaderNotFound: qty.col < 0, nameHeaderNotFound: name.col < 0,
    headerRowIndex: Math.max(name.row, qty.row), nameCol: name.col, qtyCol: qty.col };
  if (result.qtyHeaderNotFound || result.nameHeaderNotFound) return result;
  var specCol = detect(['仕様', '仕様/サイズ']).col;
  var categoryCol = detect(['分類', 'カテゴリ']).col;
  raw.slice(result.headerRowIndex + 1).forEach(function (row) {
    var n = String(row[name.col] || '').trim();
    var value = row[qty.col];
    var q = typeof value === 'number' || typeof value === 'string' ? Number(value) : NaN;
    if (n && isFinite(q) && q > 0) {
      var item = { name: n, qty: q };
      if (specCol >= 0) item.spec = String(row[specCol] || '');
      if (categoryCol >= 0) item.category = String(row[categoryCol] || '');
      result.items.push(item);
    }
  });
  return result;
}

function Phase2_VolumeCalc_estimateTrucks(caseId) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);
  if (!c.zissiId) throw new Error('zissi 未設定: ' + caseId);

  // 本表を正本とし、有効行がない場合だけ提案を暫定利用する。
  const zissi = SpreadsheetApp.openById(c.zissiId);
  const existing = Zissi_readExistingItemList(zissi);
  let itemData = existing.items;
  let itemSourceIsProposal = false;
  const existingSheet = Zissi_findItemListSheet(zissi);
  let itemSheetUsed = existingSheet ? existingSheet.getName() : '';
  if (itemData.length === 0) {
    const proposal = zissi.getSheetByName(ITEMLIST_PROPOSAL_SHEET_NAME);
    if (proposal && proposal.getLastRow() >= 2) {
      itemData = Zissi_parseItemListValues(proposal.getRange(1, 1, proposal.getLastRow(), proposal.getLastColumn()).getValues()).items;
      itemSourceIsProposal = true;
      itemSheetUsed = proposal.getName();
    }
  }
  if (itemData.length === 0) {
    throw new Error('アイテムリストに有効な積荷がありません。' +
      (existing.qtyHeaderNotFound ? '⚠️ 数量列（現場必要数）のヘッダーを検出できませんでした。アイテムリストのヘッダー行を確認してください' : '') +
      (existing.nameHeaderNotFound ? ' 品名列のヘッダーを検出できませんでした。' : ''));
  }

  // 2) 備品マスタ全件読込み (品名 → 容積 map)
  const bihinSs = SpreadsheetApp.openById(BIHIN_MASTER_SS_ID);
  let bihinSheet = null;
  bihinSs.getSheets().forEach(function (s) { if (s.getSheetId() === BIHIN_MASTER_GID) bihinSheet = s; });
  if (!bihinSheet) throw new Error('備品在庫管理表 not found');
  const bihinLastRow = bihinSheet.getLastRow();
  const bihinBlock = bihinSheet.getRange(BIHIN_DATA_START_ROW, BIHIN_COL_NAME, bihinLastRow - BIHIN_DATA_START_ROW + 1, BIHIN_COL_VOLUME - BIHIN_COL_NAME + 1).getValues();
  const nameToVolume = {};
  bihinBlock.forEach(function (r) {
    const name = String(r[0] || '').trim();
    const vol = Number(r[r.length - 1] || 0);
    if (name && vol > 0) nameToVolume[name] = vol;
  });

  // 3) アイテムリスト走査
  const items = [];
  let totalVolume = 0;
  let matchedCount = 0, unmatchedCount = 0;
  itemData.forEach(function (row) {
    const name = row.name;
    const qty = row.qty;
    const spec = row.spec;
    if (!name || qty === 0) return;
    // 完全一致 → 部分一致 (品名 contains)
    let unitVolume = nameToVolume[name];
    let source = '';
    if (unitVolume) {
      source = 'exact';
    } else {
      // 部分一致 (品名が マスタ品名を含む or その逆)
      const keys = Object.keys(nameToVolume);
      for (let i = 0; i < keys.length; i++) {
        if (name.indexOf(keys[i]) >= 0 || (keys[i].length >= 4 && keys[i].indexOf(name) >= 0)) {
          unitVolume = nameToVolume[keys[i]];
          source = 'partial:' + keys[i];
          break;
        }
      }
    }
    if (!unitVolume) {
      // spec から推定
      const dims = _parseDimensionsFromName(name + ' ' + spec);
      if (dims) {
        unitVolume = (dims.w * dims.d * dims.h) / 1e9;
        source = 'spec-parse';
      } else {
        unitVolume = _estimateVolumeByCategory(row.category || '', name);
        source = 'category-estimate';
      }
    }
    const itemVolume = Math.round(unitVolume * qty * 10000) / 10000;
    totalVolume += itemVolume;
    if (source === 'exact' || source.indexOf('partial') === 0) matchedCount++;
    else unmatchedCount++;
    items.push({ name: name.slice(0, 30), qty: qty, unitVol: unitVolume, totalVol: itemVolume, source: source });
  });
  totalVolume = Math.round(totalVolume * 100) / 100;

  // 3.5) 総容積は zissi「アイテムリスト」シート AF1（合計セル）を最優先で採用（kim 2026-08 指示）。
  //      AF1 が数値でなければ従来の 備品マスタAP列合算 にフォールバック。
  let volumeSource = '備品マスタAP列合算';
  const af1 = itemSourceIsProposal ? null : _Phase2_readItemListAF1(zissi);
  if (af1 != null) { totalVolume = Math.round(af1 * 100) / 100; volumeSource = 'アイテムリスト!AF1（合計セル）'; }

  // 4) 安全係数
  const SAFETY_FACTOR = 1.3;
  const withMargin = Math.round(totalVolume * SAFETY_FACTOR * 100) / 100;

  // 5) トラック選定
  const selection = Phase2_selectTrucks(withMargin);
  const selectedTrucks = selection.selectedTrucks;
  const isCoveredByJisha = selection.isCoveredByJisha;
  const jishaCapacity = PHASE2_DUTRO_CAPACITY + PHASE2_CARAVAN_CAPACITY;

  // 積載容積の数値は荷台内寸。駐車場判定は TruckExteriorSpec.js の外寸を使う。
  const selectedTrucksWithExterior = selectedTrucks.map(function (t) {
    return { name: t.name, kind: t.kind, capacity: t.capacity, exterior: TruckExteriorSpec_get(t.name) };
  });
  const selectedTruckNames = selectedTrucksWithExterior.map(function (t) { return t.name; });

  // 容積寄与 top 20 を別途返す (外れ値検証用)
  const sortedByVol = items.slice().sort(function (a, b) { return b.totalVol - a.totalVol; });
  return {
    caseId: caseId,
    caseName: c.caseName,
    itemSheetUsed: itemSheetUsed,
    itemSourceIsProposal: itemSourceIsProposal,
    qtyHeaderNotFound: existing.qtyHeaderNotFound,
    nameHeaderNotFound: existing.nameHeaderNotFound,
    topByVolume: sortedByVol.slice(0, 20),
    items: items.slice(0, 30),
    itemCount: items.length,
    matchedCount: matchedCount,
    unmatchedCount: unmatchedCount,
    totalVolumeM3: totalVolume,
    volumeSource: volumeSource,
    safetyFactor: SAFETY_FACTOR,
    withMarginM3: withMargin,
    jishaCapacityM3: jishaCapacity,
    isCoveredByJisha: isCoveredByJisha,
    selectedTrucks: selectedTrucksWithExterior,
    parkingRequirement: TruckExteriorSpec_requirementFor(selectedTruckNames),
    coinParkingCheck: TruckExteriorSpec_checkCoinParking(selectedTruckNames),
    selectedTotalCapacityM3: Math.round(selectedTrucks.reduce(function (a, b) { return a + b.capacity; }, 0) * 100) / 100,
    fitRatio: Math.round(withMargin / selectedTrucks.reduce(function (a, b) { return a + b.capacity; }, 0) * 100) / 100
  };
}

if (typeof module !== "undefined" && module.exports) module.exports = { Phase2_selectTrucks: Phase2_selectTrucks, Zissi_parseItemListValues: Zissi_parseItemListValues };

/**
 * Phase3: 入稿データチェック を生成。
 *
 * 目的:
 *   印刷物 (壁面グラフィック / 看板 / ロゴボックス / LEDUP / バナー 等) を入稿する前に、
 *   Claude が PDF の内容を読んで誤字脱字・案件情報の整合性・連絡先誤記・サイズ表記等を指摘する。
 *
 * 入稿 PDF 探索:
 *   1) projectFolder 配下のサブフォルダで「入稿」「印刷」「最終データ」「制作物」「デザイン」「校了」を含むものから PDF を採集
 *   2) 上記が見つからなければ 預かり素材 配下 → さらに無ければ案件フォルダ直下の PDF
 *   3) マニュアル/申込/申請系 PDF は除外
 *   4) 最大 5 ファイル (token / レイテンシ抑制)
 *
 * 出力:
 *   zissi 内に「Claude_入稿データチェック」シート を作成 (or 上書き):
 *     A 制作物名 / B 重要度 / C カテゴリ / D 指摘内容 / E 修正案 / F 確認状況
 */

const NYUKO_CHECK_SHEET_NAME = 'Claude_入稿データチェック';
const NYUKO_CHECK_HEADERS = ['制作物名', '重要度', 'カテゴリ', '指摘内容', '修正案', '確認状況'];
const _NYUKO_FOLDER_KEYWORDS = ['入稿', '印刷', '最終データ', '最終', '制作物', 'デザイン', '校了', 'プリント', 'グラフィック', 'final', 'Final', 'FINAL', 'data'];
const _NYUKO_FILENAME_EXCLUDES = [
  '出展マニュアル', '主催者', '出展規定', '出展ガイド', 'マニュアル_', 'manual_',
  '申請', '申込', '提出フォーマット'
];

function Phase3_NyukoCheck_generate(caseId) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);

  // 実施計画書取得 (出力先)
  let zissiSs = null;
  if (c.zissiId) {
    try { zissiSs = SpreadsheetApp.openById(c.zissiId); } catch (e) {}
  }
  if (!zissiSs) {
    try {
      const folder = DriveApp.getFolderById(c.projectFolderId || c.folderId);
      const files = folder.getFilesByType(MimeType.GOOGLE_SHEETS);
      while (files.hasNext()) {
        const f = files.next();
        if (f.getName().indexOf('実施計画書') >= 0 && f.getName().indexOf('提出') < 0) {
          zissiSs = SpreadsheetApp.openById(f.getId());
          break;
        }
      }
    } catch (e) {}
  }
  if (!zissiSs) {
    throw new Error('実施計画書が見つかりません。');
  }

  // 入稿 PDF を収集
  const nyukoPdfs = _Phase3_collectNyukoPdfs(c);
  if (nyukoPdfs.length === 0) {
    throw new Error('入稿対象 PDF が見つかりません。projectFolder 配下に「入稿」「印刷」「制作物」「最終データ」名のサブフォルダ＋PDFを置くか、案件フォルダ直下に入稿 PDF を置いてください。');
  }

  // アイテムリスト / 確認シート / 修正要望シート など参照可能なら context に追加
  const cachedContext = [
    Case_loadClientContext(c),
    _Phase3_loadProjectInfoContext(c),
    _Phase3_loadItemListContext(zissiSs)
  ].filter(Boolean);

  const userPrompt = [
    '以下の展示会ブース案件の入稿予定 PDF を、印刷前のチェック観点で精査し、修正が必要な箇所を全て列挙してください。',
    '',
    '## 案件情報',
    '- クライアント: ' + c.clientName,
    '- 案件名: ' + c.caseName,
    '- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate),
    '- ブースサイズ: ' + (c.boothSize || '未確定'),
    '- 許容される最大の造作範囲: ' + (_Phase1_insetBoothSize(c.boothSize, _PHASE1_BOOTH_INSET_MM) || '小間実寸が不明（要確認）。小間実寸から四方100mm内側'),
    '',
    '## チェック観点（必ず全観点を確認）',
    '1. **誤字脱字**: クライアント社名・展示会名・キャッチコピー・本文の typo / 半角全角の混在 / 不要なスペース',
    '2. **案件情報の整合性**: クライアント名/イベント名/会場/日付/小間番号 が案件情報と一致するか',
    '3. **連絡先**: 電話番号 / メール / URL / QR コードのドメイン と公式情報の食い違い',
    '4. **ロゴ・社名表記**: 株式会社・(株)・正式社名 のゆれ。商標表記 (®/™) の有無',
    '5. **サイズ表記**: パネル/グラフィックの寸法表記が他制作物と矛盾しないか',
    '6. **画像品質の懸念**: 視認できる範囲で解像度低そう/ジャギー/ブロックノイズが見える箇所',
    '7. **色味・カラーモード**: 明らかな RGB 想定の鮮やかすぎる色 / CMYK 印刷で変色しそうな箇所',
    '8. **塗り足し・トンボ**: 端まで色やデザインが伸びているが塗り足しが足りない可能性',
    '9. **不適切な内容**: 別案件のロゴ・テキスト混入、テストデータ残置 (lorem ipsum / ダミー画像)',
    '10. **その他のリスク**: ハレーション/ハーフトーン化/小サイズ文字 (4pt 未満) など',
    '11. **小間実寸からの逃げ**: 図面・レイアウトを含む資料では、造作が小間実寸から四方100mm内側に収まっているか。収まっていなければ severity=high',
    '',
    '## 出力形式（厳守・前後の説明文や ```json``` ブロック禁止・JSON 単体）',
    '{',
    '  "checks": [',
    '    {',
    '      "pdfLabel": "<該当 PDF のファイル名>",',
    '      "severity": "high|mid|low",',
    '      "category": "<上記カテゴリのいずれか>",',
    '      "issue": "<具体的な指摘 (ページ番号や位置がわかれば明記)>",',
    '      "suggestion": "<どう直すべきか具体的に>"',
    '    }',
    '  ],',
    '  "summary": "<全体所感を 200 字以内>"',
    '}',
    '',
    '注意:',
    '- 推測でなく PDF から実際に観察できた事項のみ書く。判断つかない場合は severity=low + issue 末尾に「※要確認」と記載。',
    '- 問題がなければ checks は空配列で良い。summary には「問題は確認できず」と書く。',
    '- 各 PDF 1 件あたりの指摘は重要度高いものから順に並べる。'
  ].join('\n');

  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    documents: nyukoPdfs.map(function (p) { return { driveFileId: p.driveFileId, label: p.label }; }),
    maxTokens: 6000
  });

  const parsed = _Phase1_parseJson(res.text);
  const checks = parsed.checks || [];

  // 出力シート
  let outSheet = zissiSs.getSheetByName(NYUKO_CHECK_SHEET_NAME);
  if (!outSheet) {
    try { outSheet = zissiSs.insertSheet(NYUKO_CHECK_SHEET_NAME); }
    catch (e) { outSheet = zissiSs.getSheetByName(NYUKO_CHECK_SHEET_NAME); }
  } else {
    outSheet.clear();
  }
  outSheet.getRange(1, 1, 1, NYUKO_CHECK_HEADERS.length).setValues([NYUKO_CHECK_HEADERS])
    .setFontWeight('bold').setBackground('#fce5cd');
  outSheet.setFrozenRows(1);

  // メタ情報行 (チェック対象 PDF / 生成日時 / Claude summary)
  const metaRows = [
    ['【チェック対象 PDF】', '', '', nyukoPdfs.map(function (p) { return p.label; }).join('\n'), '', ''],
    ['【全体所感】', '', '', String(parsed.summary || '').slice(0, 500), '', ''],
    ['【生成日時】', '', '', Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy/MM/dd HH:mm'), '', '']
  ];
  outSheet.getRange(2, 1, metaRows.length, NYUKO_CHECK_HEADERS.length).setValues(metaRows)
    .setBackground('#f3f3f3').setFontStyle('italic');

  if (checks.length > 0) {
    // 重要度順ソート (high → mid → low)
    const rank = { high: 0, mid: 1, low: 2 };
    checks.sort(function (a, b) {
      return (rank[a.severity] || 9) - (rank[b.severity] || 9);
    });
    const rows = checks.map(function (ck) {
      return [
        ck.pdfLabel || '',
        ck.severity || '',
        ck.category || '',
        ck.issue || '',
        ck.suggestion || '',
        '未対応'
      ];
    });
    const startRow = 2 + metaRows.length;
    outSheet.getRange(startRow, 1, rows.length, NYUKO_CHECK_HEADERS.length).setValues(rows);

    // 重要度の色付け
    for (let i = 0; i < checks.length; i++) {
      const sev = checks[i].severity;
      const bg = sev === 'high' ? '#f4cccc' : sev === 'mid' ? '#fff2cc' : '#d9ead3';
      outSheet.getRange(startRow + i, 2).setBackground(bg);
    }
  }

  // 列幅
  outSheet.setColumnWidth(1, 220); // 制作物名
  outSheet.setColumnWidth(2, 70);  // 重要度
  outSheet.setColumnWidth(3, 120); // カテゴリ
  outSheet.setColumnWidth(4, 380); // 指摘内容
  outSheet.setColumnWidth(5, 320); // 修正案
  outSheet.setColumnWidth(6, 90);  // 確認状況
  outSheet.getRange(1, 1, outSheet.getMaxRows(), NYUKO_CHECK_HEADERS.length).setWrap(true);

  const sheetUrl = PanelLinks_sheetUrl(zissiSs, outSheet);

  CaseList_touchUpdatedAt(caseId);
  MasterWriteBack_recordArtifact(caseId, '入稿データチェック',
    '入稿チェック (' + checks.length + ' 指摘 / ' + nyukoPdfs.length + ' PDF)', sheetUrl);

  return {
    zissiSheetUrl: zissiSs.getUrl(),
    checkSheetUrl: sheetUrl,
    checkSheetName: NYUKO_CHECK_SHEET_NAME,
    pdfCount: nyukoPdfs.length,
    pdfLabels: nyukoPdfs.map(function (p) { return p.label; }),
    issueCount: checks.length,
    severityCount: {
      high: checks.filter(function (c) { return c.severity === 'high'; }).length,
      mid: checks.filter(function (c) { return c.severity === 'mid'; }).length,
      low: checks.filter(function (c) { return c.severity === 'low'; }).length
    },
    summary: parsed.summary || '',
    usage: res.usage
  };
}

/**
 * 案件フォルダ配下から入稿対象の PDF を最大 5 件採集。
 * 入稿系サブフォルダ → 案件フォルダ直下 → 預かり素材 の順で探索。
 * マニュアル/申請/申込 系は除外。
 */
function _Phase3_collectNyukoPdfs(c) {
  const seen = {};
  const out = [];
  const MAX = 5;

  // (1) projectFolder 直下に 入稿/印刷/制作物... のサブフォルダがあれば優先
  const baseFolderId = c.projectFolderId || c.folderId;
  if (baseFolderId) {
    try {
      const base = DriveApp.getFolderById(baseFolderId);
      const subFolders = base.getFolders();
      while (subFolders.hasNext() && out.length < MAX) {
        const sub = subFolders.next();
        const subName = sub.getName();
        const isNyuko = _NYUKO_FOLDER_KEYWORDS.some(function (k) { return subName.indexOf(k) >= 0; });
        if (!isNyuko) continue;
        // この入稿系フォルダ配下を 2 階層まで再帰
        _Phase3_collectPdfsRecursive(sub.getId(), out, seen, subName, 2, MAX);
      }
    } catch (e) { /* skip */ }
  }

  // (2) 案件フォルダ直下の PDF (フォルダが存在しないケース)
  if (out.length < MAX) {
    [c.folderId, c.projectFolderId].filter(Boolean).forEach(function (fid) {
      if (out.length >= MAX) return;
      try {
        const folder = DriveApp.getFolderById(fid);
        const it = folder.getFilesByType(MimeType.PDF);
        while (it.hasNext() && out.length < MAX) {
          const f = it.next();
          const id = f.getId();
          if (seen[id]) continue;
          const name = f.getName();
          if (_Phase3_isExcluded(name)) continue;
          seen[id] = true;
          out.push({ driveFileId: id, label: name, source: '案件フォルダ直下' });
        }
      } catch (e) {}
    });
  }

  return out.slice(0, MAX);
}

function _Phase3_collectPdfsRecursive(folderId, out, seen, sourceLabel, maxDepth, MAX) {
  if (maxDepth <= 0 || out.length >= MAX) return;
  let folder;
  try { folder = DriveApp.getFolderById(folderId); } catch (e) { return; }
  const it = folder.getFilesByType(MimeType.PDF);
  while (it.hasNext() && out.length < MAX) {
    const f = it.next();
    const id = f.getId();
    if (seen[id]) continue;
    const name = f.getName();
    if (_Phase3_isExcluded(name)) continue;
    seen[id] = true;
    out.push({ driveFileId: id, label: name, source: sourceLabel });
  }
  const subs = folder.getFolders();
  while (subs.hasNext() && out.length < MAX) {
    const sub = subs.next();
    _Phase3_collectPdfsRecursive(sub.getId(), out, seen, sourceLabel + '/' + sub.getName(), maxDepth - 1, MAX);
  }
}

function _Phase3_isExcluded(filename) {
  const n = String(filename || '');
  for (let i = 0; i < _NYUKO_FILENAME_EXCLUDES.length; i++) {
    if (n.indexOf(_NYUKO_FILENAME_EXCLUDES[i]) >= 0) return true;
  }
  return false;
}

function _Phase3_loadProjectInfoContext(c) {
  const lines = [];
  lines.push('【案件情報 (照合用)】');
  lines.push('- クライアント正式名: ' + (c.clientName || ''));
  lines.push('- 案件名: ' + (c.caseName || ''));
  lines.push('- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate));
  lines.push('- ブースサイズ: ' + (c.boothSize || '未確定'));
  lines.push('- 許容される最大の造作範囲: ' + (_Phase1_insetBoothSize(c.boothSize, _PHASE1_BOOTH_INSET_MM) || '小間実寸が不明（要確認）。小間実寸から四方100mm内側'));
  return lines.join('\n');
}

function _Phase3_loadItemListContext(zissiSs) {
  try {
    const sheet = zissiSs.getSheetByName(ITEMLIST_PROPOSAL_SHEET_NAME);
    if (!sheet) return '';
    const lastRow = sheet.getLastRow();
    if (lastRow < 2) return '';
    const data = sheet.getRange(2, 1, Math.min(lastRow - 1, 100), 4).getValues();
    const printingItems = data.filter(function (r) {
      const cat = String(r[0] || '');
      return cat.indexOf('印刷') >= 0 || cat.indexOf('グラフィック') >= 0 || cat.indexOf('看板') >= 0;
    });
    if (printingItems.length === 0) return '';
    const lines = ['【アイテムリスト 印刷・グラフィック関連 (照合用)】'];
    printingItems.forEach(function (r) {
      lines.push('- ' + r[0] + ' / ' + r[1] + ' / ' + r[2] + ' / ' + r[3]);
    });
    return lines.join('\n');
  } catch (e) {
    return '';
  }
}

/**
 * Phase4: 本番当日案内 初版 を生成。
 *
 * 対象パーティ:
 *  - 'client'       : クライアント（出展企業）
 *  - 'construction' : 施工会社
 *  - 'ops'          : 運営スタッフ
 *  - 'driver'       : ドライバー
 *
 * 各パーティに合わせた「当日の集合時刻 / 場所 / 持ち物 / 連絡先 / 想定スケジュール / 注意事項」
 * を含むメール本文を Gmail Draft + Doc で生成。
 */

const _DAY_BRIEF_CONFIG = {
  client: {
    displayName: 'クライアント',
    docSuffix: '当日案内_クライアント',
    subjectFallback: '展示会本番 当日のご案内',
    manualQueries: ['本番当日', '当日進行', 'クライアント当日', '本番案内', '受付', '会場入り'],
    contextHint: 'クライアント（出展企業ご担当者様）への本番当日案内。集合時刻 / 場所 / 受付ブース位置 / 担当連絡先 / 当日の流れ（オープニング → セッション → 終了 → 撤去開始 等）を上品で丁寧な調子で。'
  },
  construction: {
    displayName: '施工会社',
    docSuffix: '当日案内_施工会社',
    subjectFallback: '展示会本番 当日案内（施工 / 設営撤去）',
    manualQueries: ['設営', '撤去', '搬入', '搬出', '施工会社', '当日'],
    contextHint: '施工会社への本番案内。設営開始時刻・搬入導線・養生指示・設営完了マイルストーン・撤去開始時刻・搬出ルート・連絡先を実務向け簡潔な調子で。'
  },
  ops: {
    displayName: '運営スタッフ',
    docSuffix: '当日案内_運営スタッフ',
    subjectFallback: '展示会本番 当日のご案内（運営スタッフ）',
    manualQueries: ['運営スタッフ', '当日進行', 'スタッフ', '受付', '当日タスク'],
    contextHint: '当日運営スタッフ向け案内。集合時刻 / 場所 / 服装 / 持参物 / 担当ポジション / シフト / 緊急連絡先 / よくある質問対応を実務的に。'
  },
  driver: {
    displayName: 'ドライバー',
    docSuffix: '当日案内_ドライバー',
    subjectFallback: '展示会本番 搬入出当日案内',
    manualQueries: ['ドライバー', '搬入出', '車両', 'トラック', '駐車'],
    contextHint: '搬入出ドライバーへの案内。集合時刻 / 集合場所（倉庫等）/ 車両サイズ / 会場までの推奨ルート / 搬入入口・搬出入口 / 駐車場 / 連絡先 / 積荷リストへの参照を実務的に。'
  }
};

function Phase4_DayBrief_generate(caseId, partyType) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);
  const cfg = _DAY_BRIEF_CONFIG[partyType];
  if (!cfg) throw new Error('不明な partyType: ' + partyType + ' (有効値: client / construction / ops / driver)');

  const manualPages = ManualLoader_findPages(cfg.manualQueries).slice(0, 12);
  const cachedContext = [
    Case_loadClientContext(c),
    '【関連マニュアル抜粋】',
    ...manualPages.map(function (p) { return '# ' + p.title + '\nパス: ' + p.path + '\n\n' + p.body; })
  ].filter(Boolean);

  const userPrompt = [
    '以下の案件について、本番当日に ' + cfg.displayName + ' に送るメール本文（初版）を作成してください。',
    '',
    '## メールの目的',
    cfg.contextHint,
    '',
    '## 案件情報',
    '- クライアント: ' + c.clientName,
    '- 案件名: ' + c.caseName,
    '- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate),
    '- ブースサイズ: ' + (c.boothSize || '未確定'),
    '',
    '## 出力形式（厳守）',
    '次の JSON だけを返してください。前後の説明文や ```json``` ブロックは不要。',
    '{',
    '  "subject": "<メール件名>",',
    '  "body": "<メール本文・改行は \\n>",',
    '  "confirmations": [',
    '    {"category": "<確認カテゴリ>", "content": "<確認したい内容>"}',
    '  ]',
    '}',
    '',
    '注意:',
    '- 受信者の固有名・連絡先（メアド・電話番号）は案件情報に無いので本文に書かず confirmations へ。',
    '- 集合時刻・場所・担当者名等の数値/固有値で未確定なものは confirmations へ。',
    '- 本文には「以下未確定:」「○○未確定」と仮置きで書かず、確定情報の範囲で自然な文を生成し、不足は confirmations に分離する。',
    '- 関連マニュアルが定める当日進行・チェックリスト・緊急時連絡フローは本文に必ず反映。'
  ].join('\n');

  const manualPdfs = CaseManualPdf_find(c, { includeSubmission: false });
  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    documents: manualPdfs,
    maxTokens: 3500
  });

  const parsed = _Phase1_parseJson(res.text);

  const draft = GmailApp.createDraft(
    '',
    Mail_externalSubject(c.caseId, c.caseName, parsed.subject || cfg.subjectFallback, cfg.displayName + '・当日案内'),
    parsed.body || ''
  );

  const folderId = Case_resolveProjectRoot(c);
  const docName = c.caseId + '_' + c.caseName + '_' + cfg.docSuffix + '_初版';
  const doc = DocumentApp.create(docName);
  doc.getBody().setText('件名: ' + (parsed.subject || '') + '\n\n' + (parsed.body || ''));
  doc.saveAndClose();
  if (folderId) {
    try { DriveApp.getFileById(doc.getId()).moveTo(DriveApp.getFolderById(folderId)); } catch (e) {}
  }

  if (parsed.confirmations && parsed.confirmations.length > 0) {
    const tagged = parsed.confirmations.map(function (x) {
      return { category: '[当日案内/' + cfg.displayName + '] ' + (x.category || ''), content: x.content || '' };
    });
    ConfirmationSheet_appendItems(caseId, tagged, 4);
  }
  CaseList_touchUpdatedAt(caseId);

  const docUrl = DocumentApp.openById(doc.getId()).getUrl();
  MasterWriteBack_recordArtifact(caseId, cfg.displayName + '当日案内', parsed.subject || '', docUrl);

  return {
    partyType: partyType,
    partyName: cfg.displayName,
    subject: parsed.subject,
    draftId: draft.getId(),
    docUrl: docUrl,
    confirmationCount: (parsed.confirmations || []).length,
    manualPagesUsed: manualPages.length,
    manualPdfs: manualPdfs.map(function (p) { return p.label; }),
    usage: res.usage
  };
}

/**
 * Phase5: 質問応答 (Q&A) — 現場/お客様の質問に即答するサポート機能。
 *
 * 流れ:
 *   1) caseId と質問を受け取る
 *   2) 質問からキーワード抽出 → マニュアル抜粋を 5〜10 ページ取得
 *   3) 案件 zissi の「確認」「報告」「アイテムリスト」「設営」シートを context として乗せる
 *   4) Claude に質問 + context を投げて回答 + 参照元 を JSON で返す
 *
 * 出力:
 *   { answer, sources[], confidence, follow_up_questions[] }
 *   ハルシネーション禁止 — 答えられない場合は「マニュアル/案件データに該当情報なし」と書く。
 */

function Phase5_Qna_ask(caseId, question) {
  if (!question || !String(question).trim()) {
    throw new Error('質問が空です。');
  }
  const q = String(question).trim();

  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);

  const built = _Phase5_buildQnaContext(c, q);
  const queries = built.queries;
  const manualPages = built.manualPages;
  const zissiSs = built.zissiSs;
  const cachedContext = built.cachedContext;

  const userPrompt = [
    '展示会ブース制作の規定判定ができる職人 AI として、上の context と添付 PDF のみを根拠に',
    '以下の質問に答えてください。**context に書いていない情報は推測で答えず**、確認すべき相手 (主催/施工/CL 等) を follow_up_questions に出す。',
    '',
    '## 質問',
    q,
    '',
    '## 出力形式（厳守・JSON 単体、説明文/```json``` ブロック禁止）',
    '{',
    '  "regulation_check": {"verdict": "適合|違反|グレー|規定に記載なし", "quoted_rule": "<原文引用。改変禁止。無ければ空文字>", "source_label": "<PDFファイル名 or マニュアルページ名>", "reasoning": "<読み方>"},',
    '  verdict の定義:',
    '    適合 = 引用条文に照らして問題なし',
    '    違反 = 引用条文に明確に反する',
    '    グレー = 適用される条文は引用できたが、質問の具体的なケースの可否が明記されていない',
    '      （★条文を1つでも quoted_rule に引用できたなら「規定に記載なし」ではなく必ずこれ）',
    '    規定に記載なし = 関連する条文が資料内に一切見つからず quoted_rule が空',
    '  "solutions": [{"rank": 1, "tier": "規格組替|再利用フィラー|構造で吸収|消耗品", "action": "<具体策>", "waste": "ゼロ|少|消耗", "note": "<制約・注意>"}],',
    '  "answer": "<回答本文。前置きなしで端的に。300 字以内目安>",',
    '  "sources": [',
    '    {"type": "出展規定PDF|マニュアル|案件資料ダイジェスト|保有機材|案件zissi", "label": "<参照元>", "excerpt": "<100字以内>"}',
    '  ],',
    '  "confidence": "high|mid|low",',
    '  "follow_up_questions": [',
    '    "<答えるために追加で確認すべきこと>"',
    '  ]',
    '}',
    '',
    '## 厳守ルール',
    '- マニュアル/案件データに書いていない事実は答えない。「context に該当情報がないため要確認」と書き follow_up_questions に積む。',
    '- 数値・日時・連絡先は context から完全一致で引用。少しでも曖昧なら confidence=low、要確認と明記。',
    '- 推測は禁止。ハルシネーション禁止。',
    '- sources は必ず実在の引用元のみ（マニュアル抜粋 or zissi シート名）。捏造禁止。'
    ,'- quoted_rule は添付 PDF / マニュアルからの原文コピーのみ。要約・言い換え・創作は禁止。引用できなければ verdict="規定に記載なし" とし、主催者事務局への確認を follow_up_questions に必ず入れる。'
    ,'- quoted_rule が空でない場合 verdict に "規定に記載なし" を選んではならない。適合/違反/グレーのいずれかにする。'
    ,'- solutions は廃棄ゼロ優先で、規格組替 → 再利用フィラー → 構造で吸収 → 消耗品の順。木工造作・使い捨て部材を第一候補にしない。'
    ,'- 寸法・数量はモジュール割り計算結果と保有機材の値をそのまま使い、再計算・上書きしない。'
    ,'- 在庫数を超える使用を提案しない。展示パネルは単体で自立しない制約も守る。'
  ].join('\n');

  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    documents: built.manualPdfs,
    maxTokens: 2500
  });

  const parsed = _Phase1_parseJson(res.text);

  // Q&A ログを zissi の「Claude_QAログ」シートに追記
  if (zissiSs) {
    _Phase5_appendQaLog(zissiSs, q, parsed);
  }

  return {
    question: q,
    regulationCheck: parsed.regulation_check || { verdict: '規定に記載なし', quoted_rule: '', source_label: '', reasoning: '' },
    solutions: parsed.solutions || [],
    answer: parsed.answer || '(回答が取得できませんでした)',
    sources: parsed.sources || [],
    confidence: parsed.confidence || 'low',
    followUpQuestions: parsed.follow_up_questions || [],
    manualPagesUsed: manualPages.length,
    queriesUsed: queries,
    usage: res.usage
  };
}

function _Phase5_buildQnaContext(c, q) {
  const queries = _Phase5_extractQueryKeywords(q);
  const manualPages = ManualLoader_findPages(queries).slice(0, 8);
  const manualPdfs = CaseManualPdf_find(c, { maxFiles: 3 }).slice(0, 3);
  const digest = CaseDigest_load(c) || '';
  let zissiSs = null;
  if (c.zissiId) try { zissiSs = SpreadsheetApp.openById(c.zissiId); } catch (e) {}
  const zissiContext = zissiSs ? _Phase5_extractZissiContext(zissiSs) : '';
  const targets = [];
  const seen = {};
  const re = /(?:^|[^0-9])([0-9]{4,})(?=[^0-9]|$)/g;
  let m;
  while ((m = re.exec(String(q))) && targets.length < 3) {
    const n = Number(m[1]); if (!seen[n]) { targets.push(n); seen[n] = true; }
  }
  const parts = OwnedEquipment_wallParts();
  const calculations = targets.map(function (target) {
    return { targetMm: target, result: ModuleFit_solve(target, parts) };
  });
  const calcText = calculations.map(function (x) {
    const choices = x.result.exact.length ? x.result.exact : x.result.closest;
    const lines = choices.map(function (s) {
      return s.pieces.map(function (p) { return p.name + ' ' + p.width + '×' + p.count; }).join(' + ') + ' = ' + s.total + 'mm / gap ' + s.gap + 'mm';
    });
    const headline = x.result.exact.length ? 'ぴったり組める解あり。' : 'ぴったり組める解なし。最小の余りは ' + (choices[0] ? Math.abs(choices[0].gap) : '算出不能') + ' mm。';
    return '対象幅 ' + x.targetMm + 'mm: ' + headline + '\n' + lines.join('\n');
  }).join('\n\n');
  const cachedContext = [
    OwnedEquipment_describe(),
    digest ? '【案件資料ダイジェスト(夜間に全資料を読んで作成)】\n' + digest : '',
    '【関連マニュアル抜粋】\n' + manualPages.map(function (p) { return '# ' + p.title + '\nパス: ' + p.path + '\n\n' + p.body; }).join('\n\n'),
    '【案件情報】\n- 案件 ID: ' + c.caseId + '\n- クライアント: ' + c.clientName + '\n- 案件名: ' + c.caseName + '\n- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate) + '\n- ブースサイズ: ' + (c.boothSize || '未確定'),
    '【案件 zissi 抜粋】\n' + (zissiContext || '(zissi 未取得)'),
    calcText ? '【モジュール割り計算結果（コードで計算済み・この数値を使うこと）】\nこの計算はコードで実行済み。LLM 側で再計算・上書きしないこと。\n' + calcText : ''
  ].filter(Boolean);
  return { queries: queries, manualPages: manualPages, manualPdfs: manualPdfs, digest: digest, zissiSs: zissiSs, cachedContext: cachedContext, solverTargets: targets, solverParts: parts, solverCalculations: calculations };
}

function _debug_qnaContext(caseId, question) {
  const c = CaseList_getById(caseId);
  if (!c) return { error: 'not found' };
  const b = _Phase5_buildQnaContext(c, String(question || ''));
  return { caseId: caseId, manualPages: b.manualPages.length, regulationPdfs: b.manualPdfs.map(function (p) { return p.label; }), digestPresent: Boolean(b.digest), digestChars: b.digest.length, solverInput: { targets: b.solverTargets, parts: b.solverParts }, solverResults: b.solverCalculations, context: b.cachedContext };
}

function _Phase5_extractQueryKeywords(question) {
  const text = String(question || '').trim();
  const particles = /(?:しかありません|について|における|ですが|ますが|です|ます|必要|場合|とは|には|では|から|まで|ので|のに|けど|が|は|を|に|で|と|も|や|へ|の)/;
  const fragments = text
    .replace(/[、。．・「」『』（）()【】\[\]\?？!！\.,]/g, ' ')
    .split(/\s+/)
    .reduce(function (all, phrase) { return all.concat(phrase.split(particles)); }, [])
    .map(function (part) { return part.trim(); })
    .filter(function (part) { return part.length >= 2 && !/^[0-9０-９]+(?:mm)?$/i.test(part) && !/^[^A-Za-z0-9\u3040-\u30ff\u3400-\u9fff]+$/.test(part); });
  const tokens = [];
  const preferred = text.match(/パネル|間仕切り?|施工|規定/g) || [];
  preferred.forEach(function (token) { tokens.push(token.replace(/り$/, '')); });
  fragments.forEach(function (fragment) {
    const blocks = fragment.match(/[ァ-ヶー]{3,}|[一-龠]{2,}|[A-Za-z][A-Za-z0-9]{2,}/g) || [];
    blocks.forEach(function (block) { tokens.push(block); });
    if (fragment.length <= 20 && !/^[0-9０-９]+$/.test(fragment)) tokens.push(fragment);
  });
  const seen = {};
  const out = [];
  for (let i = 0; i < tokens.length && out.length < 8; i++) {
    if (!seen[tokens[i]]) { seen[tokens[i]] = true; out.push(tokens[i]); }
  }
  return out.length > 0 ? out : [text.slice(0, 20) || '質問'];
}

function _Phase5_extractZissiContext(zissiSs) {
  const sections = [];
  // 確認シート
  try {
    const sh = zissiSs.getSheetByName('確認') || _Phase6_findSheetByKeyword(zissiSs, ['確認事項']);
    if (sh) {
      const lastRow = Math.min(sh.getLastRow(), 40);
      const lastCol = Math.min(sh.getLastColumn(), 6);
      if (lastRow >= 2 && lastCol >= 2) {
        const data = sh.getRange(1, 1, lastRow, lastCol).getValues();
        sections.push('--- 「' + sh.getName() + '」抜粋 ---\n' + _Phase5_renderRows(data));
      }
    }
  } catch (e) {}
  // アイテムリスト
  try {
    const sh = zissiSs.getSheetByName(ITEMLIST_PROPOSAL_SHEET_NAME);
    if (sh) {
      const lastRow = Math.min(sh.getLastRow(), 60);
      const lastCol = Math.min(sh.getLastColumn(), 5);
      if (lastRow >= 2 && lastCol >= 2) {
        const data = sh.getRange(1, 1, lastRow, lastCol).getValues();
        sections.push('--- 「アイテムリスト」抜粋 ---\n' + _Phase5_renderRows(data));
      }
    }
  } catch (e) {}
  // 設営/搬入関連 Doc/シート
  try {
    const sh = _Phase6_findSheetByKeyword(zissiSs, ['設営', '搬入', '当日']);
    if (sh) {
      const lastRow = Math.min(sh.getLastRow(), 40);
      const lastCol = Math.min(sh.getLastColumn(), 6);
      if (lastRow >= 2 && lastCol >= 2) {
        const data = sh.getRange(1, 1, lastRow, lastCol).getValues();
        sections.push('--- 「' + sh.getName() + '」抜粋 ---\n' + _Phase5_renderRows(data));
      }
    }
  } catch (e) {}
  return sections.join('\n\n');
}

function _Phase5_renderRows(data) {
  const lines = [];
  data.forEach(function (row) {
    const text = row.map(function (v) { return String(v || '').trim(); }).filter(Boolean).join(' | ');
    if (text) lines.push(text);
  });
  return lines.join('\n');
}

function _Phase5_appendQaLog(zissiSs, question, parsed) {
  const SHEET = 'Claude_QAログ';
  let sh = zissiSs.getSheetByName(SHEET);
  if (!sh) {
    try { sh = zissiSs.insertSheet(SHEET); }
    catch (e) { sh = zissiSs.getSheetByName(SHEET); }
    if (sh) {
      sh.getRange(1, 1, 1, 8).setValues([['日時', '質問', '回答', '確信度', '要追加確認', '規定判定', '引用条文', '採用解決策']])
        .setFontWeight('bold').setBackground('#cfe2f3');
      sh.setFrozenRows(1);
      sh.setColumnWidth(1, 130);
      sh.setColumnWidth(2, 300);
      sh.setColumnWidth(3, 400);
      sh.setColumnWidth(4, 80);
      sh.setColumnWidth(5, 260);
    }
  }
  if (!sh) return;
  const expected = ['日時', '質問', '回答', '確信度', '要追加確認', '規定判定', '引用条文', '採用解決策'];
  if (sh.getMaxColumns() < expected.length) sh.insertColumnsAfter(sh.getMaxColumns(), expected.length - sh.getMaxColumns());
  const current = sh.getRange(1, 1, 1, expected.length).getValues()[0];
  for (let i = 0; i < expected.length; i++) if (!current[i]) sh.getRange(1, i + 1).setValue(expected[i]);
  const ts = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy/MM/dd HH:mm');
  const regulation = parsed.regulation_check || {};
  const adopted = (parsed.solutions || []).map(function (s) { return (s.rank || '') + '. [' + (s.tier || '') + '] ' + (s.action || ''); }).join('\n');
  sh.appendRow([
    ts,
    question,
    parsed.answer || '',
    parsed.confidence || '',
    (parsed.follow_up_questions || []).join('\n'),
    regulation.verdict || '',
    regulation.quoted_rule || '',
    adopted
  ]);
}

if (typeof module !== 'undefined' && module.exports) module.exports = {
  _Phase5_extractQueryKeywords: _Phase5_extractQueryKeywords
};

/**
 * Phase6: 最終見積 を生成。
 *
 * 目的:
 *   案件終了後、原価実績ベースで「最終見積」をクライアント請求/社内記録用にまとめる。
 *   初版見積 (Phase1_Estimate) との差分・追加発注・減額調整 を Claude が拾ってシートに出す。
 *
 * 出力:
 *   - zissi 内「Claude_最終見積」シート (品目別: 見積初版/最終/差分/差分理由)
 *   - 確認シートへの未確定項目積み上げ
 */

const FINAL_ESTIMATE_SHEET_NAME = 'Claude_最終見積';
const FINAL_ESTIMATE_HEADERS = ['カテゴリ', '品目', '数量', '初版単価', '最終単価', '初版小計', '最終小計', '差分', '差分理由'];

function Phase6_FinalEstimate_generate(caseId) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);

  let zissiSs = null;
  if (c.zissiId) {
    try { zissiSs = SpreadsheetApp.openById(c.zissiId); } catch (e) {}
  }
  if (!zissiSs) throw new Error('実施計画書が見つかりません。');

  // 初版見積 / アイテムリスト / 確認事項 を context として渡す
  const itemListSnippet = _Phase6_loadItemListSnippet(zissiSs);
  const estimateSnippet = _Phase6_loadEstimateSnippet(zissiSs);
  const costSnippet = _Phase6_loadCostSnippet(zissiSs);
  const confirmationLog = _Phase6_loadConfirmations(caseId);

  const manualPages = ManualLoader_findPages([
    '最終見積', '原価', '見積管理', '差分', '請求書'
  ]).slice(0, 6);

  const cachedContext = [
    Case_loadClientContext(c),
    '【関連マニュアル抜粋】',
    ...manualPages.map(function (p) { return '# ' + p.title + '\nパス: ' + p.path + '\n\n' + p.body; })
  ].filter(Boolean);

  const userPrompt = [
    '以下の案件の「最終見積」を、初版見積と実発注/実工数の差分を踏まえて作成してください。',
    '',
    '## 案件情報',
    '- 案件 ID: ' + c.caseId,
    '- クライアント: ' + c.clientName,
    '- 案件名: ' + c.caseName,
    '- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate),
    '',
    '## アイテムリスト（Claude_アイテムリスト提案）',
    itemListSnippet || '(なし — Phase2 アイテムリストを先に生成推奨)',
    '',
    '## 初版見積シート抜粋',
    estimateSnippet || '(初版見積データなし)',
    '',
    '## 原価/発注実績シート抜粋',
    costSnippet || '(原価データなし — 未記入と判定)',
    '',
    '## 確認事項ログ',
    confirmationLog || '(空)',
    '',
    '## 出力形式（厳守・JSON 単体、説明文/```json``` ブロック禁止）',
    '{',
    '  "items": [',
    '    {',
    '      "category": "<カテゴリ>",',
    '      "name": "<品目名>",',
    '      "quantity": <数値>,',
    '      "initial_unit_price": <初版単価, 不明なら null>,',
    '      "final_unit_price": <最終単価, 不明なら null>,',
    '      "delta_reason": "<増減理由>"',
    '    }',
    '  ],',
    '  "missing_inputs": [',
    '    {"category": "<カテゴリ>", "content": "<不足情報>"}',
    '  ],',
    '  "summary": "<総括 (200 字以内)>"',
    '}',
    '',
    '## 重要ルール',
    '- 単価が不明な品目は initial_unit_price / final_unit_price を null にし、delta_reason に「単価未記入」と書く。推測で数値を埋めない。',
    '- 数量も不明なら 0 にして delta_reason に明記。',
    '- 差分は (final_unit_price * quantity) - (initial_unit_price * quantity) で計算側 (本実装側) が出す。Claude は単価と理由だけ書けばよい。',
    '- 差分理由は具体的に (例: 「現地でモニター追加発注」「電気容量増 → 工事費 +」「リユース確定で外注削減」)。',
    '- 品目は アイテムリスト + 初版見積に出てくる範囲。新規追加発注は実績シートから拾う。',
    '- ハルシネーション禁止。'
  ].join('\n');

  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    maxTokens: 6000
  });

  const parsed = _Phase1_parseJson(res.text);
  const items = parsed.items || [];

  // 出力シート
  let outSheet = zissiSs.getSheetByName(FINAL_ESTIMATE_SHEET_NAME);
  if (!outSheet) {
    try { outSheet = zissiSs.insertSheet(FINAL_ESTIMATE_SHEET_NAME); }
    catch (e) { outSheet = zissiSs.getSheetByName(FINAL_ESTIMATE_SHEET_NAME); }
  } else {
    outSheet.clear();
  }
  outSheet.getRange(1, 1, 1, FINAL_ESTIMATE_HEADERS.length).setValues([FINAL_ESTIMATE_HEADERS])
    .setFontWeight('bold').setBackground('#d9ead3');
  outSheet.setFrozenRows(1);

  // メタ
  outSheet.getRange(2, 1).setValue('【総括】').setFontWeight('bold');
  outSheet.getRange(2, 2).setValue(String(parsed.summary || '').slice(0, 500));
  outSheet.getRange(2, 1, 1, FINAL_ESTIMATE_HEADERS.length).setBackground('#f3f3f3');

  if (items.length > 0) {
    const rows = items.map(function (it) {
      const qty = Number(it.quantity) || 0;
      const initial = (it.initial_unit_price == null) ? '' : Number(it.initial_unit_price);
      const final = (it.final_unit_price == null) ? '' : Number(it.final_unit_price);
      const initialTotal = (initial === '') ? '' : initial * qty;
      const finalTotal = (final === '') ? '' : final * qty;
      const delta = (initialTotal === '' || finalTotal === '') ? '' : (finalTotal - initialTotal);
      return [
        it.category || '',
        it.name || '',
        qty,
        initial,
        final,
        initialTotal,
        finalTotal,
        delta,
        it.delta_reason || ''
      ];
    });
    outSheet.getRange(3, 1, rows.length, FINAL_ESTIMATE_HEADERS.length).setValues(rows);

    // 合計行
    const totalRow = 3 + rows.length;
    let sumInitial = 0, sumFinal = 0;
    rows.forEach(function (r) {
      if (typeof r[5] === 'number') sumInitial += r[5];
      if (typeof r[6] === 'number') sumFinal += r[6];
    });
    outSheet.getRange(totalRow, 1).setValue('合計').setFontWeight('bold');
    outSheet.getRange(totalRow, 6).setValue(sumInitial).setFontWeight('bold');
    outSheet.getRange(totalRow, 7).setValue(sumFinal).setFontWeight('bold');
    outSheet.getRange(totalRow, 8).setValue(sumFinal - sumInitial).setFontWeight('bold');
    outSheet.getRange(totalRow, 1, 1, FINAL_ESTIMATE_HEADERS.length).setBackground('#fff2cc');

    // 金額カラム書式
    outSheet.getRange(3, 4, rows.length + 1, 5).setNumberFormat('#,##0');
  }

  // 列幅
  outSheet.setColumnWidth(1, 100); // カテゴリ
  outSheet.setColumnWidth(2, 240); // 品目
  outSheet.setColumnWidth(3, 60);  // 数量
  outSheet.setColumnWidth(4, 100); // 初版単価
  outSheet.setColumnWidth(5, 100); // 最終単価
  outSheet.setColumnWidth(6, 110); // 初版小計
  outSheet.setColumnWidth(7, 110); // 最終小計
  outSheet.setColumnWidth(8, 100); // 差分
  outSheet.setColumnWidth(9, 260); // 差分理由

  const sheetUrl = PanelLinks_sheetUrl(zissiSs, outSheet);

  // missing_inputs を確認シートに
  const missing = parsed.missing_inputs || [];
  if (missing.length > 0) {
    const tagged = missing.map(function (m) {
      return { category: '[最終見積/補完依頼] ' + (m.category || ''), content: m.content || '' };
    });
    ConfirmationSheet_appendItems(caseId, tagged, 6);
  }

  CaseList_touchUpdatedAt(caseId);
  MasterWriteBack_recordArtifact(caseId, '最終見積',
    '最終見積 (' + items.length + ' 品目)', sheetUrl);

  return {
    sheetUrl: sheetUrl,
    sheetName: FINAL_ESTIMATE_SHEET_NAME,
    itemCount: items.length,
    missingInputCount: missing.length,
    summary: parsed.summary || '',
    usage: res.usage
  };
}

function _Phase6_loadItemListSnippet(zissiSs) {
  try {
    const sheet = zissiSs.getSheetByName(ITEMLIST_PROPOSAL_SHEET_NAME);
    if (!sheet) return '';
    const lastRow = Math.min(sheet.getLastRow(), 200);
    if (lastRow < 2) return '';
    const data = sheet.getRange(2, 1, lastRow - 1, Math.min(sheet.getLastColumn(), 8)).getValues();
    const lines = [];
    data.forEach(function (row) {
      const text = row.map(function (v) { return String(v || '').trim(); }).filter(Boolean).join(' / ');
      if (text) lines.push(text);
    });
    return lines.join('\n');
  } catch (e) {
    return '';
  }
}

function _Phase6_loadEstimateSnippet(zissiSs) {
  // 「見積」または「管理画面」シート (案件毎の見積テンプレ)
  const sheet = _Phase6_findSheetByKeyword(zissiSs, ['管理画面', '見積', 'estimate']);
  if (!sheet) return '';
  try {
    const lastRow = Math.min(sheet.getLastRow(), 50);
    const lastCol = Math.min(sheet.getLastColumn(), 12);
    if (lastRow < 2 || lastCol < 2) return '';
    const data = sheet.getRange(1, 1, lastRow, lastCol).getValues();
    const lines = ['--- 「' + sheet.getName() + '」シート抜粋 ---'];
    data.forEach(function (row) {
      const text = row.map(function (v) { return String(v || '').trim(); }).filter(Boolean).join(' | ');
      if (text) lines.push(text);
    });
    return lines.join('\n');
  } catch (e) {
    return '';
  }
}

function _Phase6_loadCostSnippet(zissiSs) {
  // 「原価」「発注」「外注」 などのシート
  const sheets = zissiSs.getSheets();
  const candidates = [];
  for (let i = 0; i < sheets.length; i++) {
    const name = sheets[i].getName();
    if (name.indexOf('原価') >= 0 || name.indexOf('発注') >= 0 || name.indexOf('外注') >= 0 || name.indexOf('実績') >= 0) {
      candidates.push(sheets[i]);
    }
  }
  if (candidates.length === 0) return '';
  const lines = [];
  candidates.slice(0, 2).forEach(function (sh) {
    try {
      const lastRow = Math.min(sh.getLastRow(), 60);
      const lastCol = Math.min(sh.getLastColumn(), 10);
      if (lastRow < 2 || lastCol < 2) return;
      const data = sh.getRange(1, 1, lastRow, lastCol).getValues();
      lines.push('--- 「' + sh.getName() + '」シート抜粋 ---');
      data.forEach(function (row) {
        const text = row.map(function (v) { return String(v || '').trim(); }).filter(Boolean).join(' | ');
        if (text) lines.push(text);
      });
    } catch (e) {}
  });
  return lines.join('\n');
}

/**
 * Phase6: 次回向け 改善指示書 を生成。
 *
 * 目的:
 *   今回案件の振り返り（報告書・確認シート・タスク進捗）から、次回類似案件で
 *   制作チーム / 営業 / 運営 / 倉庫 などに渡す「次はこう変えよう」の指示書を作る。
 *   ハルシネーション禁止 — データ無いところは「ヒアリング要」と書く。
 *
 * 出力:
 *   Doc (改善指示書) + 「Claude_改善指示書」ナビシート + 確認シート積み上げ
 */

const IMPROVE_BRIEF_DOC_SUFFIX = '改善指示書';
const IMPROVE_BRIEF_NAV_SHEET = 'Claude_改善指示書';

function Phase6_ImprovementBrief_generate(caseId) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);

  let zissiSs = null;
  if (c.zissiId) {
    try { zissiSs = SpreadsheetApp.openById(c.zissiId); } catch (e) {}
  }
  if (!zissiSs) throw new Error('実施計画書が見つかりません。');

  // 報告書 Doc が既に作成されていれば、その内容も context に乗せる
  const reportDocText = _Phase6_loadReportDocText(zissiSs);
  const zissiSnippets = _Phase6_extractZissiSnippets(zissiSs);
  const confirmationLog = _Phase6_loadConfirmations(caseId);

  const manualPages = ManualLoader_findPages([
    '改善', '振り返り', '次回', '申し送り', 'KPT', 'デブリ'
  ]).slice(0, 8);

  const cachedContext = [
    Case_loadClientContext(c),
    '【関連マニュアル抜粋】',
    ...manualPages.map(function (p) { return '# ' + p.title + '\nパス: ' + p.path + '\n\n' + p.body; })
  ].filter(Boolean);

  const userPrompt = [
    '以下の案件を振り返り、次回類似案件の各担当 (営業 / 制作ディレクター / 施工 / 運営 / 倉庫 / 経営) に対する',
    '「改善指示書」を作成してください。',
    '',
    '## 案件情報',
    '- 案件 ID: ' + c.caseId,
    '- クライアント: ' + c.clientName,
    '- 案件名: ' + c.caseName,
    '- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate),
    '',
    '## 報告書 Doc 抜粋',
    reportDocText || '(報告書 Doc 未作成 — 先に Phase6 報告書を生成することを推奨)',
    '',
    '## 実施計画書 抜粋',
    zissiSnippets || '(該当データなし)',
    '',
    '## 確認事項ログ',
    confirmationLog || '(空)',
    '',
    '## 出力形式（厳守・JSON 単体、説明文/```json``` ブロック禁止）',
    '{',
    '  "title": "<改善指示書のタイトル>",',
    '  "improvements": [',
    '    {',
    '      "audience": "<営業 / 制作ディレクター / 施工 / 運営 / 倉庫 / 経営 のいずれか>",',
    '      "priority": "high|mid|low",',
    '      "topic": "<改善テーマ>",',
    '      "current": "<今回起きた事象・現状>",',
    '      "next_action": "<次回どうするか具体的に>",',
    '      "rationale": "<なぜそうするか>"',
    '    }',
    '  ],',
    '  "missing_inputs": [',
    '    {"category": "<不足情報のカテゴリ>", "content": "<何を確認すべきか>"}',
    '  ]',
    '}',
    '',
    '## 重要ルール',
    '- 必ず audience 別に分けて記載 (担当ごとに何をするか明確に)。',
    '- データが無い場合の推測指示は出さない。「ヒアリング要」「再現性のあるデータがそろえば判断可能」等と書く。',
    '- priority は事故防止/コスト/利益への影響度で判定。曖昧なら mid。',
    '- 件数の下限なし。本当に改善点が見当たらない場合は missing_inputs にデータ不足を列挙。',
    '- ハルシネーション禁止。'
  ].join('\n');

  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    maxTokens: 6000
  });

  const parsed = _Phase1_parseJson(res.text);
  const title = parsed.title || (c.caseName + ' 改善指示書');
  const improvements = parsed.improvements || [];

  // Doc 生成
  const folderId = c.projectFolderId || c.folderId;
  const docName = c.caseId + '_' + c.caseName + '_' + IMPROVE_BRIEF_DOC_SUFFIX + '_初版';
  const doc = DocumentApp.create(docName);
  const body = doc.getBody();
  body.appendParagraph(title).setHeading(DocumentApp.ParagraphHeading.TITLE);
  body.appendParagraph('案件 ID: ' + c.caseId + ' / 生成日: ' + Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy/MM/dd HH:mm'))
    .setItalic(true);
  body.appendHorizontalRule();

  // audience 別にグルーピング
  const grouped = {};
  improvements.forEach(function (it) {
    const a = it.audience || 'その他';
    if (!grouped[a]) grouped[a] = [];
    grouped[a].push(it);
  });
  const audienceOrder = ['営業', '制作ディレクター', '施工', '運営', '倉庫', '経営', 'その他'];
  audienceOrder.forEach(function (aud) {
    const items = grouped[aud];
    if (!items || items.length === 0) return;
    body.appendParagraph('■ ' + aud).setHeading(DocumentApp.ParagraphHeading.HEADING2);
    // priority 順
    const rank = { high: 0, mid: 1, low: 2 };
    items.sort(function (a, b) { return (rank[a.priority] || 9) - (rank[b.priority] || 9); });
    items.forEach(function (it) {
      body.appendParagraph('● [' + (it.priority || '') + '] ' + (it.topic || ''))
        .setHeading(DocumentApp.ParagraphHeading.HEADING3);
      body.appendParagraph('現状: ' + (it.current || ''));
      body.appendParagraph('次回アクション: ' + (it.next_action || ''));
      if (it.rationale) body.appendParagraph('根拠: ' + it.rationale);
    });
  });
  // audience 別の漏れ (audienceOrder に無いカテゴリ)
  Object.keys(grouped).forEach(function (aud) {
    if (audienceOrder.indexOf(aud) >= 0) return;
    body.appendParagraph('■ ' + aud).setHeading(DocumentApp.ParagraphHeading.HEADING2);
    grouped[aud].forEach(function (it) {
      body.appendParagraph('● [' + (it.priority || '') + '] ' + (it.topic || ''))
        .setHeading(DocumentApp.ParagraphHeading.HEADING3);
      body.appendParagraph('現状: ' + (it.current || ''));
      body.appendParagraph('次回アクション: ' + (it.next_action || ''));
      if (it.rationale) body.appendParagraph('根拠: ' + it.rationale);
    });
  });

  doc.saveAndClose();
  if (folderId) {
    try { DriveApp.getFileById(doc.getId()).moveTo(DriveApp.getFolderById(folderId)); } catch (e) {}
  }
  const docUrl = DocumentApp.openById(doc.getId()).getUrl();

  // ナビ用シート
  let navSheet = zissiSs.getSheetByName(IMPROVE_BRIEF_NAV_SHEET);
  if (!navSheet) {
    try { navSheet = zissiSs.insertSheet(IMPROVE_BRIEF_NAV_SHEET); }
    catch (e) { navSheet = zissiSs.getSheetByName(IMPROVE_BRIEF_NAV_SHEET); }
  } else {
    navSheet.clear();
  }
  navSheet.getRange(1, 1).setValue('改善指示書 Doc URL').setFontWeight('bold');
  navSheet.getRange(1, 2).setValue(docUrl);
  navSheet.getRange(2, 1).setValue('指摘件数').setFontWeight('bold');
  navSheet.getRange(2, 2).setValue(improvements.length);
  navSheet.getRange(3, 1).setValue('生成日時').setFontWeight('bold');
  navSheet.getRange(3, 2).setValue(Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy/MM/dd HH:mm'));
  navSheet.setColumnWidth(1, 140);
  navSheet.setColumnWidth(2, 500);

  // missing_inputs を確認シートに積む
  const missing = parsed.missing_inputs || [];
  if (missing.length > 0) {
    const tagged = missing.map(function (m) {
      return { category: '[改善指示書/補完依頼] ' + (m.category || ''), content: m.content || '' };
    });
    ConfirmationSheet_appendItems(caseId, tagged, 6);
  }

  CaseList_touchUpdatedAt(caseId);
  MasterWriteBack_recordArtifact(caseId, '改善指示書', title, docUrl);

  return {
    docUrl: docUrl,
    docName: docName,
    title: title,
    improvementCount: improvements.length,
    audiences: Object.keys(grouped),
    missingInputCount: missing.length,
    manualPagesUsed: manualPages.length,
    usage: res.usage
  };
}

function _Phase6_loadReportDocText(zissiSs) {
  // 「Claude_報告書」ナビシートに Doc URL があれば、その Doc のテキストを返す
  try {
    const navSheet = zissiSs.getSheetByName(POST_REPORT_NAV_SHEET);
    if (!navSheet) return '';
    const url = String(navSheet.getRange(1, 2).getValue() || '').trim();
    const m = url.match(/\/document\/d\/([A-Za-z0-9_-]+)/);
    if (!m) return '';
    const doc = DocumentApp.openById(m[1]);
    const text = doc.getBody().getText();
    return text.length > 8000 ? text.slice(0, 8000) + '\n...(以下省略)' : text;
  } catch (e) {
    return '';
  }
}

/**
 * Phase6: 案件終了後の報告書 を生成。
 *
 * 目的:
 *   案件が完了した後、社内共有 + クライアント送付の元ネタとなる報告書を Claude にまとめさせる。
 *   実施計画書内の「報告」シート / 確認シート / Claude 生成物の URL を context として渡し、
 *   ハルシネーション禁止ルールに従って既知情報のみで構成させる。
 *
 * 出力:
 *   - Google Doc (case フォルダ配下)
 *   - 「Claude_報告書」シート(同 zissi 内、ナビゲーション用に URL を貼る)
 *   - 確認シートへの未確認項目 (KPI 数値未記入 等) の積み上げ
 */

const POST_REPORT_DOC_SUFFIX = '報告書';
const POST_REPORT_NAV_SHEET = 'Claude_報告書';

function Phase6_PostReport_generate(caseId) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);

  // 実施計画書
  let zissiSs = null;
  if (c.zissiId) {
    try { zissiSs = SpreadsheetApp.openById(c.zissiId); } catch (e) {}
  }
  if (!zissiSs) throw new Error('実施計画書が見つかりません。');

  // 実施計画書内の主要シートから snippet 抽出
  const zissiSnippets = _Phase6_extractZissiSnippets(zissiSs);

  // 確認シートの内容
  const confirmationLog = _Phase6_loadConfirmations(caseId);

  // 既に生成した Claude 成果物の URL リスト (Claude生成物 シート参照)
  const artifactLog = _Phase6_loadArtifactList(zissiSs);

  // マニュアル抜粋 (報告書テンプレートが定義されていれば参照)
  const manualPages = ManualLoader_findPages([
    '報告書', '実績', '振り返り', 'デブリーフィング', '案件終了'
  ]).slice(0, 10);

  const cachedContext = [
    Case_loadClientContext(c),
    '【関連マニュアル抜粋】',
    ...manualPages.map(function (p) { return '# ' + p.title + '\nパス: ' + p.path + '\n\n' + p.body; })
  ].filter(Boolean);

  const userPrompt = [
    '以下の展示会ブース案件について、終了後の報告書を作成してください。',
    '',
    '## 案件情報',
    '- 案件 ID: ' + c.caseId,
    '- クライアント: ' + c.clientName,
    '- 案件名: ' + c.caseName,
    '- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate),
    '- ブースサイズ: ' + (c.boothSize || '未記入'),
    '',
    '## 実施計画書から抽出した主要情報',
    zissiSnippets || '(該当データなし)',
    '',
    '## 確認事項ログ',
    confirmationLog || '(確認シート空)',
    '',
    '## 生成済み Claude 成果物',
    artifactLog || '(なし)',
    '',
    '## 出力形式（厳守・JSON 単体、説明文/```json``` ブロック禁止）',
    '{',
    '  "title": "<報告書のタイトル>",',
    '  "sections": [',
    '    {"heading": "案件概要", "body": "<本文>"},',
    '    {"heading": "実施内容のサマリ", "body": "<本文>"},',
    '    {"heading": "成功要因 / 良かった点", "body": "<本文>"},',
    '    {"heading": "課題・改善点", "body": "<本文>"},',
    '    {"heading": "クライアントからのフィードバック", "body": "<本文。データに無い場合は「ヒアリング待ち」と書く>"},',
    '    {"heading": "数値実績", "body": "<予算/原価/工数 等。データに無い数値は「未記入」と書く>"},',
    '    {"heading": "次回への申し送り", "body": "<本文>"}',
    '  ],',
    '  "missing_inputs": [',
    '    {"category": "<KPI / フィードバック 等のカテゴリ>", "content": "<確認したい/補ってほしい内容>"}',
    '  ]',
    '}',
    '',
    '## 重要ルール',
    '- 上記コンテキストに **明示的に書かれている事実のみ** を本文に記載すること。',
    '- 数値・社名・人名・成果 等で確証がないものは「未記入」「ヒアリング待ち」「要確認」と書き、絶対に推測で埋めない。',
    '- ハルシネーションは禁止。空欄や未確定情報は missing_inputs に列挙する。',
    '- 文体は社内共有の体裁 (です/ます調)。',
    '- 各 body は箇条書きと段落を適切に混在させ、500 字以内を目安に。'
  ].join('\n');

  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    maxTokens: 6000
  });

  const parsed = _Phase1_parseJson(res.text);
  const title = parsed.title || (c.caseName + ' 報告書');
  const sections = parsed.sections || [];

  // Google Doc 生成
  const folderId = Case_resolveProjectRoot(c);
  const docName = c.caseId + '_' + c.caseName + '_' + POST_REPORT_DOC_SUFFIX + '_初版';
  const doc = DocumentApp.create(docName);
  const body = doc.getBody();
  body.appendParagraph(title).setHeading(DocumentApp.ParagraphHeading.TITLE);
  body.appendParagraph('案件 ID: ' + c.caseId + ' / 生成日: ' + Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy/MM/dd HH:mm'))
    .setItalic(true);
  body.appendHorizontalRule();
  sections.forEach(function (sec) {
    body.appendParagraph(sec.heading || '').setHeading(DocumentApp.ParagraphHeading.HEADING2);
    body.appendParagraph(sec.body || '');
  });
  doc.saveAndClose();
  if (folderId) {
    try { DriveApp.getFileById(doc.getId()).moveTo(DriveApp.getFolderById(folderId)); } catch (e) {}
  }
  const docUrl = DocumentApp.openById(doc.getId()).getUrl();

  // ナビ用シート (zissi 内に URL を貼っておくと bound から開きやすい)
  let navSheet = zissiSs.getSheetByName(POST_REPORT_NAV_SHEET);
  if (!navSheet) {
    try { navSheet = zissiSs.insertSheet(POST_REPORT_NAV_SHEET); }
    catch (e) { navSheet = zissiSs.getSheetByName(POST_REPORT_NAV_SHEET); }
  } else {
    navSheet.clear();
  }
  navSheet.getRange(1, 1).setValue('報告書 Doc URL').setFontWeight('bold');
  navSheet.getRange(1, 2).setValue(docUrl);
  navSheet.getRange(2, 1).setValue('生成日時').setFontWeight('bold');
  navSheet.getRange(2, 2).setValue(Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy/MM/dd HH:mm'));
  navSheet.getRange(3, 1).setValue('タイトル').setFontWeight('bold');
  navSheet.getRange(3, 2).setValue(title);
  navSheet.setColumnWidth(1, 140);
  navSheet.setColumnWidth(2, 500);

  // missing_inputs を確認シートに積む
  const missing = parsed.missing_inputs || [];
  if (missing.length > 0) {
    const tagged = missing.map(function (m) {
      return { category: '[報告書/補完依頼] ' + (m.category || ''), content: m.content || '' };
    });
    ConfirmationSheet_appendItems(caseId, tagged, 6);
  }

  CaseList_touchUpdatedAt(caseId);
  MasterWriteBack_recordArtifact(caseId, '報告書', title, docUrl);

  return {
    docUrl: docUrl,
    docName: docName,
    title: title,
    sectionCount: sections.length,
    missingInputCount: missing.length,
    manualPagesUsed: manualPages.length,
    usage: res.usage
  };
}

function _Phase6_extractZissiSnippets(zissiSs) {
  const lines = [];
  // 「報告」シートがあれば上位 30 行
  const reportSheet = _Phase6_findSheetByKeyword(zissiSs, ['報告', 'デブリ', 'デブリーフ']);
  if (reportSheet) {
    const lastRow = Math.min(reportSheet.getLastRow(), 30);
    const lastCol = Math.min(reportSheet.getLastColumn(), 8);
    if (lastRow > 0 && lastCol > 0) {
      const data = reportSheet.getRange(1, 1, lastRow, lastCol).getValues();
      lines.push('--- 「' + reportSheet.getName() + '」シート抜粋 ---');
      data.forEach(function (row) {
        const nonEmpty = row.filter(function (v) { return String(v || '').trim(); });
        if (nonEmpty.length > 0) lines.push(nonEmpty.join(' | '));
      });
    }
  }
  // 「task」シートで残タスク / 完了率の手がかり
  const taskSheet = _Phase6_findSheetByKeyword(zissiSs, ['task', 'Task', 'タスク']);
  if (taskSheet) {
    try {
      const summary = taskSheet.getRange(1, 1, 5, Math.min(taskSheet.getLastColumn(), 10)).getValues();
      lines.push('--- 「' + taskSheet.getName() + '」シート上部 ---');
      summary.forEach(function (row) {
        const nonEmpty = row.filter(function (v) { return String(v || '').trim(); });
        if (nonEmpty.length > 0) lines.push(nonEmpty.join(' | '));
      });
    } catch (e) {}
  }
  return lines.join('\n');
}

function _Phase6_findSheetByKeyword(ss, keywords) {
  const sheets = ss.getSheets();
  for (let i = 0; i < sheets.length; i++) {
    const name = sheets[i].getName();
    for (let j = 0; j < keywords.length; j++) {
      if (name.indexOf(keywords[j]) >= 0) return sheets[i];
    }
  }
  return null;
}

function _Phase6_loadConfirmations(caseId) {
  try {
    const c = CaseList_getById(caseId);
    if (!c || !c.zissiId) return '';
    const ss = SpreadsheetApp.openById(c.zissiId);
    const sheet = ss.getSheetByName('確認') || _Phase6_findSheetByKeyword(ss, ['確認事項']);
    if (!sheet) return '';
    const lastRow = Math.min(sheet.getLastRow(), 100);
    if (lastRow < 2) return '';
    const data = sheet.getRange(2, 1, lastRow - 1, Math.min(sheet.getLastColumn(), 6)).getValues();
    const lines = [];
    data.forEach(function (row) {
      const text = row.map(function (v) { return String(v || '').trim(); }).filter(Boolean).join(' / ');
      if (text) lines.push(text);
    });
    return lines.join('\n');
  } catch (e) {
    return '';
  }
}

function _Phase6_loadArtifactList(zissiSs) {
  try {
    const sheet = zissiSs.getSheetByName('Claude生成物');
    if (!sheet) return '';
    const lastRow = sheet.getLastRow();
    if (lastRow < 2) return '';
    const data = sheet.getRange(2, 1, lastRow - 1, Math.min(sheet.getLastColumn(), 6)).getValues();
    const lines = [];
    data.forEach(function (row) {
      const text = row.map(function (v) { return String(v || '').trim(); }).filter(Boolean).join(' / ');
      if (text) lines.push(text);
    });
    return lines.join('\n');
  } catch (e) {
    return '';
  }
}

/**
 * Phase6: スタッフ評価 を生成。
 *
 * 目的:
 *   案件で動いたメンバー (制作 D、運営、施工、ドライバー、外注パートナー) について
 *   タスク完了率・確認事項対応・現場 incident をもとに「事実ベースのレビュー素材」を作る。
 *   人事評価そのものではなく、評価会議に持ち込む素材としてのドラフト。
 *   ハルシネーション禁止 — 推測の人格評価は禁止、行動事実のみ。
 *
 * 出力:
 *   zissi 内「Claude_スタッフ評価」シート + 確認シート積み上げ
 */

const STAFF_EVAL_SHEET_NAME = 'Claude_スタッフ評価';
const STAFF_EVAL_HEADERS = ['担当', '役割', '良かった行動 (事実)', '改善余地 (事実)', '次回への期待', 'データ充足度'];

function Phase6_StaffEval_generate(caseId) {
  const c = CaseList_getById(caseId);
  if (!c) throw new Error('案件が見つかりません: ' + caseId);

  let zissiSs = null;
  if (c.zissiId) {
    try { zissiSs = SpreadsheetApp.openById(c.zissiId); } catch (e) {}
  }
  if (!zissiSs) throw new Error('実施計画書が見つかりません。');

  // タスク進捗 / 確認事項 / 報告書 を context にする
  const taskSnippet = _Phase6_loadTaskAssigneeSnippet(zissiSs);
  const confirmationLog = _Phase6_loadConfirmations(caseId);
  const reportDocText = _Phase6_loadReportDocText(zissiSs);

  const manualPages = ManualLoader_findPages([
    'スタッフ評価', '評価', '人事', 'KPI'
  ]).slice(0, 5);

  const cachedContext = [
    Case_loadClientContext(c),
    '【関連マニュアル抜粋】',
    ...manualPages.map(function (p) { return '# ' + p.title + '\nパス: ' + p.path + '\n\n' + p.body; })
  ].filter(Boolean);

  const userPrompt = [
    '以下の案件で動いたメンバーについて、評価会議用の「事実ベースのレビュー素材」を作成してください。',
    '人格評価・推測の性格描写は絶対に書かないこと。事実（タスク完了/未完、確認事項対応、現場記録）に基づく事象のみ書く。',
    '',
    '## 案件情報',
    '- 案件 ID: ' + c.caseId,
    '- クライアント: ' + c.clientName,
    '- 案件名: ' + c.caseName,
    '- 出展期間: ' + _fmtDate(c.startDate) + ' 〜 ' + _fmtDate(c.endDate),
    '',
    '## タスク進捗（担当別抜粋）',
    taskSnippet || '(taskシート無し or 担当列空)',
    '',
    '## 確認事項ログ',
    confirmationLog || '(空)',
    '',
    '## 報告書 Doc 抜粋',
    reportDocText || '(報告書未生成)',
    '',
    '## 出力形式（厳守・JSON 単体、説明文/```json``` ブロック禁止）',
    '{',
    '  "members": [',
    '    {',
    '      "name": "<担当者名 (タスク表記のまま)>",',
    '      "role": "<役割: 制作ディレクター / 営業 / 運営 / 施工 / ドライバー / 外注パートナー>",',
    '      "positive_actions": "<事実として観察できた良かった行動。データから引用>",',
    '      "improvement_areas": "<事実として観察できた改善余地。データから引用>",',
    '      "next_expectation": "<次回への期待を 1〜2 文>",',
    '      "data_sufficiency": "high|mid|low"',
    '    }',
    '  ],',
    '  "missing_inputs": [',
    '    {"category": "<カテゴリ>", "content": "<不足情報>"}',
    '  ]',
    '}',
    '',
    '## 厳守ルール',
    '- 人格 (例: 「真面目」「気が利く」「やる気がある」) を書かない。**事実描写のみ** (例: 「タスクA, B, C を期日内完了」「確認事項#5 への返信が 3 日遅延」)。',
    '- データに登場しないメンバーは含めない。',
    '- データから observable な行動が無い場合は data_sufficiency=low、positive_actions/improvement_areas に「観察可能データなし」と書く。',
    '- 推測で「次回はこう改善できそう」と書かない。事実から導けるアクションだけ next_expectation に書く。',
    '- ハルシネーション禁止。'
  ].join('\n');

  const res = ClaudeClient_call({
    cachedContext: cachedContext,
    userMessage: userPrompt,
    maxTokens: 6000
  });

  const parsed = _Phase1_parseJson(res.text);
  const members = parsed.members || [];

  let outSheet = zissiSs.getSheetByName(STAFF_EVAL_SHEET_NAME);
  if (!outSheet) {
    try { outSheet = zissiSs.insertSheet(STAFF_EVAL_SHEET_NAME); }
    catch (e) { outSheet = zissiSs.getSheetByName(STAFF_EVAL_SHEET_NAME); }
  } else {
    outSheet.clear();
  }
  outSheet.getRange(1, 1, 1, STAFF_EVAL_HEADERS.length).setValues([STAFF_EVAL_HEADERS])
    .setFontWeight('bold').setBackground('#cfe2f3');
  outSheet.setFrozenRows(1);

  // 注意書き行
  outSheet.getRange(2, 1).setValue('※ Claude による事実ベースのドラフトです。最終評価は会議で判断してください。')
    .setFontStyle('italic');
  outSheet.getRange(2, 1, 1, STAFF_EVAL_HEADERS.length).merge().setBackground('#fff2cc');

  if (members.length > 0) {
    const rows = members.map(function (m) {
      return [
        m.name || '',
        m.role || '',
        m.positive_actions || '',
        m.improvement_areas || '',
        m.next_expectation || '',
        m.data_sufficiency || ''
      ];
    });
    outSheet.getRange(3, 1, rows.length, STAFF_EVAL_HEADERS.length).setValues(rows);
    // data_sufficiency 色付け
    for (let i = 0; i < members.length; i++) {
      const ds = members[i].data_sufficiency;
      const bg = ds === 'high' ? '#d9ead3' : ds === 'mid' ? '#fff2cc' : '#f4cccc';
      outSheet.getRange(3 + i, 6).setBackground(bg);
    }
  }

  outSheet.setColumnWidth(1, 130); // 担当
  outSheet.setColumnWidth(2, 140); // 役割
  outSheet.setColumnWidth(3, 300); // 良かった
  outSheet.setColumnWidth(4, 300); // 改善余地
  outSheet.setColumnWidth(5, 240); // 次回期待
  outSheet.setColumnWidth(6, 100); // データ充足度
  outSheet.getRange(1, 1, outSheet.getMaxRows(), STAFF_EVAL_HEADERS.length).setWrap(true);

  const sheetUrl = PanelLinks_sheetUrl(zissiSs, outSheet);

  // missing_inputs を確認シートに
  const missing = parsed.missing_inputs || [];
  if (missing.length > 0) {
    const tagged = missing.map(function (m) {
      return { category: '[スタッフ評価/補完依頼] ' + (m.category || ''), content: m.content || '' };
    });
    ConfirmationSheet_appendItems(caseId, tagged, 6);
  }

  CaseList_touchUpdatedAt(caseId);
  MasterWriteBack_recordArtifact(caseId, 'スタッフ評価',
    'スタッフ評価 (' + members.length + ' 名)', sheetUrl);

  return {
    sheetUrl: sheetUrl,
    sheetName: STAFF_EVAL_SHEET_NAME,
    memberCount: members.length,
    missingInputCount: missing.length,
    usage: res.usage
  };
}

function _Phase6_loadTaskAssigneeSnippet(zissiSs) {
  const sheet = _Phase6_findSheetByKeyword(zissiSs, ['task', 'Task', 'タスク']);
  if (!sheet) return '';
  try {
    const lastRow = Math.min(sheet.getLastRow(), 500);
    const lastCol = Math.min(sheet.getLastColumn(), 15);
    if (lastRow < 2 || lastCol < 2) return '';
    const data = sheet.getRange(1, 1, lastRow, lastCol).getValues();
    // 担当者ごとに完了/未完を集計
    const byAssignee = {};
    let assigneeCol = -1;
    let statusCol = -1;
    let itemCol = -1;
    // header row 推定: 1〜5 行目に「担当」「進捗」「項目」 等の列名を探す
    for (let r = 0; r < Math.min(8, data.length); r++) {
      for (let cc = 0; cc < lastCol; cc++) {
        const v = String(data[r][cc] || '');
        if ((v.indexOf('担当') >= 0 || v.indexOf('名前') >= 0 || v.indexOf('分担') >= 0) && assigneeCol < 0) assigneeCol = cc;
        if ((v.indexOf('進捗') >= 0 || v.indexOf('ステータス') >= 0 || v.indexOf('完了') >= 0) && statusCol < 0) statusCol = cc;
        if ((v.indexOf('項目') >= 0 || v.indexOf('タスク') >= 0) && itemCol < 0) itemCol = cc;
      }
    }
    if (assigneeCol < 0) return '(担当列を特定できず)';

    for (let r = 0; r < data.length; r++) {
      const a = String(data[r][assigneeCol] || '').trim();
      if (!a || a === '名前' || a === '担当' || a === '分担') continue;
      const status = statusCol >= 0 ? String(data[r][statusCol] || '').trim() : '';
      const item = itemCol >= 0 ? String(data[r][itemCol] || '').trim() : '';
      if (!byAssignee[a]) byAssignee[a] = { total: 0, done: 0, undone: 0, samples: [] };
      byAssignee[a].total++;
      const isDone = status === '済' || status === '完了' || status === 'done';
      const isUndone = status === '未着手' || status === '進行中';
      if (isDone) byAssignee[a].done++;
      if (isUndone) byAssignee[a].undone++;
      if (byAssignee[a].samples.length < 3 && item) byAssignee[a].samples.push(item);
    }

    const lines = [];
    Object.keys(byAssignee).forEach(function (a) {
      const s = byAssignee[a];
      lines.push('- ' + a + ': 計 ' + s.total + ' 件 (完了 ' + s.done + ' / 未/進行 ' + s.undone + ')。代表タスク: ' + s.samples.join(' / '));
    });
    return lines.join('\n');
  } catch (e) {
    return '';
  }
}

