function TaskLedger_autoRunNightly() {
  var started = _TaskLedger_nowMs(), cases = TaskLedger_activeCaseIds(), errors = [], candidates = [];
  cases.forEach(function (caseId) {
    try {
      TaskLedger_readRows(caseId).rows.forEach(function (row) {
